	private void checkAttachedGroupedLateralCaller(List<Boolean> variants, boolean requireNative) {
		String uri = "urn:attached-group:lateral";
		Value local = literal("local");
		Value other = literal("other");
		List<Value> arguments = new ArrayList<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				arguments.add(args[0]);
				return new CloseableIteratorIteration<>(List.<List<? extends Value>>of(List.of(local), List.of(local))
						.iterator());
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Group group = new Group(new Lateral(new SingletonSet(), call, Set.of("x")), List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryRoot root = new QueryRoot(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			Group unobservedGroup = group.clone();
			unobservedGroup.setRuntimeTelemetryEnabled(true);
			unobservedGroup.setExecutionSummaryEnabled(true);
			QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(new QueryRoot(unobservedGroup), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(root, context);
			assertThat(root.getArg()).as("the Group occurrence remains attached to its actual root").isSameAs(group);
			for (boolean matching : variants) {
				Value inputValue = matching ? local : other;
				String label = inputValue.equals(local) ? "matching" : "conflicting";
				QueryBindingSet caller = new QueryBindingSet();
				caller.addBinding("x", inputValue);
				GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
				List<Map<String, Value>> expected = inputValue.equals(local)
						? List.of(row("x", local, "count", groupInteger(2)))
						: List.of();
				arguments.clear();
				try (var rows = generic.evaluate(caller)) {
					assertThat(mappings(rows)).as("generic attached LATERAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				assertThat(arguments).as("generic tuple arguments %s", label).containsExactly(inputValue);
				assertThat(groupEntryFacts(caller, group, null)).as("generic caller unchanged %s", label)
						.isEqualTo(callerBefore);
				arguments.clear();
				long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
				try (var rows = unobserved.evaluate(caller)) {
					assertThat(mappings(rows)).as("unobserved attached LATERAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				assertThat(arguments).as("unobserved tuple arguments %s", label).containsExactly(inputValue);
				assertThat(groupEntryFacts(caller, group, null)).as("unobserved caller unchanged %s", label)
						.isEqualTo(callerBefore);
				arguments.clear();
				int entriesBefore = probe.entries.size();
				long nativeBefore = resetAttachedGroupMetrics(group);
				try (var rows = selected.evaluate(caller)) {
					assertThat(mappings(rows)).as("selected attached LATERAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				assertThat(arguments).as("selected tuple arguments %s", label).containsExactly(inputValue);
				AttachedGroupEntry entry = probe.onlyEntrySince(entriesBefore, label);
				assertThat(entry.bindings().getValue("x")).as("actual Group caller %s", label).isEqualTo(inputValue);
				assertThat(BindingFrameBindings.substitutionDomain(entry.bindings()))
						.as("root caller has no manufactured EXISTS domain %s", label)
						.isNull();
				assertAttachedGroupRoute(group, entry, nativeBefore, "lateral " + label);
				assertUnobservedGroupRoute(unobservedGroup, unobservedBefore, group, entry, nativeBefore, label);
				assertThat(groupEntryFacts(caller, group, null)).as("selected caller unchanged %s", label)
						.isEqualTo(callerBefore);
				if (requireNative) {
					assertAttachedNativeGroup(group, entry, nativeBefore, unobservedGroup, unobservedBefore, label);
				}
			}
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

