	@ParameterizedTest(name = "matching={0}")
	@ValueSource(booleans = { true, false })
	void nestedGroupedLateralComposesItsConditionalBranchWitness(boolean matching) {
		String uri = "urn:attached-group:nested-branch";
		Value local = literal("local");
		Value token = literal("parameter");
		Value first = literal("first");
		Value second = literal("second");
		Value label = literal("fresh label");
		List<List<Value>> callbacks = new ArrayList<>();
		TupleFunction function = groupBranchFunction(uri, local, 1, callbacks);
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("parameter"));
			call.addArg(Var.of("sequence"));
			call.addResultVar(Var.of("x"));
			Lateral inner = new Lateral(values("sequence", first, first, second), call,
					Set.of("parameter", "sequence", "x"));
			Extension extension = new Extension(inner, new ExtensionElem(new ValueConstant(label), "label"));
			Lateral outer = new Lateral(new SingletonSet(), extension, Set.of("parameter", "x"));
			Group group = new Group(outer, List.of("x", "label"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			GroupBranchHosts hosts = prepareGroupBranchHosts(dataset, group);
			QueryBindingSet caller = new QueryBindingSet();
			caller.setBinding("parameter", token);
			caller.setBinding("x", matching ? local : literal("other"));
			GroupBranchObservation observation = observeGroupBranch(hosts, outer, call, caller, callbacks, "nested");
			List<Map<String, Value>> expected = matching
					? List.of(row("parameter", token, "x", local, "label", label, "count", groupInteger(3)))
					: List.of();
			List<List<Value>> expectedCalls = List.of(List.of(token, first), List.of(token, first),
					List.of(token, second));
			SoftAssertions softly = new SoftAssertions();
			assertGroupBranchEffects(softly, hosts, observation, expected, expectedCalls);
			softly.assertThat(observation.facts().substitutionDomain()).isNull();
			softly.assertThat(observation.facts().logicalNames()).containsExactly("parameter", "x");
			softly.assertThat(observation.facts().seededNames()).containsExactly("x");
			softly.assertThat(observation.facts().cells().get("parameter"))
					.isEqualTo(new GroupAdmissionCell(true, true, token));
			softly.assertThat(observation.facts().cells().get("sequence"))
					.isEqualTo(new GroupAdmissionCell(false, false, null));
			softly.assertThat(observation.facts().wholeSeededInjection()).isFalse();
			softly.assertThat(observation.step().arg).isInstanceOf(LateralPlan.class);
			if (observation.step().arg instanceof LateralPlan outerPlan) {
				softly.assertThat(outerPlan.left).isInstanceOf(SingletonPlan.class);
				softly.assertThat(outerPlan.semanticEntry).isNotNull();
				softly.assertThat(outerPlan.ownerInput).isNull();
				softly.assertThat(outerPlan.right).isInstanceOf(ExtensionPlan.class);
				if (outerPlan.right instanceof ExtensionPlan extensionPlan) {
					softly.assertThat(extensionPlan.arg).isInstanceOf(LateralPlan.class);
					if (extensionPlan.arg instanceof LateralPlan innerPlan) {
						softly.assertThat(innerPlan.left).isInstanceOf(ValuesPlan.class);
						softly.assertThat(innerPlan.right).isInstanceOf(TupleFunctionPlan.class);
						softly.assertThat(innerPlan.semanticEntry).isNotNull();
						softly.assertThat(innerPlan.ownerInput).isNull();
					}
				}
			}
			QueryAlgebraBindingAnalysis analysis = groupBranchAnalysis(outer);
			var outerTransition = analysis.semanticInvocationTransition(outer);
			var extensionTransition = analysis.semanticInvocationTransition(extension);
			var innerTransition = analysis.semanticInvocationTransition(inner);
			softly.assertThat(outerTransition).isNotNull();
			softly.assertThat(extensionTransition).isNotNull();
			softly.assertThat(innerTransition).isNotNull();
			softly.assertThat(analysis.semanticInvocationTransition(call)).isNotNull();
			if (outerTransition != null && extensionTransition != null && innerTransition != null) {
				softly.assertThat(outerTransition.occurrence()).isSameAs(outer);
				softly.assertThat(outerTransition.children()).containsExactly(outer.getLeftArg(), extension);
				softly.assertThat(extensionTransition.occurrence()).isSameAs(extension);
				softly.assertThat(extensionTransition.children()).containsExactly(inner);
				softly.assertThat(innerTransition.occurrence()).isSameAs(inner);
				softly.assertThat(innerTransition.children()).containsExactly(inner.getLeftArg(), call);
			}
			softly.assertThat(QueryEvaluationUtility.isRepeatable(extension.getElements().getFirst().getExpr()))
					.isTrue();
			softly.assertThat(
					QueryEvaluationUtility.canDiscardWithoutEvaluation(extension.getElements().getFirst().getExpr()))
					.isTrue();
			softly.assertThat(caller.hasBinding("label")).as("the constant assignment is fresh").isFalse();
			assertGroupBranchNative(softly, observation);
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	@ParameterizedTest(name = "EXISTS marker present={0}")
	@ValueSource(booleans = { false, true })
	void groupedLateralDeclinesOnlyItsDirectBranchForIssuedSubstitutionDomains(boolean markerPresent) {
		String uri = "urn:attached-group:issued-domain";
		Value local = literal("local");
		Value token = literal("parameter");
		Value marker = literal("marker");
		List<List<Value>> callbacks = new ArrayList<>();
		TupleFunction function = groupBranchFunction(uri, local, 2, callbacks);
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			Group sourceGroup = new Group(new LeftJoin(new SingletonSet(), values("marker", marker)),
					List.of("marker"));
			Exists exists = new Exists(sourceGroup);
			QueryEvaluationUtility.ExistsSubstitutionInputs requirements = QueryEvaluationUtility
					.existsSubstitutionInputs(sourceGroup);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf(
						"group-branch-source-contract markerPresent=%s groupNames=%s aggregates=%d requirements=%s%n",
						markerPresent, sourceGroup.getGroupBindingNames(), sourceGroup.getGroupElements().size(),
						requirements);
			}
			assertThat(requirements.unknown()).as("the producer has a complete substitution contract").isFalse();
			assertThat(requirements.bindingNames()).containsExactly("marker");
			assertThat(requirements.needsDynamicDomain()).isTrue();
			QueryValueEvaluationStep sourceGeneric = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new Exists(sourceGroup.clone()), context);
			QueryValueEvaluationStep sourceUnobserved = groupEmissionStrategy(dataset)
					.precompile(new Exists(sourceGroup.clone()), context);
			LmdbNativeEvaluationStrategy sourceStrategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe sourceProbe = new AttachedGroupProbe(sourceStrategy, sourceGroup);
			QueryValueEvaluationStep sourceSelected = sourceStrategy.precompile(exists, context);
			QueryBindingSet caller = new QueryBindingSet();
			caller.setBinding("x", local);
			caller.setBinding("parameter", token);
			if (markerPresent) {
				caller.setBinding("marker", marker);
			}
			GroupEntryFacts sourceCallerBefore = groupEntryFacts(caller, sourceGroup, null);
			for (QueryValueEvaluationStep step : List.of(sourceGeneric, sourceUnobserved, sourceSelected)) {
				assertThat(step.evaluate(caller)).as("the real EXISTS producer returns true")
						.isEqualTo(VF.createLiteral(true));
			}
			AttachedGroupEntry sourceEntry = sourceProbe.onlyEntrySince(0, "issued substitution domain");
			BindingSet issued = sourceEntry.bindings();
			Set<String> expectedDomain = markerPresent ? Set.of("marker") : Set.of();
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("group-branch-source markerPresent=%s dynamic=%s domain=%s logical=%s%n",
						markerPresent,
						sourceEntry.dynamicContext(), BindingFrameBindings.substitutionDomain(issued),
						issued.getBindingNames());
			}
			assertThat(exists.getSubQuery()).isSameAs(sourceGroup);
			assertThat(sourceEntry.dynamicContext()).isTrue();
			assertThat(BindingFrameBindings.hasFrame(issued)).isTrue();
			assertThat(BindingFrameBindings.substitutionDomain(issued)).isNotNull().isEqualTo(expectedDomain);
			assertThat(issued.getBindingNames()).containsExactlyInAnyOrderElementsOf(caller.getBindingNames());
			assertThat(issued.getValue("x")).isEqualTo(local);
			assertThat(issued.getValue("parameter")).isEqualTo(token);
			assertThat(issued.hasBinding("marker")).isEqualTo(markerPresent);
			assertThat(issued.getValue("marker")).isEqualTo(markerPresent ? marker : null);
			assertThat(BindingFrameBindings.lateralPrivateInputs(issued)).isEmpty();
			assertThat(BindingFrameBindings.hasLookupProbe(issued, name -> true)).isFalse();
			assertThat(BindingFrameBindings.materializeWithheldInputs(issued)).isSameAs(issued);
			assertThat(GraphFrameBindings.from(issued)).isSameAs(GraphFrameBindings.EMPTY);
			GroupInvocationBindings.Prepared sourceCapability = GroupInvocationBindings.prepared(issued);
			assertThat(sourceCapability).isNotNull();
			assertThat(sourceCapability.represents(sourceGroup)).isTrue();
			assertThat(sourceCapability.admits(issued)).isTrue();
			assertThat(groupEntryFacts(issued, sourceGroup, sourceEntry.step())).isEqualTo(sourceEntry.before());
			assertThat(groupEntryFacts(caller, sourceGroup, null)).isEqualTo(sourceCallerBefore);
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("parameter"));
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Lateral lateral = new Lateral(new SingletonSet(), call, Set.of("parameter", "x"));
			Group group = new Group(lateral, List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			GroupBranchHosts hosts = prepareGroupBranchHosts(dataset, group);
			GroupBranchObservation ordinary = observeGroupBranch(hosts, lateral, call, caller, callbacks, "ordinary");
			GroupBranchObservation substituted = observeGroupBranch(hosts, lateral, call, issued, callbacks, "issued");
			List<Map<String, Value>> expected = markerPresent
					? List.of(row("parameter", token, "x", local, "marker", marker, "count", groupInteger(2)))
					: List.of(row("parameter", token, "x", local, "count", groupInteger(2)));
			List<List<Value>> expectedCalls = List.of(List.of(token, local));
			SoftAssertions softly = new SoftAssertions();
			assertGroupBranchEffects(softly, hosts, ordinary, expected, expectedCalls);
			assertGroupBranchEffects(softly, hosts, substituted, expected, expectedCalls);
			softly.assertThat(ordinary.step())
					.as("both inputs use the same prepared candidate")
					.isSameAs(substituted.step());
			softly.assertThat(ordinary.facts().substitutionDomain()).isNull();
			softly.assertThat(substituted.facts().substitutionDomain()).isNotNull().isEqualTo(expectedDomain);
			softly.assertThat(substituted.facts().cells()).isEqualTo(ordinary.facts().cells());
			softly.assertThat(substituted.facts().seededNames()).containsExactly("x");
			softly.assertThat(substituted.facts().cells().get("parameter"))
					.isEqualTo(new GroupAdmissionCell(true, true, token));
			softly.assertThat(substituted.facts().semanticEntry()).isTrue();
			softly.assertThat(substituted.facts().invocationWitness())
					.as("the selected conditional recipe retains its branch proof")
					.isTrue();
			softly.assertThat(substituted.directAdmission())
					.as("nonnull domains cannot use the direct branch")
					.isNull();
			GroupInvocationBindings.Prepared targetCapability = GroupInvocationBindings
					.prepared(substituted.entry().bindings());
			softly.assertThat(targetCapability).isNotNull().isNotSameAs(sourceCapability);
			if (targetCapability != null) {
				softly.assertThat(targetCapability.represents(group)).isTrue();
				softly.assertThat(targetCapability.admits(substituted.entry().bindings())).isTrue();
				softly.assertThat(targetCapability.admits(issued))
						.as("the source capability was not transplanted")
						.isFalse();
			}
			if (!substituted.facts().seededNames().isEmpty()
					&& Boolean.FALSE.equals(substituted.facts().wholeSeededInjection())) {
				softly.assertThat(substituted.nativeDelta())
						.as("neither direct nor legacy input proof admits this entry")
						.isZero();
				softly.assertThat(substituted.unobservedDelta()).isZero();
				softly.assertThat(substituted.entry().fallbackReason()).isNotNull();
			}
			assertGroupBranchNative(softly, ordinary);
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

