	private static final class OpaqueTupleFunctionCall extends TupleFunctionCall {
	}

	private static TupleFunction groupBranchFunction(String uri, Value output, int copies,
			List<List<Value>> callbacks) {
		return new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				callbacks.add(List.copyOf(Arrays.asList(args)));
				return new CloseableIteratorIteration<>(Collections.nCopies(copies, List.of(output)).iterator());
			}
		};
	}

	private static QueryAlgebraBindingAnalysis groupBranchAnalysis(TupleExpr expression) {
		return QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(expression,
				QueryAlgebraBindingAnalysis.withBindingValues(expression, EmptyBindingSet.getInstance()).rootContext(),
				Set.of(), QueryEvaluationUtility.preparedOptionalInputNames(expression));
	}

	private record GroupBranchHosts(Group group, QueryRoot root, QueryEvaluationStep generic, Group unobservedGroup,
			QueryEvaluationStep unobserved, QueryEvaluationStep selected, AttachedGroupProbe probe) {
	}

	private GroupBranchHosts prepareGroupBranchHosts(SailDataset dataset, Group group) {
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		QueryRoot root = new QueryRoot(group);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
				.precompile(new QueryRoot(group.clone()), context);
		Group unobservedGroup = group.clone();
		unobservedGroup.setRuntimeTelemetryEnabled(true);
		unobservedGroup.setExecutionSummaryEnabled(true);
		QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
				.precompile(new QueryRoot(unobservedGroup), context);
		LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
		AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
		QueryEvaluationStep selected = strategy.precompile(root, context);
		return new GroupBranchHosts(group, root, generic, unobservedGroup, unobserved, selected, probe);
	}

	private record GroupBranchObservation(AttachedEffects generic, AttachedEffects unobserved, AttachedEffects selected,
			AttachedGroupEntry entry, NativeGroupStep step, LateralAdmissionFacts facts,
			NativeGroupInvocationWitness.Admission directAdmission, GroupEntryFacts before, GroupEntryFacts after,
			long nativeDelta, long unobservedDelta, String nativePath, String unobservedPath) {
	}

	private static GroupBranchObservation observeGroupBranch(GroupBranchHosts hosts, Lateral lateral,
			TupleFunctionCall call, BindingSet input, List<List<Value>> callbacks, String label) {
		GroupEntryFacts before = groupEntryFacts(input, hosts.group(), null);
		AttachedEffects reference = observeAttachedEffects(hosts.generic(), input, callbacks);
		long unobservedBefore = resetAttachedGroupMetrics(hosts.unobservedGroup());
		AttachedEffects unobserved = observeAttachedEffects(hosts.unobserved(), input, callbacks);
		int entryIndex = hosts.probe().entries.size();
		long nativeBefore = resetAttachedGroupMetrics(hosts.group());
		AttachedEffects selected = observeAttachedEffects(hosts.selected(), input, callbacks);
		AttachedGroupEntry entry = hosts.probe().onlyEntrySince(entryIndex, label);
		if (SCOPE_DIAGNOSTICS) {
			System.out.printf("group-branch label=%s prepared=%s%n", label, entry.step().getClass().getSimpleName());
		}
		assertThat(entry.step()).isInstanceOf(NativeGroupStep.class);
		NativeGroupStep step = (NativeGroupStep) entry.step();
		LateralAdmissionFacts facts = lateralAdmissionFacts(hosts.group(), lateral, call, step, entry.bindings());
		NativeGroupInvocationWitness.Admission admission = step.invocationWitness == null ? null
				: step.invocationWitness.admit(entry.bindings(), facts.seededNames(), Set.of());
		long nativeDelta = Math.max(0L, hosts.group().getLongMetricActual("nativeInvocationsActual")) - nativeBefore;
		long unobservedDelta = Math.max(0L, hosts.unobservedGroup().getLongMetricActual("nativeInvocationsActual"))
				- unobservedBefore;
		String nativePath = hosts.group().getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		String unobservedPath = hosts.unobservedGroup().getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		if (SCOPE_DIAGNOSTICS) {
			System.out.printf("group-branch label=%s facts=%s directAdmission=%s result=%s callbacks=%s failure=%s "
					+ "guard=%s nativeDelta=%d unobservedDelta=%d execution=%s unobservedExecution=%s%n", label, facts,
					admission != null, selected.rows(), selected.callbacks(), selected.failure(),
					entry.fallbackReason(),
					nativeDelta, unobservedDelta, nativePath, unobservedPath);
		}
		return new GroupBranchObservation(reference, unobserved, selected, entry, step, facts, admission, before,
				groupEntryFacts(input, hosts.group(), null), nativeDelta, unobservedDelta, nativePath, unobservedPath);
	}

	private static void assertGroupBranchEffects(SoftAssertions softly, GroupBranchHosts hosts,
			GroupBranchObservation observation, List<Map<String, Value>> expected, List<List<Value>> expectedCalls) {
		for (AttachedEffects effects : List.of(observation.generic(), observation.unobserved(),
				observation.selected())) {
			softly.assertThat(effects.rows()).as("independent exact bag").containsExactlyElementsOf(expected);
			softly.assertThat(effects.callbacks())
					.as("single ordered callbacks")
					.containsExactlyElementsOf(expectedCalls);
			softly.assertThat(effects.failure()).isNull();
		}
		softly.assertThat(hosts.root().getArg()).isSameAs(hosts.group());
		softly.assertThat(observation.step().originalExpr).isSameAs(hosts.group());
		softly.assertThat(observation.facts().preparedEntry()).isTrue();
		softly.assertThat(observation.facts().representsGroup()).isTrue();
		softly.assertThat(observation.facts().admitsEntry()).isTrue();
		softly.assertThat(observation.facts().physicalResults()).isFalse();
		softly.assertThat(observation.step().optionalOnlyNames).isEmpty();
		softly.assertThat(observation.after()).as("the actual caller is unchanged").isEqualTo(observation.before());
		softly.assertThat(groupEntryFacts(observation.entry().bindings(), hosts.group(), observation.step()))
				.as("the exact Group input is unchanged")
				.isEqualTo(observation.entry().before());
	}

	private static void assertGroupBranchNative(SoftAssertions softly, GroupBranchObservation observation) {
		softly.assertThat(observation.facts().invocationWitness()).as("selected conditional input witness").isTrue();
		softly.assertThat(observation.directAdmission()).as("the direct branch is admitted before opening").isNotNull();
		if (observation.directAdmission() != null) {
			softly.assertThat(observation.directAdmission()
					.represents(observation.step().arg, observation.step().layout,
							observation.step().aggregates))
					.as("the exact frozen candidate is represented")
					.isTrue();
		}
		softly.assertThat(observation.entry().fallbackReason()).isNull();
		softly.assertThat(observation.nativeDelta()).isPositive();
		softly.assertThat(observation.unobservedDelta()).isPositive();
		softly.assertThat(observation.nativePath()).isNotBlank().doesNotContain("genericFallback");
		softly.assertThat(observation.unobservedPath()).isNotBlank().doesNotContain("genericFallback");
	}

	private void checkAttachedGroupedOptionalGateCaller(List<Boolean> variants, boolean requireNative) {
		IRI subject = VF.createIRI("urn:attached-group:subject");
		IRI predicate = VF.createIRI("urn:attached-group:predicate");
		Value local = literal("local");
		Value other = literal("other");
		Value hit = literal("hit");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, literal("first"));
			connection.add(subject, predicate, literal("second"));
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			Extension right = new Extension(values("x", local), new ExtensionElem(new ValueConstant(hit), "hit"));
			Filter gate = new Filter(new LeftJoin(new SingletonSet(), right), new Bound(Var.of("hit")));
			StatementPattern pattern = new StatementPattern(Var.of("s", subject, false, true),
					Var.of("p", predicate, false, true), Var.of("v"));
			Group group = new Group(new Join(gate, pattern), List.of("x", "hit"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryRoot root = new QueryRoot(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			Group unobservedGroup = group.clone();
			unobservedGroup.setRuntimeTelemetryEnabled(true);
			unobservedGroup.setExecutionSummaryEnabled(true);
			QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(new QueryRoot(unobservedGroup), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(root, context);
			assertThat(root.getArg()).as("the Group occurrence remains attached to its actual root").isSameAs(group);
			for (boolean matching : variants) {
				Value inputValue = matching ? local : other;
				String label = inputValue.equals(local) ? "matching" : "conflicting";
				QueryBindingSet caller = new QueryBindingSet();
				caller.addBinding("x", inputValue);
				GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
				List<Map<String, Value>> expected = inputValue.equals(local)
						? List.of(row("x", local, "hit", hit, "count", groupInteger(2)))
						: List.of();
				try (var rows = generic.evaluate(caller)) {
					assertThat(mappings(rows)).as("generic attached OPTIONAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				assertThat(groupEntryFacts(caller, group, null)).as("generic caller unchanged %s", label)
						.isEqualTo(callerBefore);
				long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
				try (var rows = unobserved.evaluate(caller)) {
					assertThat(mappings(rows)).as("unobserved attached OPTIONAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				assertThat(groupEntryFacts(caller, group, null)).as("unobserved caller unchanged %s", label)
						.isEqualTo(callerBefore);
				int entriesBefore = probe.entries.size();
				long nativeBefore = resetAttachedGroupMetrics(group);
				try (var rows = selected.evaluate(caller)) {
					assertThat(mappings(rows)).as("selected attached OPTIONAL bag %s", label)
							.containsExactlyElementsOf(expected);
				}
				AttachedGroupEntry entry = probe.onlyEntrySince(entriesBefore, label);
				assertThat(entry.bindings().getValue("x")).as("actual Group caller %s", label).isEqualTo(inputValue);
				assertThat(BindingFrameBindings.substitutionDomain(entry.bindings()))
						.as("root caller has no manufactured EXISTS domain %s", label)
						.isNull();
				assertAttachedGroupRoute(group, entry, nativeBefore, "optional " + label);
				assertUnobservedGroupRoute(unobservedGroup, unobservedBefore, group, entry, nativeBefore, label);
				assertThat(groupEntryFacts(caller, group, null)).as("selected caller unchanged %s", label)
						.isEqualTo(callerBefore);
				if (requireNative) {
					assertAttachedNativeGroup(group, entry, nativeBefore, unobservedGroup, unobservedBefore, label);
				}
			}
		}
	}

