	private void checkEnclosingExistsGroupCaller(List<Boolean> variants, boolean requireNative) {
		IRI subject = VF.createIRI("urn:attached-exists:subject");
		IRI predicate = VF.createIRI("urn:attached-exists:predicate");
		Value local = literal("local");
		Value other = literal("other");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, literal("first"));
			connection.add(subject, predicate, literal("second"));
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LeftJoin optional = new LeftJoin(values("o", literal("o")), values("z", literal("z")),
					new Compare(Var.of("x"), new ValueConstant(local), Compare.CompareOp.EQ));
			StatementPattern pattern = new StatementPattern(Var.of("s", subject, false, true),
					Var.of("p", predicate, false, true), Var.of("v"));
			Group group = new Group(new Filter(new Join(optional, pattern), new Bound(Var.of("z"))), List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			Exists exists = new Exists(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryValueEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new Exists(group.clone()), context);
			Group unobservedGroup = group.clone();
			unobservedGroup.setRuntimeTelemetryEnabled(true);
			unobservedGroup.setExecutionSummaryEnabled(true);
			QueryValueEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(new Exists(unobservedGroup), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryValueEvaluationStep selected = strategy.precompile(exists, context);
			assertThat(exists.getSubQuery()).as("the actual EXISTS owns the pinned Group occurrence").isSameAs(group);
			for (boolean matching : variants) {
				Value inputValue = matching ? local : other;
				String label = inputValue.equals(local) ? "matching" : "conflicting";
				QueryBindingSet caller = new QueryBindingSet();
				caller.addBinding("x", inputValue);
				GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
				Value expected = VF.createLiteral(inputValue.equals(local));
				assertThat(generic.evaluate(caller)).as("generic enclosing EXISTS %s", label).isEqualTo(expected);
				assertThat(groupEntryFacts(caller, group, null)).as("generic caller unchanged %s", label)
						.isEqualTo(callerBefore);
				long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
				assertThat(unobserved.evaluate(caller)).as("unobserved enclosing EXISTS %s", label)
						.isEqualTo(expected);
				assertThat(groupEntryFacts(caller, group, null)).as("unobserved caller unchanged %s", label)
						.isEqualTo(callerBefore);
				int entriesBefore = probe.entries.size();
				long nativeBefore = resetAttachedGroupMetrics(group);
				assertThat(selected.evaluate(caller)).as("selected enclosing EXISTS %s", label).isEqualTo(expected);
				AttachedGroupEntry entry = probe.onlyEntrySince(entriesBefore, label);
				assertThat(entry.dynamicContext()).as("EXISTS prepares its Group with a dynamic context %s", label)
						.isTrue();
				assertThat(BindingFrameBindings.hasFrame(entry.bindings()))
						.as("EXISTS produced an invocation frame %s", label)
						.isTrue();
				assertThat(BindingFrameBindings.substitutionDomain(entry.bindings()))
						.as("actual EXISTS substitution domain %s", label)
						.containsExactly("x");
				assertThat(entry.bindings().getValue("x")).as("actual EXISTS input %s", label).isEqualTo(inputValue);
				assertAttachedGroupRoute(group, entry, nativeBefore, "exists " + label);
				assertUnobservedGroupRoute(unobservedGroup, unobservedBefore, group, entry, nativeBefore, label);
				assertThat(groupEntryFacts(caller, group, null)).as("selected caller unchanged %s", label)
						.isEqualTo(callerBefore);
				if (requireNative) {
					assertAttachedNativeGroup(group, entry, nativeBefore, unobservedGroup, unobservedBefore, label);
				}
			}
		}
	}

	@ParameterizedTest(name = "matching={0}, fatal={1}")
	@MethodSource("attachedOptionalEffectCases")
	void attachedOptionalGatePreservesRightSideEffects(boolean matching, boolean fatal) {
		String uri = "urn:attached-group:optional-effects";
		Value local = literal("local");
		Value other = literal("other");
		Value hit = literal("hit");
		List<List<Value>> callbacks = new ArrayList<>();
		QueryEvaluationException original = new QueryEvaluationException("attached optional tuple fatal");
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				callbacks.add(List.copyOf(Arrays.asList(args)));
				if (fatal && callbacks.size() == 2) {
					throw original;
				}
				return new SingletonIteration<>(List.of(hit));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("effect"));
			Lateral right = new Lateral(values("x", local, local), call, Set.of("x"));
			Extension markedRight = new Extension(right, new ExtensionElem(new ValueConstant(hit), "hit"));
			Filter gate = new Filter(new LeftJoin(new SingletonSet(), markedRight), new Bound(Var.of("hit")));
			Group group = new Group(gate, List.of("x", "hit"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("effect"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryRoot root = new QueryRoot(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			Group unobservedGroup = group.clone();
			unobservedGroup.setRuntimeTelemetryEnabled(true);
			unobservedGroup.setExecutionSummaryEnabled(true);
			QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(new QueryRoot(unobservedGroup), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(root, context);
			QueryBindingSet caller = new QueryBindingSet();
			caller.addBinding("x", matching ? local : other);
			GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
			List<Map<String, Value>> expected = matching && !fatal
					? List.of(row("x", local, "hit", hit, "count", groupInteger(2)))
					: List.of();
			List<List<Value>> expectedCalls = List.of(List.of(local), List.of(local));

			AttachedEffects reference = observeAttachedEffects(generic, caller, callbacks);
			long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
			AttachedEffects plain = observeAttachedEffects(unobserved, caller, callbacks);
			long nativeBefore = resetAttachedGroupMetrics(group);
			AttachedEffects actual = observeAttachedEffects(selected, caller, callbacks);
			AttachedGroupEntry entry = probe.onlyEntrySince(0, "optional effects");
			for (AttachedEffects effect : List.of(reference, plain, actual)) {
				assertThat(effect.rows()).as("OPTIONAL gate exact bag").containsExactlyElementsOf(expected);
				assertThat(effect.callbacks()).as("the right side runs before compatibility is decided")
						.containsExactlyElementsOf(expectedCalls);
				if (fatal) {
					assertThat(effect.failure()).as("the original callback failure escapes").isSameAs(original);
				} else {
					assertThat(effect.failure()).isNull();
				}
			}
			assertThat(entry.bindings().getValue("x")).isEqualTo(matching ? local : other);
			assertAttachedGroupRoute(group, entry, nativeBefore, "optional effects");
			assertUnobservedGroupRoute(unobservedGroup, unobservedBefore, group, entry, nativeBefore,
					"optional effects");
			assertThat(groupEntryFacts(caller, group, null)).as("OPTIONAL caller remains unchanged")
					.isEqualTo(callerBefore);
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

