	@ParameterizedTest(name = "{0}")
	@ValueSource(strings = { "matching", "conflicting", "fatal", "reuse-after-fatal" })
	void attachedGroupedLateralEffectsRequireNativeGroup(String scenario) {
		String uri = "urn:attached-group:lateral-native-effects";
		Value first = literal("first");
		Value second = literal("second");
		Value local = literal("local");
		Value other = literal("other");
		Value fatalToken = literal("fatal");
		List<List<Value>> callbacks = new ArrayList<>();
		QueryEvaluationException original = new QueryEvaluationException("attached native lateral tuple fatal");
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				callbacks.add(List.copyOf(Arrays.asList(args)));
				if (fatalToken.equals(args[0]) && second.equals(args[1])) {
					throw original;
				}
				return new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("parameter"));
			call.addArg(Var.of("sequence"));
			call.addResultVar(Var.of("x"));
			Lateral lateral = new Lateral(values("sequence", first, first, second), call,
					Set.of("parameter", "sequence"));
			Group group = new Group(lateral, List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryRoot root = new QueryRoot(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			Group unobservedGroup = group.clone();
			unobservedGroup.setRuntimeTelemetryEnabled(true);
			unobservedGroup.setExecutionSummaryEnabled(true);
			QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(new QueryRoot(unobservedGroup), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(root, context);
			record EffectCase(String label, Value token, Value x, boolean fatal) {
			}
			EffectCase matching = new EffectCase("matching", literal("success"), local, false);
			EffectCase conflicting = new EffectCase("conflicting", literal("conflict"), other, false);
			EffectCase fatal = new EffectCase("fatal", fatalToken, other, true);
			EffectCase reused = new EffectCase("matching after fatal", literal("success"), local, false);
			List<EffectCase> cases = switch (scenario) {
			case "matching" -> List.of(matching);
			case "conflicting" -> List.of(conflicting);
			case "fatal" -> List.of(fatal);
			case "reuse-after-fatal" -> List.of(fatal, reused);
			default -> throw new IllegalArgumentException("unknown native effect case " + scenario);
			};
			record Observation(EffectCase test, AttachedEffects reference, AttachedEffects unobserved,
					AttachedEffects observed, List<AttachedGroupEntry> entries, GroupEntryFacts callerBefore,
					GroupEntryFacts callerAfter, long nativeDelta, long unobservedDelta, String nativePath,
					String unobservedPath, String runtimePlan) {
			}
			List<Observation> observations = new ArrayList<>();
			for (EffectCase test : cases) {
				QueryBindingSet caller = new QueryBindingSet();
				caller.addBinding("parameter", test.token());
				caller.addBinding("x", test.x());
				GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
				AttachedEffects reference = observeAttachedEffects(generic, caller, callbacks);
				long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
				AttachedEffects plain = observeAttachedEffects(unobserved, caller, callbacks);
				long unobservedDelta = Math.max(0L, unobservedGroup.getLongMetricActual("nativeInvocationsActual"))
						- unobservedBefore;
				String unobservedPath = unobservedGroup.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
				int entryIndex = probe.entries.size();
				long nativeBefore = resetAttachedGroupMetrics(group);
				AttachedEffects actual = observeAttachedEffects(selected, caller, callbacks);
				long nativeDelta = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual")) - nativeBefore;
				List<AttachedGroupEntry> entries = List.copyOf(probe.entries.subList(entryIndex, probe.entries.size()));
				observations.add(new Observation(test, reference, plain, actual, entries, callerBefore,
						groupEntryFacts(caller, group, null), nativeDelta, unobservedDelta,
						group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH), unobservedPath,
						group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN)));
			}
			SoftAssertions softly = new SoftAssertions();
			for (Observation observation : observations) {
				EffectCase test = observation.test();
				String label = scenario + "/" + test.label();
				List<Map<String, Value>> expected = test.x().equals(local)
						? List.of(row("parameter", test.token(), "x", local, "count", groupInteger(3)))
						: List.of();
				List<List<Value>> expectedCalls = List.of(List.of(test.token(), first), List.of(test.token(), first),
						List.of(test.token(), second));
				for (AttachedEffects effect : List.of(observation.reference(), observation.unobserved(),
						observation.observed())) {
					softly.assertThat(effect.rows())
							.as("exact Group bag %s", label)
							.containsExactlyElementsOf(expected);
					softly.assertThat(effect.callbacks())
							.as("ordered single-pass callbacks %s", label)
							.containsExactlyElementsOf(expectedCalls);
					if (test.fatal()) {
						softly.assertThat(effect.failure())
								.as("original callback failure %s", label)
								.isSameAs(original);
					} else {
						softly.assertThat(effect.failure()).as("successful callback %s", label).isNull();
					}
				}
				softly.assertThat(observation.callerAfter())
						.as("caller remains unchanged %s", label)
						.isEqualTo(observation.callerBefore());
				softly.assertThat(observation.entries()).as("actual attached Group invocation %s", label).hasSize(1);
				if (observation.entries().size() == 1) {
					AttachedGroupEntry entry = observation.entries().getFirst();
					softly.assertThat(entry.step())
							.as("prepared native Group %s", label)
							.isInstanceOf(NativeGroupStep.class);
					if (entry.step() instanceof NativeGroupStep nativeGroup) {
						softly.assertThat(nativeGroup.originalExpr)
								.as("pinned Group occurrence %s", label)
								.isSameAs(group);
					}
					softly.assertThat(entry.fallbackReason()).as("no Group entry guard %s", label).isNull();
					softly.assertThat(groupEntryFacts(entry.bindings(), group, entry.step()))
							.as("Group entry and frame remain unchanged %s", label)
							.isEqualTo(entry.before());
				}
				softly.assertThat(observation.nativeDelta())
						.as("actual pinned Group native invocation %s", label)
						.isPositive();
				softly.assertThat(observation.unobservedDelta())
						.as("unobserved Group native invocation %s", label)
						.isPositive();
				softly.assertThat(observation.nativePath() == null
						|| !observation.nativePath().contains("genericFallback"))
						.as("observed Group avoids fallback %s", label)
						.isTrue();
				softly.assertThat(observation.unobservedPath() == null
						|| !observation.unobservedPath().contains("genericFallback"))
						.as("unobserved Group avoids fallback %s", label)
						.isTrue();
				if (!test.fatal()) {
					softly.assertThat(observation.nativePath())
							.as("completed observed native route %s", label)
							.isNotBlank();
					softly.assertThat(observation.unobservedPath())
							.as("completed unobserved native route %s", label)
							.isNotBlank();
				}
				if (SCOPE_DIAGNOSTICS) {
					System.out.printf("attached-native-effects %s nativeDelta=%d unobservedDelta=%d "
							+ "execution=%s unobservedExecution=%s actual=%s%n", label, observation.nativeDelta(),
							observation.unobservedDelta(), observation.nativePath(), observation.unobservedPath(),
							observation.runtimePlan());
				}
			}
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	private record AttachedEffects(List<Map<String, Value>> rows, RuntimeException failure,
			List<List<Value>> callbacks) {
	}

	@Test
	void groupInvocationCapabilityDoesNotSurviveMappingCopies() throws Exception {
		String uri = "urn:attached-group:copy-capability";
		Value local = literal("local");
		IRI graph = VF.createIRI("urn:attached-group:issued-graph");
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				return new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:attached-group:graph-subject"), VF.createIRI("urn:attached-group:graph-p"),
					local, graph);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Group group = new Group(new Lateral(new SingletonSet(), call, Set.of("x")), List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			QueryRoot root = new QueryRoot(group);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(root, context);
			QueryBindingSet caller = new QueryBindingSet();
			caller.setBinding("x", local);
			try (var rows = selected.evaluate(caller)) {
				assertThat(mappings(rows)).containsExactly(row("x", local, "count", groupInteger(1)));
			}
			AttachedGroupEntry actual = probe.onlyEntrySince(0, "issued capability");
			assertThat(actual.step()).isInstanceOf(NativeGroupStep.class);
			NativeGroupStep nativeGroup = (NativeGroupStep) actual.step();
			GroupInvocationBindings.Prepared prepared = GroupInvocationBindings.prepared(actual.bindings());
			assertThat(prepared).isNotNull();
			assertThat(GroupInvocationBindings.prepared(group))
					.as("preparation evidence is scoped to child compilation")
					.isNull();
			assertThat(prepared.admits(actual.bindings())).as("the real root edge issued the capability").isTrue();
			assertThat(nativeGroup.semanticEntryFallbackReason(actual.bindings())).isNull();
			assertThat(nativeGroup.semanticEntryFallbackReason(actual.bindings()))
					.as("an admission probe does not consume the capability")
					.isNull();
			QueryBindingSet copied = new QueryBindingSet(actual.bindings());
			QueryBindingSet written = new QueryBindingSet(actual.bindings());
			written.setBinding("x", local);
			Projection projection = new Projection(new SingletonSet(),
					new ProjectionElemList(new ProjectionElem("x")), false);
			BindingSet projected;
			try (var rows = strategy.genericOnlyView().precompile(projection, context).evaluate(actual.bindings())) {
				assertThat(rows.hasNext()).isTrue();
				projected = rows.next();
			}
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
				output.writeObject(actual.bindings());
			}
			BindingSet restored;
			try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				restored = (BindingSet) input.readObject();
			}
			for (BindingSet ordinary : List.of(copied, written, projected, restored)) {
				assertThat(prepared.admits(ordinary)).as("ordinary mappings do not carry invocation evidence")
						.isFalse();
				assertThat(nativeGroup.semanticEntryFallbackReason(ordinary)).isEqualTo("groupInput");
			}
			Group clone = group.clone();
			assertThat(GroupInvocationBindings.prepared(clone)).as("shallow metadata does not authorize a clone")
					.isNull();
			for (Group separatelyPrepared : List.of(group, clone)) {
				QueryEvaluationStep later = LmdbNativeAggregateCompiler.tryCompile(separatelyPrepared, context,
						strategy, (NativeLmdbQuerySource) dataset);
				assertThat(later).isInstanceOf(NativeGroupStep.class);
				assertThat(((NativeGroupStep) later).semanticEntryFallbackReason(actual.bindings()))
						.as("a different preparation cannot use the genuine earlier entry")
						.isEqualTo("groupInput");
			}

			// A real GRAPH selection feeds the projection evaluator's private-input producer.
			Projection graphProducer = new Projection(new SingletonSet(),
					new ProjectionElemList(new ProjectionElem("x")), true);
			graphProducer.setProjectionContext(Var.of("graphCaller", graph, false, true));
			graphProducer.setInheritedGraphParameter("scopeGraph");
			Graph graphHost = new Graph(Var.of("graphCaller", graph, true, true), graphProducer);
			TripleSource graphSource = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			List<BindingSet> graphInputs = new ArrayList<>();
			DefaultEvaluationStrategy graphStrategy = new DefaultEvaluationStrategy(graphSource, null) {
				@Override
				protected QueryEvaluationStep prepare(SingletonSet singleton, QueryEvaluationContext activeContext)
						throws QueryEvaluationException {
					QueryEvaluationStep original = super.prepare(singleton, activeContext);
					return bindings -> {
						graphInputs.add(bindings);
						return original.evaluate(bindings);
					};
				}
			};
			QueryEvaluationStep suppliedGraph = graphStrategy.precompile(graphHost, context);
			try (var rows = suppliedGraph.evaluate(caller)) {
				assertThat(mappings(rows)).containsExactly(row("x", local));
			}
			assertThat(graphInputs).as("the actual GRAPH/Projection edge invoked its Singleton body once").hasSize(1);
			BindingSet graphInput = graphInputs.getFirst();
			assertThat(graphInput.getBindingNames()).containsExactlyInAnyOrder("x", "scopeGraph");
			assertThat(graphInput.getValue("x")).isEqualTo(local);
			assertThat(graphInput.getValue("scopeGraph")).isEqualTo(graph);
			assertThat(GraphFrameBindings.isSupplied(graphInput, "scopeGraph")).isTrue();
			assertThat(GroupInvocationBindings.prepared(graphInput)).as("the producer did not invoke a Group").isNull();
			assertThat(root.getArg()).as("the target Group remains on its separate real root edge").isSameAs(group);
			QueryEvaluationStep graphReference = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			Group unobservedGraphGroup = group.clone();
			unobservedGraphGroup.setRuntimeTelemetryEnabled(true);
			QueryEvaluationStep graphUnobserved = groupEmissionStrategy(dataset)
					.precompile(new QueryRoot(unobservedGraphGroup), context);
			List<Map<String, Value>> graphExpected = List.of(row("x", local, "scopeGraph", graph,
					"count", groupInteger(1)));
			int beforeGraph = probe.entries.size();
			long unobservedBefore = resetAttachedGroupMetrics(unobservedGraphGroup);
			for (QueryEvaluationStep target : List.of(graphReference, graphUnobserved, selected)) {
				try (var rows = target.evaluate(graphInput)) {
					List<BindingSet> results = drainGroupRdf(rows);
					assertThat(groupMaps(results)).as("the separate root Group retains its complete GRAPH caller")
							.containsExactlyElementsOf(graphExpected);
					assertThat(GraphFrameBindings.isSupplied(results.getFirst(), "scopeGraph")).isTrue();
					assertThat(GroupInvocationBindings.prepared(results.getFirst()))
							.as("results carry no entry capability")
							.isNull();
				}
			}
			BindingSet supplied = probe.onlyEntrySince(beforeGraph, "GRAPH producer").bindings();
			assertThat(prepared.admits(supplied)).isTrue();
			assertThat(nativeGroup.semanticEntryFallbackReason(supplied))
					.as("the exact root capability does not grant unsupported GRAPH admission")
					.isEqualTo("groupInput");
			assertThat(unobservedGraphGroup.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.contains("genericFallback(groupInput)");
			assertThat(Math.max(0L, unobservedGraphGroup.getLongMetricActual("nativeInvocationsActual"))
					- unobservedBefore).isZero();
			assertThat(GraphFrameBindings.isSupplied(supplied, "scopeGraph")).isTrue();
			assertThat(GraphFrameBindings.from(supplied)).isSameAs(GraphFrameBindings.from(graphInput));
			assertThat(BindingFrameBindings.from(supplied)).isSameAs(BindingFrameBindings.from(graphInput));
			QueryBindingSet graphCopy = new QueryBindingSet(supplied);
			assertThat(GraphFrameBindings.isSupplied(graphCopy, "scopeGraph")).isTrue();
			assertThat(GraphFrameBindings.from(graphCopy)).isSameAs(GraphFrameBindings.from(supplied));
			assertThat(BindingFrameBindings.from(graphCopy)).isSameAs(BindingFrameBindings.from(supplied));
			assertThat(prepared.admits(graphCopy)).isFalse();
			assertThat(GroupInvocationBindings.prepared(graphCopy)).isNull();
			assertThat(nativeGroup.semanticEntryFallbackReason(graphCopy)).isEqualTo("groupInput");
			graphCopy.setBinding("scopeGraph", graph);
			assertThat(GraphFrameBindings.isSupplied(graphCopy, "scopeGraph"))
					.as("a local write revokes the producer's GRAPH authority even for an equal value")
					.isFalse();
			assertThat(prepared.admits(graphCopy)).isFalse();
			assertThat(GraphFrameBindings.isSupplied(supplied, "scopeGraph"))
					.as("the copy's local write leaves the original producer grant intact")
					.isTrue();
			assertThat(caller.getBindingNames()).containsExactly("x");
			assertThat(GraphFrameBindings.from(caller)).isSameAs(GraphFrameBindings.EMPTY);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("group-capability-graph producerCalls=%d logical=%s supplied=%s rootCapability=%s "
						+ "guard=%s copiedCapability=%s copiedGraphAfterWrite=%s%n", graphInputs.size(),
						supplied.getBindingNames(), GraphFrameBindings.isSupplied(supplied, "scopeGraph"),
						prepared.admits(supplied), nativeGroup.semanticEntryFallbackReason(supplied),
						prepared.admits(graphCopy), GraphFrameBindings.isSupplied(graphCopy, "scopeGraph"));
			}
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	@Test
	void optionalRewriteDoesNotExposeWithheldInputsToPureExpressions() {
		Value callerValue = literal("caller");
		Value hit = literal("hit");
		Extension right = new Extension(new SingletonSet(), new ExtensionElem(new Bound(Var.of("x")), "seen"),
				new ExtensionElem(new ValueConstant(hit), "hit"));
		Filter gate = new Filter(new LeftJoin(new SingletonSet(), right), new Bound(Var.of("hit")));
		Group group = new Group(gate, List.of("x", "seen", "hit"));
		group.addGroupElement(new GroupElem("count", new Count(null, false)));
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		QueryBindingSet caller = new QueryBindingSet();
		caller.setBinding("x", callerValue);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(new QueryRoot(group), context);
			List<Map<String, Value>> expected = List.of(row("x", callerValue, "seen", VF.createLiteral(false),
					"hit", hit, "count", groupInteger(1)));
			try (var rows = generic.evaluate(caller)) {
				assertThat(mappings(rows)).containsExactlyElementsOf(expected);
			}
			long before = resetAttachedGroupMetrics(group);
			try (var rows = selected.evaluate(caller)) {
				assertThat(mappings(rows)).containsExactlyElementsOf(expected);
			}
			assertThat(probe.onlyEntrySince(0, "withheld expression").fallbackReason()).isNotNull();
			assertThat(Math.max(0L, group.getLongMetricActual("nativeInvocationsActual")) - before).isZero();
		}
	}

	@ParameterizedTest(name = "framed={0}")
	@ValueSource(booleans = { false, true })
	void attachedGroupNullCallerUsesSemanticFallbackWithoutLosingDomain(boolean framed) {
		Value keep = literal("keep");
		Value older = literal("older probe");
		QueryBindingSet caller = new QueryBindingSet();
		caller.setBinding("x", null);
		caller.setBinding("keep", keep);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryBindingSet probes = new QueryBindingSet();
		probes.setBinding("x", older);
		probes.setBinding("hidden", older);
		BindingSet input = framed
				? BindingFrameBindings.push(new BindingFrameBindings.Scope(), caller, probes, context)
				: caller;
		Group group = new Group(new SingletonSet(), List.of("x"));
		group.addGroupElement(new GroupElem("count", new Count(null, false)));
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		GroupEntryFacts before = groupEntryFacts(input, group, null);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:null-domain:subject"), VF.createIRI("urn:null-domain:predicate"), keep);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new QueryRoot(group.clone()), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(new QueryRoot(group), context);
			List<BindingSet> outputs = new ArrayList<>();
			for (QueryEvaluationStep step : List.of(generic, selected)) {
				try (var rows = step.evaluate(input)) {
					assertThat(rows.hasNext()).isTrue();
					outputs.add(rows.next());
					assertThat(rows.hasNext()).isFalse();
				}
			}
			SoftAssertions softly = new SoftAssertions();
			for (int index = 0; index < outputs.size(); index++) {
				BindingSet output = outputs.get(index);
				String route = index == 0 ? "generic" : "selected fallback";
				softly.assertThat(output.getBindingNames())
						.as("complete %s null domain", route)
						.containsExactlyInAnyOrder("x", "keep", "count");
				softly.assertThat(output.size()).isEqualTo(3);
				softly.assertThat(output.hasBinding("x")).as("%s retains present-null x", route).isTrue();
				softly.assertThat(output.getValue("x")).isNull();
				softly.assertThat(output.getValue("keep")).isEqualTo(keep);
				softly.assertThat(output.getValue("count")).isEqualTo(groupInteger(1));
				softly.assertThat(BindingFrameBindings.from(output))
						.as("%s retains its owner metadata", route)
						.isSameAs(BindingFrameBindings.from(input));
				softly.assertThat(BindingFrameBindings.probeValue(output, "hidden"))
						.isEqualTo(BindingFrameBindings.probeValue(input, "hidden"));
				softly.assertThat(GroupInvocationBindings.prepared(output)).isNull();
			}
			AttachedGroupEntry actual = probe.onlyEntrySince(0, "present-null fallback");
			softly.assertThat(actual.step()).isInstanceOf(NativeGroupStep.class);
			softly.assertThat(GroupInvocationBindings.prepared(actual.bindings()))
					.as("the actual root edge issued the candidate input")
					.isNotNull();
			softly.assertThat(actual.bindings().hasBinding("x")).isTrue();
			softly.assertThat(actual.bindings().getValue("x")).isNull();
			softly.assertThat(actual.fallbackReason())
					.as("null entries still decline before native seeding")
					.isEqualTo("groupInput");
			softly.assertThat(Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"))).isZero();
			softly.assertThat(group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.contains("genericFallback(groupInput)");
			softly.assertThat(groupEntryFacts(input, group, null))
					.as("the framed caller is unchanged")
					.isEqualTo(before);
			softly.assertThat(caller.getBindingNames()).containsExactlyInAnyOrder("x", "keep");
			softly.assertThat(caller.hasBinding("x")).isTrue();
			softly.assertThat(caller.getValue("x")).isNull();
			softly.assertThat(caller.getValue("keep")).isEqualTo(keep);
			softly.assertAll();
		}
	}

	@ParameterizedTest(name = "close={0}")
	@ValueSource(booleans = { false, true })
	void nativeGroupedLateralStopsWithTupleResultInFlight(boolean close) throws Exception {
		String uri = "urn:attached-group:native-in-flight:" + close;
		Value first = literal("first");
		Value second = literal("second");
		Value local = literal("local");
		Value callerA = literal("caller-a");
		Value callerB = literal("caller-b");
		List<List<Value>> callbacks = Collections.synchronizedList(new ArrayList<>());
		AtomicReference<OwnerInFlightResult> inFlight = new AtomicReference<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				callbacks.add(List.of(args[0], args[1]));
				OwnerInFlightResult gated = inFlight.get();
				return gated != null && callerA.equals(args[0]) ? gated : new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("parameter"));
			call.addArg(Var.of("sequence"));
			call.addResultVar(Var.of("x"));
			Group group = new Group(new Lateral(values("sequence", first, first, second), call,
					Set.of("parameter", "sequence")), List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.precompile(new QueryRoot(group), context);
			QueryBindingSet inputA = new QueryBindingSet();
			inputA.setBinding("parameter", callerA);
			inputA.setBinding("x", local);
			CloseableIteration<BindingSet> rows = selected.evaluate(inputA);
			assertThat(callbacks).isEmpty();
			OwnerInFlightResult gated = new OwnerInFlightResult(callerA, local);
			inFlight.set(gated);
			ExecutorService executor = Executors.newFixedThreadPool(2);
			AtomicReference<Thread> puller = new AtomicReference<>();
			AtomicReference<Thread> closerThread = new AtomicReference<>();
			Future<Boolean> pull = null;
			Future<?> closer = null;
			try {
				pull = executor.submit(() -> {
					puller.set(Thread.currentThread());
					return rows.hasNext();
				});
				assertThat(gated.entered.await(5, TimeUnit.SECONDS)).isTrue();
				assertThat(callbacks).containsExactly(List.of(callerA, first));
				assertThat(group.getLongMetricActual("nativeInvocationsActual")).isPositive();
				assertThat(probe.onlyEntrySince(0, "native in-flight").fallbackReason()).isNull();
				assertThat(group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN))
						.contains("strategy: nestedLoop")
						.contains("status: ACTIVE_OR_PARTIAL");
				if (close) {
					CountDownLatch started = new CountDownLatch(1);
					closer = executor.submit(() -> {
						closerThread.set(Thread.currentThread());
						started.countDown();
						rows.close();
					});
					assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
					awaitCommittedGroupCloseBlocked(closerThread.get(), puller.get(), closer);
				} else {
					assertThat(CooperativeCancellation.forward(rows)).isTrue();
				}
			} finally {
				gated.release.countDown();
				executor.shutdown();
				if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
					executor.shutdownNow();
					assertThat(awaitOwnerWorkerTermination(executor)).isTrue();
				}
				rows.close();
				inFlight.set(null);
			}
			assertThat(pull).isNotNull();
			assertThat(pull.get()).as("the stopped Group emits no row").isFalse();
			if (closer != null) {
				closer.get();
			}
			assertThat(gated.nextCalls).hasValue(1);
			assertThat(gated.closes).hasValue(1);
			assertThat(callbacks).as("no retry or later tuple callback").containsExactly(List.of(callerA, first));
			assertThat(rows.hasNext()).isFalse();
			assertThat(group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN))
					.contains("status: ACTIVE_OR_PARTIAL")
					.doesNotContain("status: COMPLETED");
			QueryBindingSet inputB = new QueryBindingSet();
			inputB.setBinding("parameter", callerB);
			inputB.setBinding("x", local);
			callbacks.clear();
			try (var reused = selected.evaluate(inputB)) {
				assertThat(mappings(reused)).containsExactly(row("parameter", callerB, "x", local,
						"count", groupInteger(3)));
			}
			assertThat(callbacks).containsExactly(List.of(callerB, first), List.of(callerB, first),
					List.of(callerB, second));
			assertThat(probe.onlyEntrySince(1, "native reuse").fallbackReason()).isNull();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	private static void awaitCommittedGroupCloseBlocked(Thread closer, Thread puller, Future<?> closeFuture) {
		ThreadMXBean threads = ManagementFactory.getThreadMXBean();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() - deadline < 0L) {
			ThreadInfo info = threads.getThreadInfo(closer.threadId(), 16);
			if (info != null && info.getThreadState() == Thread.State.BLOCKED && info.getLockInfo() != null
					&& info.getLockOwnerId() == puller.threadId()
					&& info.getLockInfo().getClassName().equals(NativeCommittedGroupIteration.class.getName())) {
				return;
			}
			if (closeFuture.isDone()) {
				throw new AssertionError("Group close completed before its in-flight input was released");
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("Group close did not reach its committed input monitor");
	}

	private static AttachedEffects observeAttachedEffects(QueryEvaluationStep step, BindingSet input,
			List<List<Value>> callbacks) {
		callbacks.clear();
		List<Map<String, Value>> results = new ArrayList<>();
		RuntimeException failure = null;
		try (var rows = step.evaluate(input)) {
			while (rows.hasNext()) {
				BindingSet row = rows.next();
				Map<String, Value> values = new TreeMap<>();
				for (String name : row.getBindingNames()) {
					values.put(name, row.getValue(name));
				}
				results.add(values);
			}
		} catch (RuntimeException problem) {
			failure = problem;
		}
		return new AttachedEffects(List.copyOf(results), failure, List.copyOf(callbacks));
	}

	@Test
	void copiedLateralInputDoesNotUpgradeGroupEntryAuthority() {
		Value callerValue = literal("caller");
		Value local = literal("local");
		Value hidden = literal("physical-sibling");
		IRI graph = VF.createIRI("urn:attached-group:ordinary-graph-value");
		Extension leftInput = new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(local), "x"));
		Projection projection = new Projection(leftInput,
				new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("caller"),
						new ProjectionElem("g")),
				false);
		Extension groupInput = new Extension(values("v", literal("first"), literal("second")));
		groupInput.addElement(new ExtensionElem(new ValueConstant(local), "x"));
		groupInput.addElement(new ExtensionElem(new ValueConstant(graph), "g"));
		Group group = new Group(groupInput, List.of("x", "g"));
		group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		Lateral lateral = new Lateral(projection, group, Set.of("x"));
		Join owner = new Join(values("hidden", hidden), lateral);
		QueryRoot root = new QueryRoot(owner);
		QueryRoot genericRoot = root.clone();
		Group genericGroup = (Group) ((Lateral) ((Join) genericRoot.getArg()).getRightArg()).getRightArg();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryBindingSet caller = new QueryBindingSet();
		caller.addBinding("caller", callerValue);
		caller.addBinding("g", graph);
		GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
		assertThat(GraphFrameBindings.isSupplied(caller, "g")).as("an ordinary IRI is not a GRAPH grant").isFalse();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy genericStrategy = spy(groupEmissionStrategy(dataset).genericOnlyView());
			AttachedGroupProbe genericProbe = new AttachedGroupProbe(genericStrategy, genericGroup);
			QueryEvaluationStep generic = genericStrategy.precompile(genericRoot, context);
			QueryEvaluationStep automatic = groupEmissionStrategy(dataset).precompile(root.clone(), context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			// Select the ordinary enclosing join and LATERAL; their actual prepared children may still be native.
			doAnswer(invocation -> strategy.genericPrecompile(owner, invocation.getArgument(1)))
					.when(strategy)
					.precompileTupleExpr(same(owner), any(QueryEvaluationContext.class));
			doAnswer(invocation -> strategy.genericPrecompile(lateral, invocation.getArgument(1)))
					.when(strategy)
					.precompileTupleExpr(same(lateral), any(QueryEvaluationContext.class));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryEvaluationStep selected = strategy.genericPrecompile(root, context);
			List<BindingSet> expectedRows;
			try (var rows = generic.evaluate(caller)) {
				expectedRows = drainGroupRdf(rows);
			}
			List<BindingSet> automaticRows;
			try (var rows = automatic.evaluate(caller)) {
				automaticRows = drainGroupRdf(rows);
			}
			long nativeBefore = resetAttachedGroupMetrics(group);
			List<BindingSet> actualRows;
			try (var rows = selected.evaluate(caller)) {
				actualRows = drainGroupRdf(rows);
			}
			List<Map<String, Value>> expected = List.of(row("caller", callerValue, "g", graph, "x", local,
					"hidden", hidden, "count", groupInteger(2)));
			assertThat(groupMaps(expectedRows)).as("ordinary generic copied-boundary bag")
					.containsExactlyElementsOf(expected);
			assertThat(groupMaps(automaticRows)).as("automatic copied-boundary bag")
					.containsExactlyElementsOf(expected);
			assertThat(groupMaps(actualRows)).as("selected copied-boundary bag").containsExactlyElementsOf(expected);
			AttachedGroupEntry genericEntry = genericProbe.onlyEntrySince(0, "generic copied boundary");
			AttachedGroupEntry entry = probe.onlyEntrySince(0, "selected copied boundary");
			for (AttachedGroupEntry observed : List.of(genericEntry, entry)) {
				BindingSet input = observed.bindings();
				assertThat(input.getValue("caller")).as("the root caller reaches the Group").isEqualTo(callerValue);
				assertThat(input.getValue("x")).as("the projected local value reaches the Group").isEqualTo(local);
				assertThat(input.getValue("g")).as("the ordinary graph-valued caller is preserved").isEqualTo(graph);
				assertThat(input.hasBinding("hidden")).as("the sibling probe is not a logical input").isFalse();
				assertThat(BindingFrameBindings.probeValue(input, "hidden"))
						.as("the real enclosing join retains its physical sibling probe")
						.isEqualTo(hidden);
				assertThat(BindingFrameBindings.substitutionDomain(input)).as("the LATERAL invocation domain")
						.isEqualTo(Set.of("x"));
				assertThat(GraphFrameBindings.isSupplied(input, "g"))
						.as("copying does not turn an ordinary value into GRAPH authority")
						.isFalse();
			}
			assertSameGroupFrameFacts(genericEntry.before(), entry.before(), "Group entry");
			assertThat(entry.dynamicContext()).as("the Group receives the real LATERAL preparation context")
					.isEqualTo(genericEntry.dynamicContext())
					.isTrue();
			assertThat(entry.step()).as("the attached Group has a selected native candidate")
					.isInstanceOf(NativeGroupStep.class);
			assertThat(entry.fallbackReason()).as("the local write is checked before native admission")
					.isEqualTo("entryAssignment");
			assertAttachedGroupRoute(group, entry, nativeBefore, "copied boundary");
			for (List<BindingSet> rows : List.of(automaticRows, actualRows)) {
				assertThat(rows).hasSize(1);
				assertThat(GraphFrameBindings.isSupplied(rows.getFirst(), "g"))
						.as("the Group's local write does not create GRAPH authority")
						.isFalse();
				assertSameGroupFrameFacts(groupEntryFacts(expectedRows.getFirst(), group, null),
						groupEntryFacts(rows.getFirst(), group, null), "host output");
			}
			assertThat(groupEntryFacts(caller, group, null)).as("the original caller is unchanged")
					.isEqualTo(callerBefore);
		}
	}

	private static void assertSameGroupFrameFacts(GroupEntryFacts expected, GroupEntryFacts actual, String label) {
		assertAll(
				() -> assertThat(actual.logical()).as("logical mapping %s", label).isEqualTo(expected.logical()),
				() -> assertThat(actual.present()).as("binding presence %s", label).isEqualTo(expected.present()),
				() -> assertThat(actual.substitutionDomain()).as("substitution domain %s", label)
						.isEqualTo(expected.substitutionDomain()),
				() -> assertThat(actual.lateralPrivateInputs()).as("private inputs %s", label)
						.isEqualTo(expected.lateralPrivateInputs()),
				() -> assertThat(actual.withheld()).as("withheld inputs %s", label).isEqualTo(expected.withheld()),
				() -> assertThat(actual.currentWithheld()).as("current withheld inputs %s", label)
						.isEqualTo(expected.currentWithheld()),
				() -> assertThat(actual.effectiveProbe()).as("effective probes %s", label)
						.isEqualTo(expected.effectiveProbe()),
				() -> assertThat(actual.graphParameters()).as("GRAPH parameters %s", label)
						.isEqualTo(expected.graphParameters()),
				() -> assertThat(actual.supplied()).as("GRAPH authority %s", label).isEqualTo(expected.supplied()),
				() -> assertThat(actual.frame() != null).as("frame presence %s", label)
						.isEqualTo(expected.frame() != null),
				() -> assertThat(actual.visibleProbes()).as("visible probes %s", label)
						.isEqualTo(expected.visibleProbes()),
				() -> assertThat(actual.empty()).as("empty mapping %s", label).isEqualTo(expected.empty()));
	}

	private record AttachedGroupEntry(BindingSet bindings, GroupEntryFacts before, QueryEvaluationStep step,
			boolean dynamicContext, String fallbackReason) {
	}

	/** Observes the real prepared occurrence and delegates the original step without changing its input. */
	private static final class AttachedGroupProbe {
		private final List<AttachedGroupEntry> entries = new ArrayList<>();

		private AttachedGroupProbe(LmdbNativeEvaluationStrategy strategy, Group group) {
			doAnswer(invocation -> {
				QueryEvaluationStep prepared = (QueryEvaluationStep) invocation.callRealMethod();
				QueryEvaluationContext context = invocation.getArgument(1);
				return (QueryEvaluationStep) bindings -> {
					String fallback = prepared instanceof NativeGroupStep nativeGroup
							? nativeGroup.semanticEntryFallbackReason(bindings)
							: null;
					entries.add(new AttachedGroupEntry(bindings, groupEntryFacts(bindings, group, prepared), prepared,
							BindingFrameBindings.hasDynamicSubstitution(context), fallback));
					return prepared.evaluate(bindings);
				};
			}).when(strategy).precompileTupleExpr(same(group), any(QueryEvaluationContext.class));
		}

		private AttachedGroupEntry onlyEntrySince(int index, String label) {
			List<AttachedGroupEntry> current = entries.subList(index, entries.size());
			assertThat(current).as("actual prepared Group invocations %s", label).hasSize(1);
			return current.getFirst();
		}
	}

	private static long resetAttachedGroupMetrics(Group group) {
		group.setStringMetricActual(LmdbNativeExplain.EXECUTION_PATH, null);
		group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		return Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"));
	}

	private static void assertAttachedGroupRoute(Group group, AttachedGroupEntry entry, long nativeBefore,
			String label) {
		long nativeDelta = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual")) - nativeBefore;
		String execution = group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		String runtimePlan = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
		if (SCOPE_DIAGNOSTICS) {
			String planned = entry.step() instanceof LmdbNativePhysicalPlan physical ? physical.nativePhysicalPlan()
					: null;
			System.out.printf(
					"attached-group %s prepared=%s guard=%s nativeDelta=%d execution=%s planned=%s actual=%s%n",
					label, entry.step().getClass().getSimpleName(), entry.fallbackReason(), nativeDelta, execution,
					planned,
					runtimePlan);
		}
		assertThat(groupEntryFacts(entry.bindings(), group, entry.step()))
				.as("the actual Group entry and frame remain unchanged %s", label)
				.isEqualTo(entry.before());
		if (entry.step() instanceof NativeGroupStep nativeGroup) {
			assertThat(nativeGroup.originalExpr).as("native candidate pins the actual Group occurrence %s", label)
					.isSameAs(group);
			if (entry.fallbackReason() != null) {
				assertThat(nativeDelta).as("guard declines before Group native work %s", label).isZero();
				assertThat(execution).as("actual Group fallback reason %s", label)
						.contains("genericFallback(" + entry.fallbackReason() + ")");
			} else if (nativeDelta > 0) {
				assertThat(runtimePlan).as("actual Group runtime plan %s", label).isNotBlank();
			} else {
				assertThat(execution).as("explicit fallback or empty native seed %s", label)
						.containsAnyOf("genericFallback(", "emptySeed");
			}
		} else if (!(entry.step() instanceof LmdbNativePhysicalPlan)) {
			// An ordinary prepared Group is not proof that a native Group ran. Other physical step types are
			// reported separately because they may implement their own invocation telemetry.
			assertThat(nativeDelta).as("no native Group invocation for an ordinary prepared step %s", label).isZero();
		}
	}

	private static void assertUnobservedGroupRoute(Group unobserved, long unobservedBefore, Group observed,
			AttachedGroupEntry entry, long observedBefore, String label) {
		long unobservedDelta = Math.max(0L, unobserved.getLongMetricActual("nativeInvocationsActual"))
				- unobservedBefore;
		long observedDelta = Math.max(0L, observed.getLongMetricActual("nativeInvocationsActual")) - observedBefore;
		String unobservedPath = unobserved.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		if (SCOPE_DIAGNOSTICS) {
			System.out.printf("attached-group unobserved %s nativeDelta=%d execution=%s%n", label, unobservedDelta,
					unobservedPath);
		}
		if (entry.step() instanceof NativeGroupStep) {
			assertThat(unobservedDelta > 0).as("probe preserves actual Group native admission %s", label)
					.isEqualTo(observedDelta > 0);
			if (entry.fallbackReason() != null) {
				assertThat(unobservedPath).as("unobserved Group has the same guard %s", label)
						.contains("genericFallback(" + entry.fallbackReason() + ")");
			}
		}
	}

	private static void assertAttachedNativeGroup(Group observed, AttachedGroupEntry entry, long observedBefore,
			Group unobserved, long unobservedBefore, String label) {
		long observedDelta = Math.max(0L, observed.getLongMetricActual("nativeInvocationsActual")) - observedBefore;
		long unobservedDelta = Math.max(0L, unobserved.getLongMetricActual("nativeInvocationsActual"))
				- unobservedBefore;
		String observedPath = observed.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		String unobservedPath = unobserved.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		assertAll(
				() -> assertThat(entry.step()).as("prepared native Group for %s", label)
						.isInstanceOf(NativeGroupStep.class),
				() -> assertThat(entry.fallbackReason()).as("no Group entry guard for %s", label).isNull(),
				() -> assertThat(observedDelta).as("actual pinned native Group invocation for %s", label).isPositive(),
				() -> assertThat(observedPath).as("observed Group avoids fallback for %s", label)
						.isNotBlank()
						.doesNotContain("genericFallback"),
				() -> assertThat(unobservedDelta).as("actual unobserved native Group invocation for %s", label)
						.isPositive(),
				() -> assertThat(unobservedPath).as("unobserved Group avoids fallback for %s", label)
						.isNotBlank()
						.doesNotContain("genericFallback"));
	}

	private record ExactGroupHosts(Group group, QueryRoot root, Group referenceGroup, Group unobservedGroup,
			QueryEvaluationStep reference, QueryEvaluationStep unobserved, QueryEvaluationStep selected,
			AttachedGroupProbe probe) {
	}

	private record ExactGroupCall(List<Map<String, Value>> rows, List<Value> arguments, GroupEntryFacts before,
			GroupEntryFacts after, long rawBefore, long rawAfter, long nativeDelta, String execution,
			String runtimePlan) {
	}

	private record ExactGroupComparison(ExactGroupHosts hosts, AttachedGroupEntry entry, ExactGroupCall reference,
			ExactGroupCall unobserved, ExactGroupCall selected) {
	}

	private record ExactRawGroup(Group group, NativeGroupStep step, BindingSet input, ExactGroupCall call,
			String guard) {
	}

	private ExactGroupHosts prepareExactRootGroup(SailDataset dataset, Group group, QueryEvaluationContext context) {
		Group referenceGroup = group.clone();
		Group unobservedGroup = group.clone();
		for (Group candidate : List.of(group, referenceGroup, unobservedGroup)) {
			candidate.setRuntimeTelemetryEnabled(true);
			candidate.setExecutionSummaryEnabled(true);
		}
		QueryEvaluationStep reference = groupEmissionStrategy(dataset).genericOnlyView()
				.precompile(new QueryRoot(referenceGroup), context);
		QueryEvaluationStep unobserved = groupEmissionStrategy(dataset)
				.precompile(new QueryRoot(unobservedGroup), context);
		LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
		AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
		QueryRoot root = new QueryRoot(group);
		QueryEvaluationStep selected = strategy.precompile(root, context);
		return new ExactGroupHosts(group, root, referenceGroup, unobservedGroup, reference, unobserved, selected,
				probe);
	}

	private static ExactGroupCall observeExactGroupCall(QueryEvaluationStep step, Group group, BindingSet input,
			List<Value> arguments) {
		GroupEntryFacts before = groupEntryFacts(input, group, null);
		arguments.clear();
		long rawBefore = group.getLongMetricActual("nativeInvocationsActual");
		long nativeBefore = resetAttachedGroupMetrics(group);
		List<Map<String, Value>> rows;
		try (var iteration = step.evaluate(input)) {
			rows = mappings(iteration);
		}
		long rawAfter = group.getLongMetricActual("nativeInvocationsActual");
		return new ExactGroupCall(rows, List.copyOf(arguments), before, groupEntryFacts(input, group, null), rawBefore,
				rawAfter, Math.max(0L, rawAfter) - nativeBefore,
				group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH),
				group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN));
	}

	private static ExactGroupComparison observeExactRootGroup(ExactGroupHosts hosts, BindingSet input,
			List<Value> arguments, String label) {
		ExactGroupCall reference = observeExactGroupCall(hosts.reference(), hosts.referenceGroup(), input, arguments);
		ExactGroupCall unobserved = observeExactGroupCall(hosts.unobserved(), hosts.unobservedGroup(), input,
				arguments);
		int entriesBefore = hosts.probe().entries.size();
		ExactGroupCall selected = observeExactGroupCall(hosts.selected(), hosts.group(), input, arguments);
		AttachedGroupEntry entry = hosts.probe().onlyEntrySince(entriesBefore, label);
		if (SCOPE_DIAGNOSTICS) {
			System.out.printf("exact-root-group %s capturedDynamicContext=%s reference=%s unobserved=%s selected=%s%n",
					label, entry.dynamicContext(), reference, unobserved, selected);
		}
		describeExactGroupEntry(label, hosts.group(), entry.step(), entry.bindings());
		return new ExactGroupComparison(hosts, entry, reference, unobserved, selected);
	}

	private static void describeExactGroupEntry(String label, Group group, QueryEvaluationStep step, BindingSet input) {
		if (!SCOPE_DIAGNOSTICS) {
			return;
		}
		GroupInvocationBindings.Prepared capability = GroupInvocationBindings.prepared(input);
		if (step instanceof NativeGroupStep nativeGroup) {
			Set<String> withheld = NativeEntryBindingVariant.problemBindings(input, nativeGroup.optionalOnlyNames,
					nativeGroup.context);
			Set<String> seeded = new TreeSet<>();
			for (String name : nativeGroup.layout.slotNames()) {
				if (input.hasBinding(name) && !withheld.contains(name)) {
					seeded.add(name);
				}
			}
			System.out.printf("exact-group-entry %s prepared=%s original=%s capability=%s matches=%s admits=%s "
					+ "targetDynamicContext=%s targetStaticDomain=%s witness=%s seeded=%s withheld=%s wholeInjection=%s "
					+ "guardAfterEvaluation=%s planned=%s facts=%s%n",
					label, step.getClass().getSimpleName(), nativeGroup.originalExpr == group, capability != null,
					capability != null && capability.represents(group), capability != null && capability.admits(input),
					BindingFrameBindings.hasDynamicSubstitution(nativeGroup.context),
					nativeGroup.context.getSubstitutionBindingNames(),
					nativeGroup.invocationWitness != null, seeded, withheld,
					nativeGroup.inputInjectionProof == null ? null : nativeGroup.inputInjectionProof.test(seeded),
					nativeGroup.semanticEntryFallbackReason(input), nativeGroup.nativePhysicalPlan(),
					groupEntryFacts(input, group, step));
		} else {
			System.out.printf("exact-group-entry %s prepared=%s capability=%s facts=%s%n", label,
					step.getClass().getSimpleName(), capability != null, groupEntryFacts(input, group, step));
		}
	}

	private ExactRawGroup observeExactRawGroup(SailDataset dataset, Group group, QueryEvaluationContext context,
			BindingSet input, List<Value> arguments, String label) {
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(group, context,
				groupEmissionStrategy(dataset),
				(NativeLmdbQuerySource) dataset);
		assertThat(compiled).as("direct compiler candidate %s", label).isInstanceOf(NativeGroupStep.class);
		NativeGroupStep nativeGroup = (NativeGroupStep) compiled;
		ExactGroupCall call = observeExactGroupCall(compiled, group, input, arguments);
		String guard = nativeGroup.semanticEntryFallbackReason(input);
		if (SCOPE_DIAGNOSTICS) {
			System.out.printf("exact-raw-group %s observation=%s%n", label, call);
		}
		describeExactGroupEntry(label, group, compiled, input);
		return new ExactRawGroup(group, nativeGroup, input, call, guard);
	}

	private static void assertExactGroupBags(SoftAssertions softly, ExactGroupComparison observation,
			List<Map<String, Value>> expected, String label) {
		for (ExactGroupCall call : List.of(observation.reference(), observation.unobserved(), observation.selected())) {
			softly.assertThat(call.rows()).as("exact root bag %s", label).containsExactlyElementsOf(expected);
			softly.assertThat(call.after()).as("exact root caller unchanged %s", label).isEqualTo(call.before());
		}
		ExactGroupHosts hosts = observation.hosts();
		AttachedGroupEntry entry = observation.entry();
		softly.assertThat(hosts.root().getArg()).isSameAs(hosts.group());
		softly.assertThat(hosts.group().getParentNode()).isSameAs(hosts.root());
		softly.assertThat(GroupInvocationBindings.prepared(hosts.group()))
				.as("preparation lifetime ended %s", label)
				.isNull();
		GroupInvocationBindings.Prepared capability = GroupInvocationBindings.prepared(entry.bindings());
		softly.assertThat(capability).as("real root Group capability %s", label).isNotNull();
		if (capability != null) {
			softly.assertThat(capability.represents(hosts.group())).isTrue();
			softly.assertThat(capability.admits(entry.bindings())).isTrue();
		}
		softly.assertThat(entry.step()).as("pinned Group candidate %s", label).isInstanceOf(NativeGroupStep.class);
		if (entry.step() instanceof NativeGroupStep nativeGroup) {
			softly.assertThat(nativeGroup.originalExpr).isSameAs(hosts.group());
		}
		softly.assertThat(groupEntryFacts(entry.bindings(), hosts.group(), entry.step()))
				.as("real Group entry unchanged %s", label)
				.isEqualTo(entry.before());
	}

	private static void assertExactGroupNative(SoftAssertions softly, ExactGroupComparison observation,
			boolean requireWitness, String label) {
		if (requireWitness && observation.entry().step() instanceof NativeGroupStep nativeGroup) {
			softly.assertThat(nativeGroup.invocationWitness).as("selected semantic witness %s", label).isNotNull();
		}
		softly.assertThat(observation.entry().fallbackReason()).as("actual entry guard %s", label).isNull();
		for (ExactGroupCall call : List.of(observation.unobserved(), observation.selected())) {
			softly.assertThat(call.nativeDelta()).as("first actual root native invocation %s", label).isPositive();
			softly.assertThat(call.execution())
					.as("this invocation's execution path %s", label)
					.isNotBlank()
					.doesNotContain("genericFallback");
			softly.assertThat(call.runtimePlan()).as("this invocation's runtime plan %s", label).isNotBlank();
		}
	}

	private static void assertExactGroupFallback(SoftAssertions softly, ExactGroupCall call, String reason,
			String label) {
		softly.assertThat(call.nativeDelta()).as("no native Group work %s", label).isZero();
		softly.assertThat(call.execution())
				.as("this invocation's fallback %s", label)
				.contains("genericFallback(" + reason + ")");
		softly.assertThat(call.runtimePlan()).as("this invocation opened no native plan %s", label).isNull();
	}

	private static void assertExactRawGroup(SoftAssertions softly, ExactRawGroup raw, List<Map<String, Value>> expected,
			String fallback, String label) {
		softly.assertThat(raw.group().getParentNode()).as("raw target is detached %s", label).isNull();
		softly.assertThat(GroupInvocationBindings.prepared(raw.group())).isNull();
		GroupInvocationBindings.Prepared sourceCapability = GroupInvocationBindings.prepared(raw.input());
		if (sourceCapability != null) {
			softly.assertThat(sourceCapability.represents(raw.group()))
					.as("source authority is not target authority %s", label)
					.isFalse();
		}
		softly.assertThat(raw.step().invocationWitness)
				.as("raw compilation gains no target witness %s", label)
				.isNull();
		softly.assertThat(raw.call().rows()).as("raw bag %s", label).containsExactlyElementsOf(expected);
		softly.assertThat(raw.call().after()).as("raw caller unchanged %s", label).isEqualTo(raw.call().before());
		softly.assertThat(raw.guard()).as("raw guard %s", label).isEqualTo(fallback);
		if (fallback != null) {
			assertExactGroupFallback(softly, raw.call(), fallback, label);
		} else {
			softly.assertThat(raw.call().nativeDelta()).as("legacy injection path %s", label).isPositive();
			softly.assertThat(raw.call().runtimePlan()).isNotBlank();
		}
	}

	@Test
	void actualRootInvokesExactGroupedLateralInputTransitions() {
		// Both legacy methods use this exact one-result tuple function, LATERAL, key and COUNT(x).
		String uri = "urn:native-tuple-input:grouped";
		Value caller = literal("caller");
		Value local = literal("local");
		List<Value> arguments = new ArrayList<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				arguments.add(args[0]);
				return new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry registry = TupleFunctionRegistry.getInstance();
		var previous = registry.add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Group group = new Group(new Lateral(new SingletonSet(), call, Set.of("x")), List.of("x"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			Group rawGroup = group.clone();
			ExactGroupHosts hosts = prepareExactRootGroup(dataset, group, context);
			QueryBindingSet original = new QueryBindingSet();
			original.addBinding("x", caller);
			BindingSet withheld = BindingFrameBindings.without(original, Set.of("x"), context);
			QueryBindingSet presentNull = new QueryBindingSet();
			presentNull.setBinding("x", null);
			SoftAssertions softly = new SoftAssertions();
			for (String kind : List.of("plain", "withheld", "present-null")) {
				BindingSet input = kind.equals("plain") ? original : kind.equals("withheld") ? withheld : presentNull;
				List<Map<String, Value>> expected = kind.equals("withheld")
						? List.of(row("x", local, "count", groupInteger(1)))
						: List.of();
				ExactRawGroup raw = observeExactRawGroup(dataset, rawGroup, context, input, arguments, kind);
				ExactGroupComparison actual = observeExactRootGroup(hosts, input, arguments, kind);
				assertExactRawGroup(softly, raw, expected, kind.equals("withheld") ? null : "groupInput", kind);
				assertExactGroupBags(softly, actual, expected, kind);
				List<Value> expectedArguments = kind.equals("present-null") ? List.of() : List.of(caller);
				for (ExactGroupCall observation : List.of(raw.call(), actual.reference(), actual.unobserved(),
						actual.selected())) {
					softly.assertThat(observation.arguments())
							.as("exact tuple arguments %s", kind)
							.containsExactlyElementsOf(expectedArguments);
				}
				softly.assertThat(BindingFrameBindings.substitutionDomain(actual.entry().bindings())).isNull();
				if (kind.equals("present-null")) {
					softly.assertThat(actual.entry().bindings().hasBinding("x")).isTrue();
					softly.assertThat(actual.entry().bindings().getValue("x")).isNull();
					softly.assertThat(actual.entry().fallbackReason()).isEqualTo("groupInput");
					assertExactGroupFallback(softly, actual.selected(), "groupInput", kind);
					assertExactGroupFallback(softly, actual.unobserved(), "groupInput", kind);
				} else {
					// The withheld arm already has an empty logical seed; its native counter does not prove witness
					// admission.
					assertExactGroupNative(softly, actual, kind.equals("plain"), kind);
				}
			}
			softly.assertAll();
		} finally {
			registry.remove(function);
			previous.ifPresent(registry::add);
		}
	}

	private BindingSet exactGroupEmptyDomainFromExists(SailDataset dataset, QueryEvaluationContext context,
			BindingSet caller) {
		Group producer = new Group(new LeftJoin(new SingletonSet(), values("marker", literal("marker"))),
				List.of("marker"));
		Exists exists = new Exists(producer);
		LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
		AttachedGroupProbe probe = new AttachedGroupProbe(strategy, producer);
		QueryValueEvaluationStep selected = strategy.precompile(exists, context);
		GroupEntryFacts before = groupEntryFacts(caller, producer, null);
		assertThat(selected.evaluate(caller)).as("the real EMPTY-domain producer executes")
				.isEqualTo(VF.createLiteral(true));
		AttachedGroupEntry entry = probe.onlyEntrySince(0, "exact gate EMPTY producer");
		assertThat(QueryEvaluationUtility.existsSubstitutionInputs(producer).bindingNames()).containsExactly("marker");
		assertThat(entry.dynamicContext()).isTrue();
		assertThat(BindingFrameBindings.substitutionDomain(entry.bindings())).isNotNull().isEmpty();
		assertThat(entry.bindings().getBindingNames()).containsExactly("x");
		assertThat(entry.bindings().getValue("x")).isEqualTo(caller.getValue("x"));
		GroupInvocationBindings.Prepared capability = GroupInvocationBindings.prepared(entry.bindings());
		assertThat(capability).isNotNull();
		assertThat(capability.represents(producer)).isTrue();
		assertThat(capability.admits(entry.bindings())).isTrue();
		assertThat(groupEntryFacts(caller, producer, null)).isEqualTo(before);
		return entry.bindings();
	}

	@ParameterizedTest(name = "exact gate family={0}")
	@ValueSource(strings = { "caller-bound", "values", "compatibility", "compatibility-empty" })
	void actualRootInvokesExactOptionalGateFamilies(String family) {
		boolean compatibility = family.startsWith("compatibility");
		String prefix = compatibility ? "urn:optional-match:"
				: family.equals("values") ? "urn:optional-values-gate:"
						: "urn:optional-gate-input:";
		IRI subject = VF.createIRI(prefix + "subject");
		IRI predicate = VF.createIRI(prefix + "predicate");
		IRI outer = VF.createIRI(prefix + "outer");
		IRI inner = VF.createIRI(prefix + "inner");
		IRI outerHit = VF.createIRI(prefix + "outer-hit");
		IRI unrelated = VF.createIRI(prefix + "unrelated");
		Value localHit = compatibility ? VF.createLiteral(true)
				: family.equals("values") ? VF.createIRI(prefix + "local-hit") : literal("local-hit");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<IRI> resources = compatibility ? List.of(subject, outer, inner)
					: family.equals("values") ? List.of(subject, outer, inner, outerHit, (IRI) localHit, unrelated)
							: List.of(subject, outer, inner, outerHit, unrelated);
			for (IRI resource : resources) {
				connection.add(resource, predicate, literal("witness"));
			}
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryBindingSet caller = new QueryBindingSet();
			caller.addBinding("x", outer);
			BindingSet input = family.equals("compatibility-empty")
					? exactGroupEmptyDomainFromExists(dataset, context, caller)
					: caller;
			SoftAssertions softly = new SoftAssertions();
			for (boolean gated : List.of(false, true)) {
				TupleExpr right = family.equals("values") ? valuesWithOptionalHeader(false, inner, localHit)
						: new Extension(values("x", inner), new ExtensionElem(new ValueConstant(localHit), "hit"));
				TupleExpr optional = new LeftJoin(new SingletonSet(), right);
				if (gated) {
					optional = new Filter(optional, new Bound(Var.of("hit")));
				}
				StatementPattern pattern = new StatementPattern(Var.of("s", subject, false, true),
						Var.of("p", predicate, false, true), Var.of("v"));
				Group group = new Group(new Join(optional, pattern), compatibility ? List.of("x")
						: List.of("x", "hit", "unrelated"));
				group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
				String label = family + "/gated=" + gated;
				List<Map<String, Value>> expected = gated || family.equals("compatibility-empty") ? List.of()
						: List.of(row("x", outer, "count", groupInteger(1)));
				ExactRawGroup raw = observeExactRawGroup(dataset, group.clone(), context, input, new ArrayList<>(),
						label);
				ExactGroupHosts hosts = prepareExactRootGroup(dataset, group, context);
				ExactGroupComparison actual = observeExactRootGroup(hosts, input, new ArrayList<>(), label);
				String rawGuard = gated ? "groupInput" : family.equals("compatibility-empty") ? null : "optionalEntry";
				assertExactRawGroup(softly, raw, expected, rawGuard, label);
				assertExactGroupBags(softly, actual, expected, label);
				softly.assertThat(actual.entry().bindings().getValue("x")).isEqualTo(outer);
				softly.assertThat(actual.entry().bindings().hasBinding("hit")).isFalse();
				if (family.equals("compatibility-empty")) {
					softly.assertThat(BindingFrameBindings.substitutionDomain(actual.entry().bindings()))
							.isNotNull()
							.isEmpty();
					softly.assertThat(GroupInvocationBindings.prepared(actual.entry().bindings()))
							.as("the target root issued a fresh capability")
							.isNotSameAs(GroupInvocationBindings.prepared(input));
				} else {
					softly.assertThat(BindingFrameBindings.substitutionDomain(actual.entry().bindings())).isNull();
				}
				if (gated || family.equals("compatibility-empty")) {
					assertExactGroupNative(softly, actual, gated, label);
				} else {
					softly.assertThat(actual.entry().fallbackReason()).isEqualTo("optionalEntry");
					assertExactGroupFallback(softly, actual.selected(), "optionalEntry", label);
					assertExactGroupFallback(softly, actual.unobserved(), "optionalEntry", label);
				}
			}
			softly.assertAll();
		}
	}

	private BindingSet exactDeclaredOutputGraphProducer(SailDataset dataset, IRI graph) {
		// A producer-only named dataset permits this empty graph without adding statements to the target data.
		SimpleDataset producerDataset = new SimpleDataset();
		producerDataset.addNamedGraph(graph);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(producerDataset);
		Projection projection = new Projection(new SingletonSet(), new ProjectionElemList(), true);
		projection.setProjectionContext(Var.of("graphCaller", graph, false, true));
		projection.setInheritedGraphParameter("g");
		Graph host = new Graph(Var.of("graphCaller", graph, true, true), projection);
		List<BindingSet> entries = new ArrayList<>();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(
				new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null) {
			@Override
			protected QueryEvaluationStep prepare(SingletonSet singleton, QueryEvaluationContext activeContext)
					throws QueryEvaluationException {
				QueryEvaluationStep original = super.prepare(singleton, activeContext);
				return bindings -> {
					entries.add(bindings);
					return original.evaluate(bindings);
				};
			}
		};
		QueryBindingSet caller = new QueryBindingSet();
		try (var rows = strategy.precompile(host, context).evaluate(caller)) {
			assertThat(mappings(rows)).containsExactly(Map.<String, Value>of());
		}
		assertThat(caller.isEmpty()).isTrue();
		assertThat(entries).as("the actual GRAPH/Projection/Singleton edge executes").hasSize(1);
		BindingSet supplied = entries.getFirst();
		assertThat(supplied.getBindingNames()).containsExactly("g");
		assertThat(supplied.getValue("g")).isEqualTo(graph);
		assertThat(GraphFrameBindings.isSupplied(supplied, "g")).isTrue();
		assertThat(GroupInvocationBindings.prepared(supplied)).as("the GRAPH producer did not invoke a Group").isNull();
		assertThat(BindingFrameBindings.substitutionDomain(supplied)).isNull();
		assertThat(BindingFrameBindings.lateralPrivateInputs(supplied)).isEmpty();
		assertThat(BindingFrameBindings.hasLookupProbe(supplied, name -> true)).isFalse();
		assertThat(BindingFrameBindings.materializeWithheldInputs(supplied)).isSameAs(supplied);
		return supplied;
	}

	@ParameterizedTest(name = "exact declared output producer={0}, equal={1}")
	@MethodSource("exactDeclaredOutputCases")
	void actualGraphAndRootInvokeExactDeclaredOutputGroups(String producer, boolean equal) {
		IRI graph = VF.createIRI("urn:optional-output:graph");
		IRI other = VF.createIRI("urn:optional-output:other");
		IRI predicate = VF.createIRI("urn:optional-output:p");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(graph, predicate, other);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			// supply is the internal GRAPH provenance constructor; this manual baseline does not prove an evaluated
			// producer.
			BindingSet manual = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
			BindingSet supplied = exactDeclaredOutputGraphProducer(dataset, graph);
			SoftAssertions softly = new SoftAssertions();
			for (boolean gated : List.of(false, true)) {
				Value right = equal ? graph : other;
				TupleExpr output = producer.equals("values") ? values("g", right)
						: new Projection(values("local", right),
								new ProjectionElemList(new ProjectionElem("local", "g")), false);
				LeftJoin optional = new LeftJoin(values("o", literal("o")),
						new Join(output, values("z", literal("z"))));
				TupleExpr selectedOptional = gated ? new Filter(optional, new Bound(Var.of("z"))) : optional;
				StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true),
						Var.of("v"));
				Group group = new Group(new Join(selectedOptional, pattern), List.of("g"));
				group.addGroupElement(new GroupElem("count", new Count(Var.of("z"), false)));
				List<Map<String, Value>> expected = gated && !equal ? List.of()
						: List.of(row("g", graph, "count", groupInteger(equal ? 1 : 0)));
				String label = producer + "/equal=" + equal + "/gated=" + gated;
				ExactRawGroup raw = observeExactRawGroup(dataset, group.clone(), context, manual, new ArrayList<>(),
						label + "/raw-manual");
				ExactGroupComparison manualRoot = observeExactRootGroup(
						prepareExactRootGroup(dataset, group.clone(), context),
						manual, new ArrayList<>(), label + "/manual-root-diagnostic");
				ExactGroupComparison actual = observeExactRootGroup(prepareExactRootGroup(dataset, group, context),
						supplied,
						new ArrayList<>(), label + "/genuine-GRAPH-root");
				assertExactRawGroup(softly, raw, expected, "groupInput", label);
				// No permanent positive native-route promise is made for manually constructed provenance.
				assertExactGroupBags(softly, manualRoot, expected, label + "/manual-root-diagnostic");
				assertExactGroupBags(softly, actual, expected, label + "/genuine-GRAPH-root");
				for (ExactGroupComparison observation : List.of(manualRoot, actual)) {
					softly.assertThat(observation.entry().bindings().getBindingNames()).containsExactly("g");
					softly.assertThat(observation.entry().bindings().getValue("g")).isEqualTo(graph);
					softly.assertThat(GraphFrameBindings.isSupplied(observation.entry().bindings(), "g")).isTrue();
					softly.assertThat(BindingFrameBindings.substitutionDomain(observation.entry().bindings())).isNull();
				}
				assertExactGroupNative(softly, actual, true, label + "/genuine-GRAPH-root");
			}
			softly.assertAll();
		}
	}

	private static Stream<Arguments> exactDeclaredOutputCases() {
		return Stream.of("values", "alias")
				.flatMap(producer -> Stream.of(false, true)
						.map(equal -> Arguments.of(producer, equal)));
	}

	private BindingSet graphLawProducerInput(SailDataset dataset, BindingSet caller, Map<String, IRI> grants) {
		BindingSet input = caller;
		for (Map.Entry<String, IRI> grant : new TreeMap<>(grants).entrySet()) {
			SimpleDataset producerDataset = new SimpleDataset();
			producerDataset.addNamedGraph(grant.getValue());
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal(producerDataset);
			Projection producer = new Projection(new SingletonSet(), new ProjectionElemList(input.getBindingNames()
					.stream()
					.sorted()
					.map(ProjectionElem::new)
					.toList()), true);
			producer.setProjectionContext(Var.of("graphCaller", grant.getValue(), false, true));
			producer.setInheritedGraphParameter(grant.getKey());
			Graph graph = new Graph(Var.of("graphCaller", grant.getValue(), true, true), producer);
			List<BindingSet> entries = new ArrayList<>();
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null) {
				@Override
				protected QueryEvaluationStep prepare(SingletonSet singleton, QueryEvaluationContext activeContext)
						throws QueryEvaluationException {
					QueryEvaluationStep original = super.prepare(singleton, activeContext);
					return bindings -> {
						entries.add(bindings);
						return original.evaluate(bindings);
					};
				}
			};
			List<Map<String, Value>> projected;
			try (var rows = strategy.precompile(graph, context).evaluate(input)) {
				projected = mappings(rows);
			}
			Map<String, Value> previous = new TreeMap<>();
			for (String name : input.getBindingNames()) {
				previous.put(name, input.getValue(name));
			}
			assertThat(projected).containsExactly(previous);
			assertThat(entries).as("the real GRAPH/Projection/Singleton producer executes once").hasSize(1);
			input = entries.getFirst();
			assertThat(GraphFrameBindings.isSupplied(input, grant.getKey())).isTrue();
			assertThat(input.getValue(grant.getKey())).isEqualTo(grant.getValue());
		}
		for (Map.Entry<String, IRI> grant : grants.entrySet()) {
			assertThat(GraphFrameBindings.isSupplied(input, grant.getKey())).isTrue();
			assertThat(input.getValue(grant.getKey())).isEqualTo(grant.getValue());
		}
		assertThat(GroupInvocationBindings.prepared(input)).as("GRAPH producers issue no Group token").isNull();
		assertThat(BindingFrameBindings.substitutionDomain(input)).isNull();
		assertThat(BindingFrameBindings.lateralPrivateInputs(input)).isEmpty();
		assertThat(BindingFrameBindings.hasLookupProbe(input, name -> true)).isFalse();
		assertThat(BindingFrameBindings.materializeWithheldInputs(input)).isSameAs(input);
		return input;
	}

	private record GraphLawProjectionScope(Projection occurrence, List<String> pairs, boolean subquery,
			boolean contextEnclosing, boolean effectiveEnclosing, GroupEntryFacts input) {
	}

	private ExactGroupHosts graphLawObservedReference(SailDataset dataset, ExactGroupHosts hosts,
			QueryEvaluationContext context, List<GraphLawProjectionScope> scopes) {
		DefaultEvaluationStrategy reference = new DefaultEvaluationStrategy(
				new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null) {
			@Override
			protected QueryEvaluationStep prepare(Projection projection, QueryEvaluationContext activeContext)
					throws QueryEvaluationException {
				QueryEvaluationStep original = super.prepare(projection, activeContext);
				List<String> pairs = projection.getProjectionElemList()
						.getElements()
						.stream()
						.map(element -> element.getName() + "->"
								+ element.getProjectionAlias().orElse(element.getName()))
						.toList();
				boolean subquery = projection.isSubquery();
				boolean enclosing = activeContext.hasEnclosingProjection();
				boolean effective = ProjectionIterator.hasEnclosingProjection(projection, activeContext);
				return bindings -> {
					scopes.add(new GraphLawProjectionScope(projection, pairs, subquery, enclosing, effective,
							groupEntryFacts(bindings, projection, original)));
					return original.evaluate(bindings);
				};
			}
		};
		QueryEvaluationStep generic = reference.precompile((QueryRoot) hosts.referenceGroup().getParentNode(), context);
		return new ExactGroupHosts(hosts.group(), hosts.root(), hosts.referenceGroup(), hosts.unobservedGroup(),
				generic,
				hosts.unobserved(), hosts.selected(), hosts.probe());
	}

	private static void assertGraphLawBagAndRoute(SoftAssertions softly, ExactGroupComparison observation,
			List<Map<String, Value>> expected, boolean requireFallback, String label) {
		for (ExactGroupCall call : List.of(observation.reference(), observation.unobserved(), observation.selected())) {
			softly.assertThat(call.rows())
					.as("independent exact graph-law bag %s", label)
					.containsExactlyElementsOf(expected);
			softly.assertThat(call.after()).as("graph-law caller unchanged %s", label).isEqualTo(call.before());
		}
		AttachedGroupEntry entry = observation.entry();
		GroupInvocationBindings.Prepared token = GroupInvocationBindings.prepared(entry.bindings());
		softly.assertThat(token).as("the real root issues token authority only %s", label).isNotNull();
		if (token != null) {
			softly.assertThat(token.represents(observation.hosts().group())).isTrue();
			softly.assertThat(token.admits(entry.bindings())).isTrue();
		}
		softly.assertThat(groupEntryFacts(entry.bindings(), observation.hosts().group(), entry.step()))
				.as("actual graph-law Group entry unchanged %s", label)
				.isEqualTo(entry.before());
		for (ExactGroupCall call : List.of(observation.unobserved(), observation.selected())) {
			if (requireFallback || call.nativeDelta() == 0) {
				softly.assertThat(call.nativeDelta()).as("unproved barrier opens no native Group %s", label).isZero();
				softly.assertThat(call.runtimePlan()).as("no actual native plan %s", label).isNull();
				if (entry.step() instanceof NativeGroupStep) {
					softly.assertThat(entry.fallbackReason()).as("explicit semantic refusal %s", label).isNotBlank();
					softly.assertThat(call.execution()).contains("genericFallback(" + entry.fallbackReason() + ")");
				}
			} else {
				// A retaining boundary may acquire a complete proof later; bag correctness alone never proves that
				// route.
				softly.assertThat(entry.fallbackReason()).isNull();
				softly.assertThat(call.runtimePlan()).isNotBlank();
				softly.assertThat(call.execution()).isNotBlank().doesNotContain("genericFallback");
				softly.assertThat(entry.step()).isInstanceOf(NativeGroupStep.class);
				if (entry.step() instanceof NativeGroupStep nativeGroup) {
					softly.assertThat(nativeGroup.invocationWitness).isNotNull();
				}
			}
		}
	}

	@ParameterizedTest(name = "left retains entry={0}, z rows={1}, outside grant={2}")
	@MethodSource("graphLawNestedOptionalCases")
	void graphGroupNestedOptionalPreservesProjectionEmptiness(boolean retainingLeft, int rows, boolean outsideGrant) {
		IRI graph = VF.createIRI("urn:optional-output:graph");
		IRI other = VF.createIRI("urn:optional-output:other");
		IRI predicate = VF.createIRI("urn:optional-output:p");
		IRI outside = VF.createIRI("urn:optional-output:outside");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(graph, predicate, other);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			BindingSet input = graphLawProducerInput(dataset, new QueryBindingSet(), outsideGrant
					? Map.of("g", graph, "h", outside)
					: Map.of("g", graph));
			Value z = literal("z");
			BindingSetAssignment zs = rows == 1 ? values("z", z) : values("z", z, z);
			TupleExpr p = retainingLeft ? zs
					: new Projection(zs, new ProjectionElemList(new ProjectionElem("z")), false);
			Projection q = new Projection(values("local", other),
					new ProjectionElemList(new ProjectionElem("local", "g")), false);
			LeftJoin r = new LeftJoin(p, q);
			LeftJoin t = new LeftJoin(values("o", literal("o")), r);
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true),
					Var.of("v"));
			Group group = new Group(new Join(t, pattern), List.of("g"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("z"), false)));
			List<GraphLawProjectionScope> scopes = new ArrayList<>();
			ExactGroupHosts hosts = graphLawObservedReference(dataset, prepareExactRootGroup(dataset, group, context),
					context, scopes);
			String label = "nested/retaining=" + retainingLeft + "/rows=" + rows + "/outside=" + outsideGrant;
			ExactGroupComparison actual = observeExactRootGroup(hosts, input, new ArrayList<>(), label);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("graph-law-projection-scopes %s scopes=%s%n", label, scopes);
			}
			Map<String, Value> expected = new TreeMap<>(
					row("g", graph, "count", groupInteger(retainingLeft ? rows : 0)));
			if (outsideGrant) {
				expected.put("h", outside);
			}
			SoftAssertions softly = new SoftAssertions();
			assertGraphLawBagAndRoute(softly, actual, List.of(expected), !retainingLeft, label);
			softly.assertThat(scopes).as("actual generic Projection inputs and modes are captured").isNotEmpty();
			LeftJoin referenceT = (LeftJoin) ((Join) hosts.referenceGroup().getArg()).getLeftArg();
			LeftJoin referenceR = (LeftJoin) referenceT.getRightArg();
			Projection referenceQ = (Projection) referenceR.getRightArg();
			Projection referenceP = retainingLeft ? null : (Projection) referenceR.getLeftArg();
			softly.assertThat(scopes.stream()
					.anyMatch(scope -> scope.occurrence() == referenceQ
							&& scope.pairs().equals(List.of("local->g"))))
					.as("the exact Q alias is observed")
					.isTrue();
			if (referenceP != null) {
				softly.assertThat(scopes.stream()
						.anyMatch(scope -> scope.occurrence() == referenceP
								&& scope.pairs().equals(List.of("z->z"))))
						.as("the exact P drop is observed")
						.isTrue();
			}
			for (GraphLawProjectionScope scope : scopes) {
				softly.assertThat(scope.occurrence() == referenceQ || scope.occurrence() == referenceP)
						.as("only the exact target projections supply these observations")
						.isTrue();
				softly.assertThat(scope.subquery()).isFalse();
				softly.assertThat(scope.contextEnclosing()).isFalse();
				softly.assertThat(scope.effectiveEnclosing()).as("outer Projection output mode").isFalse();
			}
			if (!retainingLeft && actual.entry().step() instanceof NativeGroupStep nativeGroup) {
				// The current bounded capability excludes these projection barriers; later scopes need their own proof.
				softly.assertThat(nativeGroup.invocationWitness)
						.as("no residual native capability crosses nested OPTIONAL")
						.isNull();
			}
			if (outsideGrant && actual.entry().step() instanceof NativeGroupStep nativeGroup) {
				softly.assertThat(nativeGroup.layout.slot("h"))
						.as("the second genuine grant is outside the layout")
						.isNull();
				softly.assertThat(GraphFrameBindings.isSupplied(actual.entry().bindings(), "h")).isTrue();
			}
			softly.assertAll();
		}
	}

	private static Stream<Arguments> graphLawNestedOptionalCases() {
		return Stream.of(Arguments.of(false, 1, false), Arguments.of(false, 2, false), Arguments.of(true, 1, false),
				Arguments.of(true, 2, false), Arguments.of(false, 1, true));
	}

	@ParameterizedTest(name = "z has a genuine GRAPH grant={0}")
	@ValueSource(booleans = { false, true })
	void graphGroupGateChecksTheWholeActualEntryDomain(boolean graphZ) {
		IRI graph = VF.createIRI("urn:optional-output:graph");
		IRI other = VF.createIRI("urn:optional-output:other");
		IRI predicate = VF.createIRI("urn:optional-output:p");
		IRI z = VF.createIRI("urn:optional-output:z-entry");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(graph, predicate, other);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryBindingSet caller = new QueryBindingSet();
			if (!graphZ) {
				caller.addBinding("z", z);
			}
			BindingSet input = graphLawProducerInput(dataset, caller,
					graphZ ? Map.of("g", graph, "z", z) : Map.of("g", graph));
			SoftAssertions softly = new SoftAssertions();
			for (boolean gated : List.of(false, true)) {
				LeftJoin optional = new LeftJoin(values("o", literal("o")),
						new Join(values("g", other), values("z", literal("z"))));
				TupleExpr selected = gated ? new Filter(optional, new Bound(Var.of("z"))) : optional;
				StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true),
						Var.of("v"));
				Group group = new Group(new Join(selected, pattern), List.of("g"));
				group.addGroupElement(new GroupElem("count", new Count(Var.of("z"), false)));
				String label = "whole-entry/graphZ=" + graphZ + "/gated=" + gated;
				ExactGroupComparison actual = observeExactRootGroup(prepareExactRootGroup(dataset, group, context),
						input,
						new ArrayList<>(), label);
				assertGraphLawBagAndRoute(softly, actual, List.of(row("g", graph, "z", z, "count", groupInteger(1))),
						gated || !graphZ, label);
				softly.assertThat(actual.entry().bindings().getBindingNames()).containsExactlyInAnyOrder("g", "z");
				softly.assertThat(GraphFrameBindings.isSupplied(actual.entry().bindings(), "g")).isTrue();
				softly.assertThat(GraphFrameBindings.isSupplied(actual.entry().bindings(), "z")).isEqualTo(graphZ);
				softly.assertThat(actual.entry().bindings().getValue("z")).isEqualTo(z);
				if (gated && actual.entry().step() instanceof NativeGroupStep nativeGroup) {
					softly.assertThat(nativeGroup.optionalCallerRequirement.gateNames()).contains("z");
					softly.assertThat(actual.entry().fallbackReason())
							.as("the full-domain gate runs before GRAPH admission")
							.isEqualTo("optionalEntry");
				}
			}
			softly.assertAll();
		}
	}

	@Test
	void groupedNativeLateralReadsWithheldTupleArgumentWithoutConstrainingOutput() {
		String uri = "urn:native-tuple-input:grouped";
		Value caller = literal("caller");
		Value local = literal("local");
		List<Value> observed = new ArrayList<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add(args[0]);
				return new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Lateral lateral = new Lateral(new SingletonSet(), call, Set.of("x"));
			Group host = new Group(lateral, List.of("x"));
			host.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			host.setRuntimeTelemetryEnabled(true);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy,
					(NativeLmdbQuerySource) dataset);
			assertThat(compiled).isInstanceOf(NativeGroupStep.class);
			assertThat(((NativeGroupStep) compiled).nativePhysicalPlan()).contains("Lateral(", "TupleFunctionPlan");
			QueryBindingSet original = new QueryBindingSet();
			original.addBinding("x", caller);
			long rawBefore = host.getLongMetricActual("nativeInvocationsActual");
			resetAttachedGroupMetrics(host);
			NativeOptionalObservation plain = observeNativeOptional("raw grouped LATERAL plain", compiled, host,
					original);
			assertThat(plain.rows()).isEmpty();
			// Raw -1 is unavailable; the guard, explicit fallback and absent plan also establish this refusal.
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("raw-grouped-lateral plain rawBefore=%d rawAfter=%d normalizedDelta=%d%n", rawBefore,
						host.getLongMetricActual("nativeInvocationsActual"), plain.invocations());
			}
			SoftAssertions softly = new SoftAssertions();
			// This direct compiler call has no Group invocation edge; its actual-root counterpart is qualified above.
			assertDirectGroupInputFallback(softly, host, compiled, original, plain, "raw grouped LATERAL plain");
			observed.clear();
			BindingSet withheld = BindingFrameBindings.without(original, Set.of("x"), context);
			long withheldBefore = resetAttachedGroupMetrics(host);
			try (var rows = compiled.evaluate(withheld)) {
				assertThat(mappings(rows))
						.containsExactly(row("x", local, "count", VF.createLiteral("1", XSD.INTEGER)));
			}
			assertThat(observed).containsExactly(caller);
			softly.assertThat(Math.max(0L, host.getLongMetricActual("nativeInvocationsActual")) - withheldBefore)
					.as("the unchanged empty logical seed executes natively")
					.isPositive();
			softly.assertThat(host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.doesNotContain("genericFallback");
			softly.assertThat(host.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN)).isNotBlank();
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	@Test
	void groupedLateralInputTransitionCapturesPlainAndWithheldEntries() {
		String uri = "urn:native-tuple-input:grouped";
		Value caller = literal("caller");
		Value local = literal("local");
		List<Value> observed = new ArrayList<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add(args[0]);
				return new SingletonIteration<>(List.of(local));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("x"));
			call.addResultVar(Var.of("x"));
			Lateral lateral = new Lateral(new SingletonSet(), call, Set.of("x"));
			Group host = new Group(lateral, List.of("x"));
			host.addGroupElement(new GroupElem("count", new Count(Var.of("x"), false)));
			host.setRuntimeTelemetryEnabled(true);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryBindingSet original = new QueryBindingSet();
			original.addBinding("x", caller);
			BindingSet withheld = BindingFrameBindings.without(original, Set.of("x"), context);
			QueryBindingSet presentNull = new QueryBindingSet();
			presentNull.setBinding("x", null);
			record Case(String name, BindingSet input, List<Map<String, Value>> expected) {
			}
			List<Case> cases = List.of(new Case("plain", original, List.of()),
					new Case("withheld", withheld,
							List.of(row("x", local, "count", VF.createLiteral("1", XSD.INTEGER)))),
					new Case("present-null", presentNull, List.of()));
			SoftAssertions softly = new SoftAssertions();
			QueryEvaluationStep compiled = compileGroupInputDiagnostic(host, context, strategy,
					(NativeLmdbQuerySource) dataset, List.of(original, withheld, presentNull), "lateral", softly);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			record Observation(Case test, GroupEntryFacts before, GroupEntryFacts afterGeneric,
					GroupEntryFacts afterSelected, List<Map<String, Value>> genericRows, List<Value> genericArgs,
					NativeOptionalObservation selected, List<Value> selectedArgs) {
			}
			List<Observation> observations = new ArrayList<>();
			for (Case test : cases) {
				GroupEntryFacts before = groupEntryFacts(test.input(), host, compiled);
				observed.clear();
				List<Map<String, Value>> genericRows;
				try (var rows = generic.evaluate(test.input())) {
					genericRows = mappings(rows);
				}
				List<Value> genericArgs = new ArrayList<>(observed);
				GroupEntryFacts afterGeneric = groupEntryFacts(test.input(), host, compiled);
				observed.clear();
				String pathBefore = host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
				resetAttachedGroupMetrics(host);
				NativeOptionalObservation selected = compiled == null ? null
						: observeNativeOptional("group-lateral-" + test.name(), compiled, host, test.input());
				List<Value> selectedArgs = new ArrayList<>(observed);
				GroupEntryFacts afterSelected = groupEntryFacts(test.input(), host, compiled);
				if (SCOPE_DIAGNOSTICS) {
					System.out.printf("group-lateral input=%s generic=%s genericArgs=%s selected=%s selectedArgs=%s "
							+ "pathBefore=%s callerBefore=%s callerAfterGeneric=%s callerAfterSelected=%s%n",
							test.name(),
							genericRows, genericArgs, selected, selectedArgs, pathBefore, before, afterGeneric,
							afterSelected);
				}
				observations.add(new Observation(test, before, afterGeneric, afterSelected, genericRows, genericArgs,
						selected, selectedArgs));
			}
			softly.assertThat(compiled)
					.as("the grouped LATERAL has a native Group step")
					.isInstanceOf(NativeGroupStep.class);
			if (compiled instanceof NativeGroupStep nativeGroup) {
				softly.assertThat(nativeGroup.nativePhysicalPlan()).contains("Lateral(", "TupleFunctionPlan");
			}
			for (Observation observation : observations) {
				String label = observation.test().name();
				softly.assertThat(observation.genericRows())
						.as("generic LATERAL bag %s", label)
						.containsExactlyElementsOf(observation.test().expected());
				softly.assertThat(observation.afterGeneric())
						.as("generic caller unchanged %s", label)
						.isEqualTo(observation.before());
				softly.assertThat(observation.afterSelected())
						.as("selected caller unchanged %s", label)
						.isEqualTo(observation.before());
				if (observation.selected() != null) {
					softly.assertThat(observation.selected().rows())
							.as("selected LATERAL bag %s", label)
							.containsExactlyElementsOf(observation.test().expected());
					if (label.equals("plain")) {
						assertDirectGroupInputFallback(softly, host, compiled, observation.test().input(),
								observation.selected(), "raw plain LATERAL");
					}
				}
				if (label.equals("withheld")) {
					softly.assertThat(observation.genericArgs())
							.as("generic withheld tuple argument")
							.containsExactly(caller);
					softly.assertThat(observation.selectedArgs())
							.as("selected withheld tuple argument")
							.containsExactly(caller);
					if (observation.selected() != null) {
						softly.assertThat(observation.selected().invocations())
								.as("legacy empty logical seed is native")
								.isPositive();
						softly.assertThat(observation.selected().fallback()).isNull();
						softly.assertThat(observation.selected().execution()).doesNotContain("genericFallback");
						softly.assertThat(observation.selected().runtimePlan()).isNotBlank();
					}
				} else if (label.equals("present-null")) {
					softly.assertThat(observation.test().input().hasBinding("x"))
							.as("present null retains its name")
							.isTrue();
					softly.assertThat(observation.test().input().getValue("x"))
							.as("present null has no RDF value")
							.isNull();
					if (observation.selected() != null) {
						softly.assertThat(observation.selected().fallback())
								.as("present-null Group guard")
								.isEqualTo("groupInput");
						softly.assertThat(observation.selected().invocations())
								.as("present null is not seeded")
								.isZero();
					}
				}
			}
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	@Test
	void genericLateralDescriptorRetainsExternalOwnerInputs() {
		assertLateralDescriptorOwnerInputs(false);
	}

	@Test
	void genericLateralDescriptorRemapsCopiedInternalOwnerInputs() {
		assertLateralDescriptorOwnerInputs(true);
	}

	private void assertLateralDescriptorOwnerInputs(boolean copyOwner) {
		String uri = "urn:group-bridge:descriptor-owner:" + copyOwner;
		IRI caller = VF.createIRI("urn:group-bridge:descriptor-caller");
		IRI sibling = VF.createIRI("urn:group-bridge:descriptor-sibling");
		IRI local = VF.createIRI("urn:group-bridge:descriptor-local");
		Value hit = literal("hit");
		List<List<Value>> observed = new ArrayList<>();
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				observed.add(new ArrayList<>(Arrays.asList(args)));
				return new SingletonIteration<>(List.of(hit));
			}
		};
		TupleFunctionRegistry.getInstance().add(function);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			LmdbNativeEvaluationStrategy strategy = groupEmissionStrategy(dataset).genericOnlyView();
			Extension visibility = new Extension(new SingletonSet());
			visibility.addElement(new ExtensionElem(new Bound(Var.of("caller")), "callerSeen"));
			visibility.addElement(new ExtensionElem(new Bound(Var.of("sibling")), "siblingSeen"));
			Join left = new Join(values("local", local), visibility);
			TupleFunctionCall call = new TupleFunctionCall();
			call.setURI(uri);
			call.addArg(Var.of("caller"));
			call.addArg(Var.of("sibling"));
			call.addResultVar(Var.of("hit"));
			Group group = new Group(call, List.of("hit"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("hit"), false)));
			Lateral lateral = new Lateral(left, group, Set.of("caller", "sibling", "local"));
			Join owner = new Join(values("sibling", sibling), lateral);
			QueryRoot root = new QueryRoot(owner);
			QueryBindingSet input = new QueryBindingSet();
			input.addBinding("caller", caller);

			List<Map<String, Value>> outerRows;
			try (var rows = strategy.precompile(root, context).evaluate(input)) {
				outerRows = mappings(rows);
			}
			List<List<Value>> outerArguments = List.copyOf(observed);
			observed.clear();

			BindingSet siblingRow;
			try (var rows = strategy.precompile(owner.getLeftArg(), context).evaluate(input)) {
				assertThat(rows.hasNext()).as("the owner produces its sibling row").isTrue();
				siblingRow = new QueryBindingSet(rows.next());
				assertThat(rows.hasNext()).isFalse();
			}
			BindingSet framed = BindingFrameBindings.push(BindingFrameBindings.scopeFor(owner), input, siblingRow,
					context);
			List<Map<String, Value>> attachedRows;
			try (var rows = strategy.precompile(lateral, context).evaluate(framed)) {
				attachedRows = mappings(rows);
			}
			List<List<Value>> attachedArguments = List.copyOf(observed);
			observed.clear();

			TupleExpr selected = copyOwner ? owner : lateral;
			GenericSubplanDescriptor descriptor = GenericSubplanDescriptor.create(selected, strategy);
			TupleExpr pinned = descriptor.pinnedExpr();
			Lateral pinnedLateral = copyOwner ? (Lateral) ((Join) pinned).getRightArg() : (Lateral) pinned;
			BindingSet pinnedOwnerFrame = framed;
			if (copyOwner) {
				Join pinnedOwner = (Join) pinned;
				BindingSet pinnedSiblingRow;
				try (var rows = strategy.precompile(pinnedOwner.getLeftArg(), context).evaluate(input)) {
					assertThat(rows.hasNext()).as("the copied owner produces its sibling row").isTrue();
					pinnedSiblingRow = new QueryBindingSet(rows.next());
					assertThat(rows.hasNext()).isFalse();
				}
				pinnedOwnerFrame = BindingFrameBindings.push(BindingFrameBindings.scopeFor(pinnedOwner), input,
						pinnedSiblingRow, context);
			}
			QueryEvaluationStep cloneStep = descriptor.genericPrecompile(strategy, context);
			DescriptorOwnerObservation clone = observeDescriptorOwner(cloneStep, copyOwner ? input : framed,
					observed);
			DescriptorOwnerObservation repeated = observeDescriptorOwner(cloneStep, copyOwner ? input : framed,
					observed);

			DescriptorOwnerObservation detachedObservation = null;
			if (!copyOwner) {
				GenericSubplanDescriptor detached = GenericSubplanDescriptor.create(lateral.clone(), strategy);
				detachedObservation = observeDescriptorOwner(detached.genericPrecompile(strategy, context), framed,
						observed);
			}

			Map<String, Value> attachedExpected = row("caller", caller, "local", local,
					"callerSeen", VF.createLiteral(true), "siblingSeen", VF.createLiteral(false),
					"hit", hit, "count", groupInteger(1));
			Map<String, Value> outerExpected = new TreeMap<>(attachedExpected);
			outerExpected.put("sibling", sibling);
			Map<String, Value> cloneExpected = copyOwner ? outerExpected : attachedExpected;
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(framed.getValue("caller")).as("semantic caller stays visible").isEqualTo(caller);
			softly.assertThat(framed.hasBinding("sibling")).as("the sibling is an owner probe").isFalse();
			softly.assertThat(BindingFrameBindings.parameterInputs(lateral, lateral.getRightInputBindingNames(), true)
					.borrowedValue(framed, "sibling")).as("the attached recipient's owner grant").isEqualTo(sibling);
			softly.assertThat(siblingRow.getValue("sibling")).as("the actual owner output").isEqualTo(sibling);
			softly.assertThat(outerRows).as("independent generic outer bag").containsExactly(outerExpected);
			softly.assertThat(attachedRows).as("independent attached LATERAL bag").containsExactly(attachedExpected);
			softly.assertThat(outerArguments).as("generic outer callback").containsExactly(List.of(caller, sibling));
			softly.assertThat(attachedArguments)
					.as("generic attached callback")
					.containsExactly(List.of(caller, sibling));
			softly.assertThat(pinned).as("descriptor owns a distinct snapshot").isNotSameAs(selected);
			softly.assertThat(BindingFrameBindings
					.parameterInputs(pinnedLateral, pinnedLateral.getRightInputBindingNames(), true)
					.borrowedValue(pinnedOwnerFrame, "sibling"))
					.as("the copied recipient's exact owner grant")
					.isEqualTo(sibling);
			if (copyOwner) {
				softly.assertThat(BindingFrameBindings.scopeFor((Join) pinned))
						.as("the copied owner has its own scope")
						.isNotEqualTo(BindingFrameBindings.scopeFor(owner));
				softly.assertThat(BindingFrameBindings
						.parameterInputs(pinnedLateral, pinnedLateral.getRightInputBindingNames(), true)
						.borrowedValue(framed, "sibling"))
						.as("the copied owner cannot borrow the original frame")
						.isNull();
			} else {
				softly.assertThat(detachedObservation.failure())
						.as("the detached clone reports the unbound tuple argument")
						.isInstanceOf(ValueExprEvaluationException.class);
				softly.assertThat(detachedObservation.rows()).as("an unmarked detached clone emits no rows").isEmpty();
				softly.assertThat(detachedObservation.arguments())
						.as("the detached clone does not call the tuple function")
						.isEmpty();
			}
			softly.assertThat(clone.failure()).as("pinned descriptor evaluation error").isNull();
			softly.assertThat(clone.rows()).as("pinned descriptor bag").containsExactly(cloneExpected);
			softly.assertThat(clone.arguments())
					.as("pinned descriptor callback")
					.containsExactly(List.of(caller, sibling));
			softly.assertThat(repeated.failure()).as("reused pinned descriptor evaluation error").isNull();
			softly.assertThat(repeated.rows()).as("reused pinned descriptor bag").containsExactly(cloneExpected);
			softly.assertThat(repeated.arguments())
					.as("reused pinned descriptor callback")
					.containsExactly(List.of(caller, sibling));
			softly.assertThat(input.getBindingNames()).as("the caller remains unchanged").containsExactly("caller");
			softly.assertAll();
		} finally {
			TupleFunctionRegistry.getInstance().remove(function);
		}
	}

	private record DescriptorOwnerObservation(List<Map<String, Value>> rows, RuntimeException failure,
			List<List<Value>> arguments) {
	}

	private static DescriptorOwnerObservation observeDescriptorOwner(QueryEvaluationStep step, BindingSet input,
			List<List<Value>> observed) {
		List<Map<String, Value>> results = new ArrayList<>();
		RuntimeException failure = null;
		try (var rows = step.evaluate(input)) {
			while (rows.hasNext()) {
				BindingSet bindings = rows.next();
				Map<String, Value> mapping = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					mapping.put(name, bindings.getValue(name));
				}
				results.add(mapping);
			}
		} catch (RuntimeException problem) {
			failure = problem;
		}
		List<List<Value>> arguments = List.copyOf(observed);
		observed.clear();
		return new DescriptorOwnerObservation(List.copyOf(results), failure, arguments);
	}

