		final AtomicReference<List<String>> runtimeAtCallbacks = new AtomicReference<>();
		final AtomicReference<AtomicInteger> tupleResultCloses = new AtomicReference<>();
		final AtomicReference<OwnerInFlightResult> inFlightResult = new AtomicReference<>();
		final TupleFunction function;
		SailDataset dataset;
		NativeLmdbQuerySource source;
		QueryEvaluationContext context;
		LmdbNativeEvaluationStrategy strategy;
		Lateral lateral;
		Join owner;
		QueryRoot root;
		QueryEvaluationStep ownerProducer;
		QueryEvaluationStep genericOuter;
		QueryEvaluationStep genericAttached;
		NativeRowsStep selected;
