				Extension visibility = new Extension(new SingletonSet());
				visibility.addElement(new ExtensionElem(new Bound(Var.of("caller")), "callerSeen"));
				visibility.addElement(new ExtensionElem(new Bound(Var.of("sibling")), "siblingSeen"));
