				lateral.setRuntimeTelemetryEnabled(true);
				lateral.setExecutionSummaryEnabled(true);
				owner = new Join(values("sibling", siblingA, siblingB), lateral);
				root = new QueryRoot(owner);
				ownerProducer = strategy.genericOnlyView().precompile(owner.getLeftArg(), context);
