	@Test
	void nativeSupportedPathConstantsKeepExactBagsAndRoutes() {
		verifyPathConstantCases(List.of(
				new PathConstantCase(false, false, false),
				new PathConstantCase(false, true, false),
				new PathConstantCase(false, true, true),
				new PathConstantCase(true, false, false),
				new PathConstantCase(true, true, false),
				new PathConstantCase(true, true, true)), true);
	}

	private record PathConstantCase(boolean anonymousPredicate, boolean anonymousContext, boolean general) {
	}

	private void verifyPathConstantCases(List<PathConstantCase> cases, boolean nativeExecution) {
		IRI subject = VF.createIRI("urn:path-constant:subject");
		IRI predicate = VF.createIRI("urn:path-constant:predicate");
		IRI object = VF.createIRI("urn:path-constant:object");
		IRI graph = VF.createIRI("urn:path-constant:graph");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object, graph);
		}
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			for (PathConstantCase test : cases) {
				Var contextVar = Var.of("queryContext", graph, test.anonymousContext(), true);
				StatementPattern edge = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
						Var.of("s"), Var.of("queryPredicate", predicate, test.anonymousPredicate(), true),
						Var.of("o"), contextVar.clone());
				TupleExpr body = test.general() ? new Filter(edge, new ValueConstant(VF.createLiteral(true))) : edge;
				ArbitraryLengthPath path = new ArbitraryLengthPath(StatementPattern.Scope.NAMED_CONTEXTS,
						Var.of("s"), body, Var.of("o"), contextVar, 1);
				path.setRuntimeTelemetryEnabled(true);
				QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
				List<Map<String, Value>> expected = List.of(row("s", subject, "o", object));
				long pathBefore = PathPlan.ENGAGED.get();
				long generalBefore = GeneralPathPlan.ENGAGED.get();
				long invocationBefore = Math.max(0L, path.getLongMetricActual("nativeInvocationsActual"));
				QueryEvaluationStep compiled = nativeExecution ? strategy.precompile(path, context)
						: strategy.genericOnlyView().precompile(path, context);
				try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
					softly.assertThat(mappings(rows)).as("exact bag " + test).containsExactlyElementsOf(expected);
				}
				if (nativeExecution) {
					long routeDelta = test.general() ? GeneralPathPlan.ENGAGED.get() - generalBefore
							: PathPlan.ENGAGED.get() - pathBefore;
					softly.assertThat(routeDelta).as("actual native path route " + test).isPositive();
					softly.assertThat(path.getLongMetricActual("nativeInvocationsActual"))
							.as("actual native invocation " + test)
							.isGreaterThan(invocationBefore);
				}
			}
		}
		softly.assertAll();
	}

	@Test
	void singletonOptionalExistsIsTrueWhenNativeIsDisabledOrSourceIsEmpty() {
		String property = "rdf4j.lmdb.nativeQueryEngine.enabled";
		String previous = System.getProperty(property);
		System.setProperty(property, "true");
		try {
			NativeLmdbQuerySource emptySource = mock(NativeLmdbQuerySource.class);
			doReturn(true).when(emptySource).hasCanonicalIds();
			doReturn(false).when(emptySource).hasStatementsInSource();
			LmdbNativeEvaluationStrategy nativeStrategy = new LmdbNativeEvaluationStrategy(
					new NativeWorkerTripleSource(emptySource, VF), null, null, 0L, new EvaluationStatistics(), false);
			assertThat(nativeStrategy.nativeSource()).isSameAs(emptySource);
			for (boolean enabled : List.of(false, true)) {
				AtomicInteger traversals = new AtomicInteger();
				Iterable<BindingSet> oneShotEmpty = () -> {
					if (traversals.incrementAndGet() > 1) {
						throw new IllegalStateException("singleton OPTIONAL VALUES may only be traversed once");
					}
					return List.<BindingSet>of().iterator();
				};
				BindingSetAssignment values = new BindingSetAssignment();
				values.setBindingNames(Set.of("x"));
				values.setBindingSets(oneShotEmpty);
				Exists expression = new Exists(new LeftJoin(new SingletonSet(), values));
				LmdbNativeEvaluationStrategy evaluator = enabled ? nativeStrategy : nativeStrategy.genericOnlyView();
				var step = evaluator.precompile(expression, new QueryEvaluationContext.Minimal((Dataset) null));
				assertThat(step.evaluate(EmptyBindingSet.getInstance())).as("enabled=%s", enabled)
						.isEqualTo(VF.createLiteral(true));
				assertThat(step.evaluate(EmptyBindingSet.getInstance())).as("repeat enabled=%s", enabled)
						.isEqualTo(VF.createLiteral(true));
				assertThat(traversals.get()).as("one-shot capture enabled=%s", enabled).isLessThanOrEqualTo(1);
			}
			verify(emptySource, atLeastOnce()).hasStatementsInSource();
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

