	@Test
	void nativeSupportedNilAndOrdinaryPathsKeepExactBagsAndRoutes() {
		verifyNilPathCases(List.of(
				new NilPathCase("ordinary", false), new NilPathCase("ordinary", true),
				new NilPathCase("named", false), new NilPathCase("named", true),
				new NilPathCase("rdf4j-constant", false), new NilPathCase("sesame-constant", false)), true);
	}

	private record NilPathCase(String kind, boolean general) {
	}

	private void verifyNilPathCases(List<NilPathCase> cases, boolean nativeExecution) {
		IRI subject = VF.createIRI("urn:path-nil:subject");
		IRI predicate = VF.createIRI("urn:path-nil:predicate");
		IRI object = VF.createIRI("urn:path-nil:object");
		IRI namedGraph = VF.createIRI("urn:path-nil:named");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
			connection.add(subject, predicate, object, namedGraph);
		}
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			for (NilPathCase test : cases) {
				String kind = test.kind();
				IRI graph = switch (kind) {
				case "named" -> namedGraph;
				case "rdf4j-valued", "rdf4j-constant" -> RDF4J.NIL;
				case "sesame-valued", "sesame-constant" -> SESAME.NIL;
				default -> null;
				};
				boolean constant = kind.endsWith("constant");
				Var contextVar = graph == null ? null
						: Var.of(constant ? "queryConstant" : "g", graph, constant, constant);
				StatementPattern.Scope scope = kind.equals("named") ? StatementPattern.Scope.NAMED_CONTEXTS
						: StatementPattern.Scope.DEFAULT_CONTEXTS;
				StatementPattern edge = new StatementPattern(scope, Var.of("s"),
						Var.of("p", predicate, true, true), Var.of("o"),
						contextVar == null ? null : contextVar.clone());
				TupleExpr body = test.general() ? new Filter(edge, new ValueConstant(VF.createLiteral(true))) : edge;
				ArbitraryLengthPath path = new ArbitraryLengthPath(scope, Var.of("s"), body, Var.of("o"),
						contextVar, 1L);
				path.setRuntimeTelemetryEnabled(true);
				List<Map<String, Value>> expected = graph != null && !constant
						? List.of(row("s", subject, "o", object, "g", graph))
						: List.of(row("s", subject, "o", object));
				QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
				long optimizedBefore = PathPlan.ENGAGED.get();
				long generalBefore = GeneralPathPlan.ENGAGED.get();
				long invocationBefore = Math.max(0L, path.getLongMetricActual("nativeInvocationsActual"));
				QueryEvaluationStep compiled = nativeExecution ? strategy.precompile(path, context)
						: strategy.genericOnlyView().precompile(path, context);
				try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
					softly.assertThat(mappings(rows)).as("exact bag " + test).containsExactlyElementsOf(expected);
				}
				if (nativeExecution) {
					boolean optimized = !test.general() && (kind.equals("ordinary") || constant);
					long routeDelta = optimized ? PathPlan.ENGAGED.get() - optimizedBefore
							: GeneralPathPlan.ENGAGED.get() - generalBefore;
					softly.assertThat(routeDelta).as("actual native path route " + test).isPositive();
					softly.assertThat(path.getLongMetricActual("nativeInvocationsActual"))
							.as("actual native invocation " + test)
							.isGreaterThan(invocationBefore);
				}
			}
		}
		softly.assertAll();
	}

	@Test
	void valuedAnonymousStatementOccurrencesPreserveBindingsAndRepeatedEquality() {
		IRI subject = VF.createIRI("urn:occurrence:subject");
		IRI other = VF.createIRI("urn:occurrence:other");
		IRI predicate = VF.createIRI("urn:occurrence:predicate");
		Value seed = literal("seed");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, subject);
			connection.add(subject, predicate, other);
		}
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			for (boolean anonymous : List.of(false, true)) {
				for (String shape : List.of("single", "repeated", "conflicting-fixed")) {
					Var object = switch (shape) {
					case "single" -> Var.of("object", other, true, true);
					case "repeated" -> Var.of("x");
					default -> Var.of("x", other, anonymous, false);
					};
					StatementPattern pattern = new StatementPattern(Var.of("x", subject, anonymous, false),
							Var.of("predicate", predicate, true, true), object);
					Projection host = new Projection(new Join(values("seed", seed), pattern),
							new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("seed")), false);
					host.setRuntimeTelemetryEnabled(true);
					QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
					QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy,
							source);
					List<Map<String, Value>> expected = shape.equals("conflicting-fixed") ? List.of()
							: List.of(row("x", subject, "seed", seed));
					String label = "anonymous=" + anonymous + ", shape=" + shape;
					try (var rows = generic.evaluate(EmptyBindingSet.getInstance())) {
						softly.assertThat(mappings(rows)).as("generic " + label).containsExactlyElementsOf(expected);
					}
					if (compiled instanceof NativeRowsStep nativeStep) {
						String fallback = nativeStep.semanticEntryFallbackReason(EmptyBindingSet.getInstance());
						long before = host.getLongMetricActual("nativeInvocationsActual");
						long islandsBefore = LmdbNativeAggregateCompiler.ISLAND_OPENS.get();
						String plan = nativeStep.nativePhysicalPlan();
						List<Map<String, Value>> actual;
						try (var rows = nativeStep.evaluate(EmptyBindingSet.getInstance())) {
							actual = mappings(rows);
						}
						if (fallback == null && plan.contains("GenericEvalPlan(")) {
							softly.assertThat(LmdbNativeAggregateCompiler.ISLAND_OPENS.get())
									.as("actual generic-island fallback " + label)
									.isGreaterThan(islandsBefore);
							if (SCOPE_DIAGNOSTICS) {
								System.out.printf("occurrence %s route=generic-island plan=%s%n", label, plan);
							}
						} else if (fallback == null) {
							softly.assertThat(plan).as("native plan " + label).contains("Pattern(");
							softly.assertThat(host.getLongMetricActual("nativeInvocationsActual"))
									.as("actual native invocation " + label)
									.isPositive()
									.isGreaterThan(before);
							if (SCOPE_DIAGNOSTICS) {
								System.out.printf("occurrence %s route=native invocations=%d plan=%s%n", label,
										host.getLongMetricActual("nativeInvocationsActual"), plan);
							}
						} else {
							softly.assertThat(fallback).as("reported native entry fallback " + label).isNotBlank();
							if (SCOPE_DIAGNOSTICS) {
								System.out.printf("occurrence %s route=entry-fallback reason=%s%n", label, fallback);
							}
						}
						softly.assertThat(actual)
								.as("native or entry fallback " + label)
								.containsExactlyElementsOf(expected);
					} else if (compiled == null) {
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf("occurrence %s route=compiler-declined generic-fallback%n", label);
						}
						QueryEvaluationStep fallback = strategy.genericOnlyView().precompile(host.clone(), context);
						try (var rows = fallback.evaluate(EmptyBindingSet.getInstance())) {
							softly.assertThat(mappings(rows))
									.as("compiler-declined fallback " + label)
									.containsExactlyElementsOf(expected);
						}
					} else if (compiled instanceof LmdbNativePhysicalPlan physical) {
						long before = host.getLongMetricActual("nativeInvocationsActual");
						List<Map<String, Value>> actual;
						try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
							actual = mappings(rows);
						}
						softly.assertThat(host.getLongMetricActual("nativeInvocationsActual"))
								.as("actual native wrapper invocation " + label)
								.isPositive()
								.isGreaterThan(before);
						softly.assertThat(actual).as("native wrapper " + label).containsExactlyElementsOf(expected);
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf("occurrence %s route=native-wrapper plan=%s%n", label,
									physical.nativePhysicalPlan());
						}
					} else {
						softly.assertThat(compiled)
								.as("recognized native plan for " + label)
								.isInstanceOf(NativeRowsStep.class);
					}
				}
			}
		}
		softly.assertAll();
	}

	@Test
	void nestedSelectInheritedGraphsKeepTheirSharedDomainOnGenericAndNativeRoutes() {
		IRI firstSubject = VF.createIRI("urn:nested-graph:first");
		IRI sameSubject = VF.createIRI("urn:nested-graph:same");
		IRI otherSubject = VF.createIRI("urn:nested-graph:other");
		IRI firstPredicate = VF.createIRI("urn:nested-graph:first-predicate");
		IRI secondPredicate = VF.createIRI("urn:nested-graph:second-predicate");
		IRI object = VF.createIRI("urn:nested-graph:object");
		IRI graph = VF.createIRI("urn:nested-graph:graph");
		IRI otherGraph = VF.createIRI("urn:nested-graph:other-graph");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(firstSubject, firstPredicate, object, graph);
			connection.add(sameSubject, secondPredicate, object, graph);
			connection.add(otherSubject, secondPredicate, object, otherGraph);
		}
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(VF, dataset), null, null, 0L, new EvaluationStatistics(), false);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryBindingSet matching = new QueryBindingSet();
			matching.addBinding("g", graph);
			QueryBindingSet conflicting = new QueryBindingSet();
			conflicting.addBinding("g", otherGraph);
			for (int scenario = 0; scenario < 5; scenario++) {
				Projection host = nestedGraphHost(firstPredicate, secondPredicate, object, graph, otherGraph, scenario);
				for (boolean nativeMode : List.of(false, true)) {
					Projection copy = host.clone();
					Join join = (Join) copy.getArg();
					StatementPattern first = (StatementPattern) join.getLeftArg();
					StatementPattern second = (StatementPattern) ((Projection) join.getRightArg()).getArg();
					QueryRoot hostRoot = new QueryRoot(copy);
					QueryEvaluationStep step = nativeMode ? strategy.precompile(hostRoot, context)
							: strategy.genericOnlyView().precompile(hostRoot, context);
					List<BindingSet> entries = List.of(EmptyBindingSet.getInstance(), matching, conflicting, matching);
					for (int call = 0; call < entries.size(); call++) {
						// The inconsistent fixed-lineage no-caller case is preserved in the GRAPH diagnostic packet.
						if (scenario == 0 && call == 0) {
							continue;
						}
						List<Map<String, Value>> expected = scenario == 0 || call == 2 || scenario == 3 && call != 0
								? List.of()
								: List.of(row("s1", firstSubject, "s2", scenario >= 3 ? otherSubject : sameSubject));
						try (CloseableIteration<BindingSet> rows = step.evaluate(entries.get(call))) {
							softly.assertThat(mappings(rows))
									.as("scenario=%s native=%s call=%s", scenario, nativeMode,
											call)
									.containsExactlyElementsOf(expected);
						}
					}
					if (SCOPE_DIAGNOSTICS) {
						System.out.printf("nested-graph scenario=%d native=%s firstInvocations=%d firstPath=%s "
								+ "secondInvocations=%d secondPath=%s%n", scenario, nativeMode,
								first.getLongMetricActual("nativeInvocationsActual"),
								first.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH),
								second.getLongMetricActual("nativeInvocationsActual"),
								second.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH));
					}
				}
			}
		}
		softly.assertAll();
	}

	private static Projection nestedGraphHost(IRI firstPredicate, IRI secondPredicate, IRI object, IRI graph,
			IRI otherGraph, int scenario) {
		Var firstContext = Var.of("g", graph);
		firstContext.setGraphContextDepth(1);
		Var secondContext = switch (scenario) {
		case 0, 3 -> Var.of("g", otherGraph);
		case 1 -> Var.of("g", graph);
		case 4 -> Var.of("localGraph", otherGraph, true, true);
		default -> Var.of("g");
		};
		secondContext.setGraphContextDepth(scenario >= 3 ? 0 : 2);
		StatementPattern first = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s1"),
				Var.of("p1", firstPredicate, true, true), Var.of("o1", object, true, true), firstContext);
		StatementPattern second = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s2"),
				Var.of("p2", secondPredicate, true, true), Var.of("o2", object, true, true), secondContext);
		first.setRuntimeTelemetryEnabled(true);
		second.setRuntimeTelemetryEnabled(true);
		Projection inner = new Projection(second, new ProjectionElemList(new ProjectionElem("s2")), true);
		Var innerCaller = Var.of("g");
		innerCaller.setGraphContextDepth(1);
		inner.setProjectionContext(innerCaller);
		Projection outer = new Projection(new Join(first, inner),
				new ProjectionElemList(new ProjectionElem("s1"), new ProjectionElem("s2")), true);
		outer.setProjectionContext(Var.of("g"));
		return outer;
	}

