	@Test
	void preparedAncestorFilterUsesExecutedNativeMultiJoin() {
		loadAncestorFilterPlacementData();
		Filter filter = ancestorPlacementFilter();
		Join tail = new Join(filter, ancestorPlacementPattern("c", "r", "a"));
		Join owner = new Join(ancestorPlacementPattern("a", "p", "b"), tail);
		owner.setRuntimeTelemetryEnabled(true);

		// The FILTER reads c locally and a from this exact ancestor, not from the later r pattern.
		assertThat(QueryEvaluationUtility.requiresBindingFrameReplayPartition(owner)).isTrue();
		PreparedFilterScope scope = QueryEvaluationUtility.preparedFilterScope(owner);
		assertThat(scope).isNotNull();
		assertThat(scope.isRegion(owner)).isTrue();
		assertThat(scope.requiresScopedInput(owner)).isTrue();
		assertThat(scope.conditionReads(filter)).containsExactlyInAnyOrder("a", "c");
		assertThat(scope.conditionInputsAvailable(filter, Set.of("c"),
				(candidate, name) -> candidate == owner && name.equals("a"))).isTrue();
		assertThat(scope.conditionInputsAvailable(filter, Set.of("c"),
				(candidate, name) -> candidate == tail && name.equals("a"))).isFalse();

		// From the ten statements loaded below: A-B-C, D-B-C, D-B-A, and A-E-C survive.
		// A-B-A is rejected by a != c; no other p/q/r combination closes the cycle.
		List<Map<String, Value>> expected = List.of(
				ancestorPlacementRow("a", "b", "c", true),
				ancestorPlacementRow("d", "b", "c", true),
				ancestorPlacementRow("d", "b", "a", true),
				ancestorPlacementRow("a", "e", "c", true));
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = spy(new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false));
			doReturn("nestedLoop").when(strategy).forcedExecutionStrategyName();
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(owner.clone(), context);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(owner, context, strategy, source);
			assertThat(compiled).as("production compilation of the attached owner region")
					.isInstanceOf(NativeRowsStep.class);
			NativeRowsStep nativeStep = (NativeRowsStep) compiled;
			assertThat(nativeStep.nativePhysicalPlan()).as("the certified region stays one native join")
					.contains("NativeRows(arg=MultiJoin(", "filterDepths=", "Pattern(")
					.doesNotContain("GenericEvalPlan(", "LexicalFrame");
			assertThat(nativeStep.semanticEntryFallbackReason(EmptyBindingSet.getInstance())).isNull();
			try (var rows = generic.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(mappings(rows)).as("generic exact unprojected algebra bag")
						.containsExactlyInAnyOrderElementsOf(expected);
			}
			List<Map<String, Value>> actual;
			try (var rows = nativeStep.evaluate(EmptyBindingSet.getInstance())) {
				actual = mappings(rows);
			}
			assertThat(actual).as("native exact unprojected algebra bag")
					.containsExactlyInAnyOrderElementsOf(expected);
			assertThat(owner.getLongMetricActual("nativeInvocationsActual")).isPositive();
			assertThat(owner.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.contains("nestedLoop")
					.doesNotContain("genericFallback");
			assertThat(owner.getStringMetricActual("runtimePhysicalPlan"))
					.contains("actualOrder:", "Pattern(")
					.doesNotContain("<not opened", "GenericEvalPlan(", "LexicalFrame");
		}
	}

	@Test
	void laterSiblingCannotSupplyFilterInput() {
		loadAncestorFilterPlacementData();
		Join filtered = new Join(ancestorPlacementFilter(), ancestorPlacementPattern("c", "r", "a"));
		assertThat(QueryEvaluationUtility.preparedFilterScope(filtered)).isNull();
		// The q/r relation has six matches and binds a, but a is absent when the earlier FILTER runs.
		Join unfiltered = new Join(ancestorPlacementPattern("b", "q", "c"),
				ancestorPlacementPattern("c", "r", "a"));
		assertAncestorPlacementSolutions(unfiltered, List.of(
				ancestorPlacementRow("a", "b", "c", false), ancestorPlacementRow("d", "b", "c", false),
				ancestorPlacementRow("a", "b", "a", false), ancestorPlacementRow("d", "b", "a", false),
				ancestorPlacementRow("a", "e", "c", false), ancestorPlacementRow("d", "e", "c", false)));
		assertAncestorPlacementSolutions(filtered, List.of());
	}

	@Test
	void nullableAncestorCannotReceiveFilterInputFromLaterSibling() {
		loadAncestorFilterPlacementData();
		Join tail = new Join(ancestorPlacementFilter(), ancestorPlacementPattern("c", "r", "a"));
		Join owner = new Join(values("a", ancestorPlacementIri("a"), ancestorPlacementIri("a"), null,
				ancestorPlacementIri("d")), tail);
		assertThat(QueryEvaluationUtility.preparedFilterScope(owner)).isNull();
		// The two A inputs each contribute two rows, D contributes three, and UNDEF contributes none.
		assertAncestorPlacementSolutions(owner, List.of(
				ancestorPlacementRow("a", "b", "c", false), ancestorPlacementRow("a", "b", "c", false),
				ancestorPlacementRow("a", "e", "c", false), ancestorPlacementRow("a", "e", "c", false),
				ancestorPlacementRow("d", "b", "c", false), ancestorPlacementRow("d", "b", "a", false),
				ancestorPlacementRow("d", "e", "c", false)));
	}

	private void loadAncestorFilterPlacementData() {
		IRI a = ancestorPlacementIri("a");
		IRI b = ancestorPlacementIri("b");
		IRI c = ancestorPlacementIri("c");
		IRI d = ancestorPlacementIri("d");
		IRI e = ancestorPlacementIri("e");
		IRI p = ancestorPlacementIri("p");
		IRI q = ancestorPlacementIri("q");
		IRI r = ancestorPlacementIri("r");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(a, p, b);
			connection.add(d, p, b);
			connection.add(a, p, e);
			connection.add(b, q, c);
			connection.add(b, q, a);
			connection.add(e, q, c);
			connection.add(c, r, a);
			connection.add(c, r, d);
			connection.add(a, r, a);
			connection.add(a, r, d);
		}
	}

	private static Filter ancestorPlacementFilter() {
		return new Filter(ancestorPlacementPattern("b", "q", "c"),
				new Compare(new Var("a"), new Var("c"), Compare.CompareOp.NE));
	}

	private static StatementPattern ancestorPlacementPattern(String subject, String predicate, String object) {
		return new StatementPattern(new Var(subject), new Var("constant-" + predicate, ancestorPlacementIri(predicate)),
				new Var(object));
	}

	private static IRI ancestorPlacementIri(String name) {
		return VF.createIRI("urn:" + name);
	}

	private static Map<String, Value> ancestorPlacementRow(String a, String b, String c, boolean includesP) {
		// Named valued, nonconstant predicate Vars are algebra outputs, just as in the original raw fixture.
		Map<String, Value> result = row("a", ancestorPlacementIri(a), "b", ancestorPlacementIri(b),
				"c", ancestorPlacementIri(c), "constant-q", ancestorPlacementIri("q"),
				"constant-r", ancestorPlacementIri("r"));
		if (includesP) {
			result.put("constant-p", ancestorPlacementIri("p"));
		}
		return result;
	}

	private void assertAncestorPlacementSolutions(TupleExpr expression, List<Map<String, Value>> expected) {
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(expression.clone(), context);
			QueryEvaluationStep actual = strategy.precompile(expression, context);
			try (var rows = generic.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(mappings(rows)).as("generic exact boundary bag")
						.containsExactlyInAnyOrderElementsOf(expected);
			}
			try (var rows = actual.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(mappings(rows)).as("production exact boundary bag")
						.containsExactlyInAnyOrderElementsOf(expected);
			}
		}
	}

	@ParameterizedTest(name = "{0}: {1}")
	@MethodSource("scopeCases")
	void optionalOperandsKeepTheirOwnBindings(String strategy, String description, String query,
			List<Map<String, Value>> expected) {
		assertNativeSolutions(strategy, query, expected);
	}

	private static Stream<Arguments> scopeCases() {
		List<Arguments> cases = new ArrayList<>();
		for (String strategy : List.of("auto", "nestedLoop", "batch")) {
			cases.add(Arguments.of(strategy, "outer-only BIND input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(?x AS ?y) } }",
					List.of(row("x", literal("left")))));
			cases.add(Arguments.of(strategy, "outer-only COALESCE input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(COALESCE(?x, \"fallback\") AS ?y) } }",
					List.of(row("x", literal("left"), "y", literal("fallback")))));
			cases.add(Arguments.of(strategy, "outer-only BOUND input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(BOUND(?x) AS ?y) } }",
					List.of(row("x", literal("left"), "y", VF.createLiteral(false)))));
			cases.add(Arguments.of(strategy, "UNDEF and bound outer values",
					"SELECT * WHERE { VALUES ?x { \"left\" UNDEF } OPTIONAL { "
							+ "BIND(COALESCE(?x, \"fallback\") AS ?y) } }",
					List.of(row("x", literal("left"), "y", literal("fallback")),
							row("y", literal("fallback")))));
			cases.add(Arguments.of(strategy, "lifted condition and independent BIND",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
							+ "FILTER(BOUND(?x)) BIND(\"yes\" AS ?y) BIND(?x AS ?z) } }",
					List.of(row("x", literal("left"), "y", literal("yes")))));
			cases.add(Arguments.of(strategy, "nested OPTIONAL BIND input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { VALUES ?o { \"o\" } "
							+ "OPTIONAL { BIND(?x AS ?y) } } }",
					List.of(row("x", literal("left"), "o", literal("o")))));
			cases.add(Arguments.of(strategy, "nested group filter input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { VALUES ?o { \"o\" } "
							+ "{ FILTER(BOUND(?x)) } } }",
					List.of(row("x", literal("left")))));
			cases.add(Arguments.of(strategy, "MINUS BIND input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { VALUES ?o { \"left\" } "
							+ "MINUS { BIND(?x AS ?o) } } }",
					List.of(row("x", literal("left"), "o", literal("left")))));
			cases.add(Arguments.of(strategy, "MINUS filter input",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { VALUES ?o { \"o\" } "
							+ "MINUS { VALUES ?o { \"o\" } FILTER(BOUND(?x)) } } }",
					List.of(row("x", literal("left"), "o", literal("o")))));
			cases.add(Arguments.of(strategy, "independent UNION branches",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
							+ "{ BIND(?x AS ?y) } UNION { BIND(\"u\" AS ?y) } } }",
					List.of(row("x", literal("left")), row("x", literal("left"), "y", literal("u")))));
			cases.add(Arguments.of(strategy, "UNION filter scope",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
							+ "{ FILTER(BOUND(?x)) BIND(\"yes\" AS ?y) } UNION { BIND(\"other\" AS ?y) } } }",
					List.of(row("x", literal("left"), "y", literal("other")))));
			cases.add(Arguments.of(strategy, "BIND target collision",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { BIND(\"right\" AS ?x) } }",
					List.of(row("x", literal("left")))));
			cases.add(Arguments.of(strategy, "failed BIND target",
					"SELECT * WHERE { VALUES ?x { \"left\" } OPTIONAL { "
							+ "VALUES ?o { \"abc\" } BIND(?o + 1 AS ?x) } }",
					List.of(row("x", literal("left"), "o", literal("abc")))));
			cases.add(Arguments.of(strategy, "OPTIONAL condition sees both operands",
					"SELECT * WHERE { VALUES ?x { \"left\" \"right\" } OPTIONAL { "
							+ "VALUES ?o { \"left\" } FILTER(?x = ?o) } }",
					List.of(row("x", literal("left"), "o", literal("left")), row("x", literal("right")))));
			cases.add(Arguments.of(strategy, "subquery OPTIONAL condition sees both operands",
					"SELECT * WHERE { VALUES ?x { \"left\" \"right\" } OPTIONAL { "
							+ "{ SELECT ?o WHERE { VALUES ?o { \"left\" } } } FILTER(?x = ?o) } }",
					List.of(row("x", literal("left"), "o", literal("left")), row("x", literal("right")))));
			cases.add(Arguments.of(strategy, "incompatible nested OPTIONAL match",
					"SELECT * WHERE { VALUES ?x { \"outer\" } OPTIONAL { VALUES ?o { \"a\" } "
							+ "OPTIONAL { VALUES ?x { \"inner\" } } } }",
					List.of(row("x", literal("outer")))));
			cases.add(Arguments.of(strategy, "duplicate outer mappings",
					"SELECT * WHERE { VALUES ?x { \"left\" \"left\" } OPTIONAL { BIND(?x AS ?y) } }",
					List.of(row("x", literal("left")), row("x", literal("left")))));
			cases.add(Arguments.of(strategy, "same RDF term is compatible",
					"SELECT * WHERE { VALUES ?x { \"text\"@en } OPTIONAL { "
							+ "VALUES (?x ?o) { (\"text\"@en \"match\") } } }",
					List.of(row("x", VF.createLiteral("text", "en"), "o", literal("match")))));
			cases.add(Arguments.of(strategy, "different RDF terms are incompatible",
					"SELECT * WHERE { VALUES ?x { \"text\"@en } OPTIONAL { "
							+ "VALUES (?x ?o) { (\"text\" \"match\") } } }",
					List.of(row("x", VF.createLiteral("text", "en")))));
		}
		return cases.stream();
	}

	@Test
	void lexicalFrameHidesOuterValueDuringRightEvaluation() throws IOException {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("x", 0, "o", 1, "z", 2), null);
		layout.freeze(List.of("x", "o", "z"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN);
		row.recomputeBoundMask();
		assertThat(row.bind(0, 11L)).isTrue();
		SlotPlan left = SlotPlan.values(new ValuesRow[] { new ValuesRow(new int[] { 1 }, new long[] { 22L }) });
		SlotPlan right = SlotPlan.filter(
				SlotPlan.values(new ValuesRow[] { new ValuesRow(new int[] { 2 }, new long[] { 33L }) }),
				input -> input.slots[0] != UNKNOWN, 1L);

		try (LexicalFrameLeftJoinCursor cursor = new LexicalFrameLeftJoinCursor(left, right, new int[] { 0 }, row)) {
			assertThat(cursor.next()).isTrue();
			assertThat(row.slots).containsExactly(11L, 22L, UNKNOWN);
			assertThat(cursor.next()).isFalse();
		}
		assertThat(row.slots).containsExactly(11L, UNKNOWN, UNKNOWN);
	}

