	@Test
	void nativeExistsUsesWithheldInvocationRatherThanInvisibleProbe() {
		IRI other = VF.createIRI("urn:exists:other");
		IRI invocation = VF.createIRI("urn:exists:invocation");
		IRI predicate = VF.createIRI("urn:exists:p");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(other, predicate, VF.createIRI("urn:exists:o"));
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			StatementPattern pattern = new StatementPattern(Var.of("x"), Var.of("p", predicate, false, true),
					Var.of("o"));
			assertThat(LmdbNativeAggregateCompiler.tryCompileExists(pattern.clone(), context, strategy, source))
					.as("the unframed bare-pattern EXISTS has a native cursor")
					.isInstanceOf(NativeExistsValueStep.class);
			var exists = strategy.precompile(new Exists(pattern), context);
			QueryBindingSet input = new QueryBindingSet();
			input.addBinding("x", invocation);
			BindingSet withheld = BindingFrameBindings.without(input, Set.of("x"), context);
			QueryBindingSet probe = new QueryBindingSet();
			probe.addBinding("x", other);
			BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(), withheld, probe, context);
			assertThat(exists.evaluate(EmptyBindingSet.getInstance())).isEqualTo(VF.createLiteral(true));
			assertThat(exists.evaluate(input)).isEqualTo(VF.createLiteral(false));
			assertThat(exists.evaluate(framed)).isEqualTo(VF.createLiteral(false));
		}
	}

	@Test
	void nativeCompoundExistsUsesWitnessEntryDomain() {
		IRI absentNode = VF.createIRI("urn:exists:predicate-only");
		IRI subject = VF.createIRI("urn:exists:subject");
		IRI object = VF.createIRI("urn:exists:object");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, absentNode, object);
		}
		StatementPattern input = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		Filter filter = new Filter(values("x", absentNode),
				new Exists(new ZeroLengthPath(Var.of("x"), Var.of("x"))));
		filter.setConditionBindingScope(ConditionBindingScope.ALL);
		TupleExpr host = new Join(input, filter);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			TupleExpr genericHost = host.clone();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
			assertThat(compiled).as("the surrounding host is claimed by the native compiler")
					.isInstanceOf(NativeRowsStep.class);
			assertThat(((NativeRowsStep) compiled).nativePhysicalPlan()).contains("Pattern(");
			List<Map<String, Value>> expected = List
					.of(row("s", subject, "p", absentNode, "o", object, "x", absentNode));
			try (var rows = strategy.genericOnlyView()
					.precompile(genericHost, context)
					.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(mappings(rows)).as("generic witness oracle").containsExactlyElementsOf(expected);
			}
			try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(mappings(rows)).containsExactlyElementsOf(expected);
			}
		}
	}

