	@Test
	void nativeExistsFilterUsesCurrentEntryAndNotOlderWithheldGraphHistory() {
		IRI present = VF.createIRI("urn:nearest-filter:present");
		IRI missing = VF.createIRI("urn:nearest-filter:missing");
		Value keep = literal("keep");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:nearest-filter:s"), VF.createIRI("urn:nearest-filter:p"),
					VF.createIRI("urn:nearest-filter:o"), present);
		}
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet emptyDomain = BindingFrameBindings.withSubstitutionDomain(EmptyBindingSet.getInstance(), Set.of(),
				context);
		MutableBindingSet local = BindingFrameBindings.preserve(emptyDomain, context.createBindingSet(emptyDomain));
		local.setBinding("g", missing);
		BindingSet currentWithheld = BindingFrameBindings.without(local, Set.of("g"), context);
		QueryBindingSet oldRow = new QueryBindingSet();
		oldRow.addBinding("g", missing);
		BindingSet oldDomain = BindingFrameBindings.withSubstitutionDomain(oldRow, Set.of("g"), context);
		BindingSet oldWithheld = BindingFrameBindings.without(oldDomain, Set.of("g"), context);
		BindingSet newerEmpty = BindingFrameBindings.withSubstitutionDomain(oldWithheld, Set.of(), context);
		BindingSet newerUnbound = BindingFrameBindings.withLateralDomain(oldWithheld, Set.of("g"), Set.of("g"),
				context);
		QueryBindingSet unmarkedRow = new QueryBindingSet();
		unmarkedRow.addBinding("g", missing);
		BindingSet unmarked = BindingFrameBindings.without(unmarkedRow, Set.of("g"), context);
		Filter host = new Filter(values("keep", keep), new Exists(new Graph(Var.of("g"), new SingletonSet())));
		host.setConditionBindingScope(ConditionBindingScope.ALL);
		host.setRuntimeTelemetryEnabled(true);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep nativeStep = (NativeRowsStep) compiled;
			if (SCOPE_DIAGNOSTICS) {
				System.out.println("Nearest invocation native EXISTS plan: " + nativeStep.nativePhysicalPlan());
			}
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			record Case(String name, BindingSet input, List<Map<String, Value>> expected) {
			}
			List<Case> cases = List.of(
					new Case("current after empty", currentWithheld, List.of()),
					new Case("older below empty", newerEmpty, List.of(row("keep", keep))),
					new Case("older below UNDEF", newerUnbound, List.of(row("keep", keep))),
					new Case("unmarked", unmarked, List.of()));
			SoftAssertions softly = new SoftAssertions();
			for (Case test : cases) {
				List<Map<String, Value>> genericRows;
				try (var rows = generic.evaluate(test.input())) {
					genericRows = mappings(rows);
				}
				long before = host.getLongMetricActual("nativeInvocationsActual");
				List<Map<String, Value>> nativeRows;
				try (var rows = compiled.evaluate(test.input())) {
					nativeRows = mappings(rows);
				}
				long after = host.getLongMetricActual("nativeInvocationsActual");
				softly.assertThat(genericRows)
						.as("generic result " + test.name())
						.containsExactlyElementsOf(test.expected());
				softly.assertThat(nativeStep.semanticEntryFallbackReason(test.input())).as(test.name()).isNull();
				softly.assertThat(nativeRows)
						.as("native result " + test.name())
						.containsExactlyElementsOf(test.expected());
				softly.assertThat(after).as("native invocation " + test.name()).isPositive().isGreaterThan(before);
			}
			softly.assertAll();
		}
	}

