	@Test
	void compoundTripleRefWorkerRetainsDictionarySemanticsOrDeclines() {
		IRI s = VF.createIRI("urn:worker-term:s");
		IRI p = VF.createIRI("urn:worker-term:p");
		TripleTerm present = VF.createTripleTerm(s, p, VF.createIRI("urn:worker-term:present"));
		TripleTerm absent = VF.createTripleTerm(s, p, VF.createIRI("urn:worker-term:absent"));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(s, p, present);
		}
		TripleRef ref = new TripleRef(Var.of("s"), Var.of("p"), Var.of("o"), Var.of("t"));
		Filter filter = new Filter(new SingletonSet(), new Exists(new Join(ref, new SingletonSet())));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("t")));
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("t", absent);
		BindingSet framed = BindingFrameBindings.without(input, Set.of("t"), context);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			assertThat(source.supportsTripleTermScan()).isTrue();
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(context, strategy, source);
			planner.slot("t");
			NativeBooleanFilter predicate = planner.compileProjectedFilter(filter);
			assertThat(predicate).as("incomplete TripleRef reads use the semantic condition")
					.isInstanceOf(NativeValueOutcomeBooleanFilter.class);
			planner.layout.freeze(planner.slotNames);
			RowState plain = new RowState(source, planner.layout, EmptyBindingSet.getInstance());
			Arrays.fill(plain.slots, UNKNOWN);
			plain.recomputeBoundMask();
			assertThat(predicate.accept(plain)).as("unframed dictionary witness").isTrue();
			try (var rows = strategy.genericOnlyView().precompile(filter.clone(), context).evaluate(framed)) {
				assertThat(rows.hasNext()).as("absent invocation term has no dictionary witness").isFalse();
			}
			assertThat(predicate.parallelWorkerForkable()).isFalse();
			assertThat(predicate.forkForParallelWorker(NativeScalarPlan.WorkerContext.forSource(source, context)))
					.isNull();
			RowState scoped = new RowState(source, planner.layout, framed);
			Arrays.fill(scoped.slots, UNKNOWN);
			scoped.recomputeBoundMask();
			assertThat(predicate.accept(scoped)).isFalse();
			input.setBinding("t", present);
			BindingSet matching = BindingFrameBindings.without(input, Set.of("t"), context);
			RowState matched = new RowState(source, planner.layout, matching);
			Arrays.fill(matched.slots, UNKNOWN);
			matched.recomputeBoundMask();
			assertThat(predicate.accept(matched)).isTrue();
		}
	}

