	@Test
	void optionalEntrySeparatesMatchAuthorityFromGateVisibility() {
		IRI value = VF.createIRI("urn:optional-entry:authority");
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		OptionalCallerRequirement match = new OptionalCallerRequirement(Set.of("x"), false);
		OptionalCallerRequirement gate = new OptionalCallerRequirement(Set.of(), false, Set.of("hit"), false, false);
		QueryBindingSet x = new QueryBindingSet();
		x.addBinding("x", value);
		QueryBindingSet hit = new QueryBindingSet();
		hit.addBinding("hit", value);
		BindingSet markedX = BindingFrameBindings.withSubstitutionDomain(x, Set.of(), context);
		BindingSet markedHit = BindingFrameBindings.withSubstitutionDomain(hit, Set.of(), context);
		BindingSet graphX = GraphFrameBindings.supply(new QueryBindingSet(), "x", value);
		BindingSet graphHit = GraphFrameBindings.supply(new QueryBindingSet(), "hit", value);
		BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(),
				EmptyBindingSet.getInstance(), hit, context);
		BindingSet withheld = BindingFrameBindings.without(hit, Set.of("hit"), context);
		QueryEvaluationContext staticX = new QueryEvaluationContext.Minimal((Dataset) null) {
			@Override
			public Set<String> getSubstitutionBindingNames() {
				return Set.of("x");
			}
		};
		assertAll(
				() -> assertThat(NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(x, match, context))
						.as("an unmarked logical caller constrains OPTIONAL matching")
						.isTrue(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(markedX, match, context))
								.as("a newer empty domain leaves compatibility to later restoration")
								.isFalse(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(graphX, match, context))
								.as("a supplied graph is not an ordinary caller constraint")
								.isFalse(),
				() -> assertThat(NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(x, match, staticX))
						.as("a static invocation input remains available to the OPTIONAL")
						.isFalse(),
				() -> assertThat(NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(hit, gate, context))
						.as("a logical gate input defeats the unbound proof")
						.isTrue(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(markedHit, gate, context))
								.as("an explicit empty marker does not hide a logical gate value")
								.isTrue(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(graphHit, gate, context))
								.as("a supplied graph can be a visible FILTER value")
								.isTrue(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(probe, gate, context))
								.as("a physical probe is not a logical FILTER value")
								.isFalse(),
				() -> assertThat(
						NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(withheld, gate, context))
								.as("an argument-only withheld input is not a logical FILTER value")
								.isFalse(),
				() -> assertThat(NativeEntryBindingVariant.optionalCallerRequiresSemanticEvaluation(x, gate, context))
						.as("an unrelated caller leaves the null-rejecting gate native")
						.isFalse());
	}

	private record GroupEntryFacts(Map<String, Value> logical, Map<String, Boolean> present,
			Set<String> substitutionDomain, Set<String> lateralPrivateInputs, Map<String, Value> withheld,
			Map<String, Value> currentWithheld, Map<String, Value> effectiveProbe, Map<String, Value> graphParameters,
			Map<String, Boolean> supplied, Object frame, boolean visibleProbes, boolean empty) {
	}

	private static GroupEntryFacts groupEntryFacts(BindingSet input, TupleExpr host, QueryEvaluationStep step) {
		Set<String> names = new TreeSet<>(input.getBindingNames());
		names.addAll(host.getBindingNames());
		if (host instanceof Group group) {
			names.addAll(group.getArg().getBindingNames());
		}
		if (step instanceof NativeGroupStep group) {
			names.addAll(Arrays.asList(group.layout.slotNames()));
		}
		names.addAll(Set.of("x", "hit", "unrelated", "hidden"));
		Map<String, Value> logical = new TreeMap<>();
		for (String name : input.getBindingNames()) {
			logical.put(name, input.getValue(name));
		}
		Map<String, Boolean> present = new TreeMap<>();
		Map<String, Value> withheld = new TreeMap<>();
		Map<String, Value> currentWithheld = new TreeMap<>();
		Map<String, Value> effectiveProbe = new TreeMap<>();
		Map<String, Boolean> supplied = new TreeMap<>();
		for (String name : names) {
			present.put(name, input.hasBinding(name));
			withheld.put(name, BindingFrameBindings.withheldInput(input, name));
			currentWithheld.put(name, BindingFrameBindings.currentEntryWithheldInput(input, name));
			effectiveProbe.put(name, BindingFrameBindings.probeValue(input, name));
			supplied.put(name, GraphFrameBindings.isSupplied(input, name));
		}
		Map<String, Value> graphParameters = new TreeMap<>();
		GraphFrameBindings.from(input).visit(graphParameters::put);
		Set<String> domain = BindingFrameBindings.substitutionDomain(input);
		return new GroupEntryFacts(logical, present, domain == null ? null : Set.copyOf(domain),
				Set.copyOf(BindingFrameBindings.lateralPrivateInputs(input)), withheld, currentWithheld,
				effectiveProbe, graphParameters, supplied, BindingFrameBindings.from(input),
				BindingFrameBindings.hasVisibleProbes(input), input.isEmpty());
	}

	private static QueryEvaluationStep compileGroupInputDiagnostic(Group host, QueryEvaluationContext context,
			LmdbNativeEvaluationStrategy strategy, NativeLmdbQuerySource source, List<BindingSet> inputs, String label,
			SoftAssertions softly) {
		// The compiler normally enters this snapshot itself. The outer wrapper lets the diagnostic use that same
		// preparation; compare its observed routes with the archived uninstrumented run.
		return QueryEvaluationUtility.withQuerySafetySnapshot(host, () -> {
			TupleExpr argument = host.getArg();
			Predicate<Set<String>> attachedProof = QueryEvaluationUtility.preparedBindingInjectionProof(argument);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
			boolean sameArgument = host.getArg() == argument;
			boolean attached = argument.getParentNode() == host;
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf(
						"group-prepare %s wrapper=sharedSafetySnapshot sameArg=%s attached=%s arg=%s compiled=%s "
								+ "repeatable=%s queryFatal=%s mappingParameterized=%s producerBoundary=%s "
								+ "dynamicContext=%s staticDomain=%s%n",
						label, sameArgument, attached, argument.getSignature(),
						compiled == null ? null : compiled.getClass().getSimpleName(),
						QueryEvaluationUtility.isRepeatable(argument),
						QueryEvaluationUtility.mayRaiseQueryFatalError(argument),
						QueryEvaluationUtility.usesMappingParameterizedEvaluation(argument),
						QueryEvaluationUtility.hasProducerInputBoundary(argument),
						BindingFrameBindings.hasDynamicSubstitution(context), context.getSubstitutionBindingNames());
			}
			softly.assertThat(sameArgument).as("same attached Group argument %s", label).isTrue();
			softly.assertThat(attached).as("Group argument retains its parent %s", label).isTrue();
			for (int index = 0; index < inputs.size(); index++) {
				BindingSet input = inputs.get(index);
				String entryLabel = label + "/" + index;
				describeGroupModel(host, input, entryLabel);
				GroupEntryFacts entry = groupEntryFacts(input, host, compiled);
				if (compiled instanceof NativeGroupStep group) {
					Set<String> withheld = NativeEntryBindingVariant.problemBindings(input, group.optionalOnlyNames,
							context);
					Set<String> wouldSeed = new LinkedHashSet<>();
					Set<String> presentNull = new LinkedHashSet<>();
					for (String name : group.layout.slotNames()) {
						if (!withheld.contains(name) && input.hasBinding(name)) {
							wouldSeed.add(name);
							if (input.getValue(name) == null) {
								presentNull.add(name);
							}
						}
					}
					Set<String> nonNull = new LinkedHashSet<>(wouldSeed);
					nonNull.removeAll(presentNull);
					Set<String> proofNames = Set.copyOf(nonNull);
					boolean publicProof = QueryEvaluationUtility.permitsBindingInjection(argument, proofNames);
					boolean capturedProof = attachedProof.test(proofNames);
					Boolean compiledProof = group.inputInjectionProof == null ? null
							: group.inputInjectionProof.test(proofNames);
					if (SCOPE_DIAGNOSTICS) {
						System.out.printf("group-entry %s logical=%s layout=%s optionalOnly=%s problemWithheld=%s "
								+ "wouldSeed=%s presentNull=%s proofNames=%s proofSampleExcludesNull=%s "
								+ "publicProof=%s attachedProof=%s "
								+ "compiledProof=%s guard=%s compiledOriginalIsHost=%s%n", entryLabel, entry,
								Arrays.toString(group.layout.slotNames()), Arrays.toString(group.optionalOnlyNames),
								withheld,
								wouldSeed, presentNull, proofNames, !presentNull.isEmpty(), publicProof, capturedProof,
								compiledProof,
								group.semanticEntryFallbackReason(input), group.originalExpr == host);
					}
					softly.assertThat(capturedProof)
							.as("attached exact-set proof %s", entryLabel)
							.isEqualTo(publicProof);
					softly.assertThat(compiledProof)
							.as("compiled exact-set proof %s", entryLabel)
							.isEqualTo(capturedProof);
					if (group.arg instanceof LateralPlan lateral && lateral.right instanceof TupleFunctionPlan tuple) {
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf("group-lateral-grant %s declared=%s entryGrantValue=%s%n", entryLabel,
									tuple.argumentGrant().names(), tuple.argumentGrant().value(input, "x"));
						}
					}
				} else {
					if (SCOPE_DIAGNOSTICS) {
						System.out.printf("group-entry %s logical=%s nativeGroup=unavailable%n", entryLabel, entry);
					}
				}
			}
			return compiled;
		});
	}

	private static String groupModelFrame(QueryAlgebraBindingAnalysis.ReadOnlyContext frame) {
		if (frame == null) {
			return "absent";
		}
		return "visible=" + frame.visibleNames() + " maybe=" + frame.maybeBoundNames() + " guaranteed="
				+ frame.guaranteedNames() + " fixed=" + frame.fixedValues() + " external=" + frame.externalValues()
				+ " externalGuaranteed=" + frame.externalGuaranteedNames() + " domainKnown="
				+ frame.bindingDomainKnown()
				+ " scope=" + frame.scopeIdentity();
	}

	private static String groupModelOutput(QueryAlgebraBindingAnalysis.OutputFacts facts) {
		return "possibleKnown=" + facts.possibleOutputsKnown() + " possible=" + facts.possibleOutputs()
				+ " guaranteedKnown=" + facts.guaranteedOutputsKnown() + " guaranteed=" + facts.guaranteedOutputs()
				+ " retained=" + facts.retainedInputNames() + " overwritten=" + facts.overwrittenInputNames()
				+ " fixed=" + facts.fixedValues() + " canProduceRows=" + facts.canProduceRows();
	}

	private static void describeGroupModel(Group group, BindingSet input, String label) {
		if (!SCOPE_DIAGNOSTICS) {
			return;
		}
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(group, input);
		QueryAlgebraBindingAnalysis.ReadOnlyContext groupInput = analysis.contextAt(group);
		QueryAlgebraBindingAnalysis.ReadOnlyContext argumentInput = analysis.contextAt(group.getArg());
		QueryAlgebraBindingAnalysis.ReadOnlyContext childInput = analysis.childInput(group, group.getArg(), groupInput);
		System.out.printf("group-model %s group={%s} argument={%s} explicitChild={%s} sameChild=%s output={%s}%n",
				label, groupModelFrame(groupInput), groupModelFrame(argumentInput), groupModelFrame(childInput),
				argumentInput.equals(childInput),
				groupModelOutput(analysis.outputFacts(group.getArg(), argumentInput)));
		group.getArg().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(LeftJoin optional) {
				QueryAlgebraBindingAnalysis.ReadOnlyContext entry = analysis.contextAt(optional);
				QueryAlgebraBindingAnalysis.ReadOnlyContext left = analysis.childInput(optional, optional.getLeftArg(),
						entry);
				QueryAlgebraBindingAnalysis.ReadOnlyContext right = analysis.childInput(optional,
						optional.getRightArg(),
						entry);
				QueryAlgebraBindingAnalysis.ReadOnlyContext condition = optional.getCondition() == null ? null
						: analysis.childInput(optional, optional.getCondition(), entry);
				System.out.printf("group-model-optional %s entry={%s} left={%s} right={%s} condition={%s} "
						+ "output={%s}%n", label, groupModelFrame(entry), groupModelFrame(left), groupModelFrame(right),
						groupModelFrame(condition), groupModelOutput(analysis.outputFacts(optional, entry)));
				super.meet(optional);
			}

			@Override
			public void meet(Lateral lateral) {
				QueryAlgebraBindingAnalysis.ReadOnlyContext entry = analysis.contextAt(lateral);
				QueryAlgebraBindingAnalysis.ReadOnlyContext left = analysis.childInput(lateral, lateral.getLeftArg(),
						entry);
				QueryAlgebraBindingAnalysis.ReadOnlyContext right = analysis.childInput(lateral, lateral.getRightArg(),
						entry);
				System.out.printf("group-model-lateral %s declared=%s owners=%s entry={%s} left={%s} right={%s} "
						+ "output={%s}%n", label, lateral.getRightInputBindingNames(),
						BindingScopePolicy.parameterInputEdges(lateral, lateral.getRightInputBindingNames(), true),
						groupModelFrame(entry), groupModelFrame(left), groupModelFrame(right),
						groupModelOutput(analysis.outputFacts(lateral, entry)));
				super.meet(lateral);
			}

			@Override
			public void meet(Filter filter) {
				QueryAlgebraBindingAnalysis.FilterInputFrames frames = analysis.filterInputFrames(filter);
				System.out.printf("group-model-filter %s owners=%s entry={%s} argument={%s} condition={%s} "
						+ "output={%s}%n", label, BindingScopePolicy.filterInputEdges(filter),
						groupModelFrame(frames.entry()), groupModelFrame(frames.argument()),
						groupModelFrame(frames.condition()),
						groupModelOutput(analysis.outputFacts(filter, frames.entry())));
				super.meet(filter);
			}
		});
	}

	private record NativeOptionalObservation(List<Map<String, Value>> rows, long invocations, String fallback,
			String execution, String runtimePlan) {
	}

	private static NativeOptionalObservation observeNativeOptional(String label, QueryEvaluationStep step,
			TupleExpr host,
			BindingSet input) {
		String fallback = step instanceof NativeRowsStep rows ? rows.semanticEntryFallbackReason(input)
				: step instanceof NativeGroupStep group ? group.semanticEntryFallbackReason(input) : null;
		long before = Math.max(0L, host.getLongMetricActual("nativeInvocationsActual"));
		List<Map<String, Value>> actual;
		try (var rows = step.evaluate(input)) {
			actual = mappings(rows);
		}
		long delta = Math.max(0L, host.getLongMetricActual("nativeInvocationsActual")) - before;
		String execution = host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		String runtimePlan = host.getStringMetricActual("runtimePhysicalPlan");
		if (SCOPE_DIAGNOSTICS) {
			String planned = step instanceof LmdbNativePhysicalPlan plan ? plan.nativePhysicalPlan()
					: step.getClass().getSimpleName();
			System.out.printf(
					"optional-entry %s invocations=%d fallback=%s execution=%s planned=%s actualPlan=%s rows=%s%n",
					label, delta, fallback, execution, planned, runtimePlan, actual);
		}
		return new NativeOptionalObservation(actual, delta, fallback, execution, runtimePlan);
	}

	private static void assertOptionalEntryRoute(NativeOptionalObservation actual, boolean semanticFallback,
			String label) {
		if (semanticFallback) {
			assertThat(actual.invocations()).as("no native invocation for %s", label).isZero();
			assertThat(actual.fallback()).as("prepared OPTIONAL guard for %s", label).isEqualTo("optionalEntry");
			assertThat(actual.execution()).as("recorded semantic fallback for %s", label)
					.contains("genericFallback(optionalEntry)");
		} else {
			assertThat(actual.invocations()).as("native invocation for %s", label).isPositive();
			assertThat(actual.fallback()).as("no semantic entry fallback for %s", label).isNull();
		}
	}

	/** A direct Group needs either a safe complete seed or its own evaluator-issued semantic invocation evidence. */
	private static void assertDirectGroupInputFallback(SoftAssertions softly, TupleExpr host, QueryEvaluationStep step,
			BindingSet input, NativeOptionalObservation actual, String label) {
		softly.assertThat(host).as("direct Group host %s", label).isInstanceOf(Group.class);
		softly.assertThat(step).as("direct Group candidate %s", label).isInstanceOf(NativeGroupStep.class);
		if (!(host instanceof Group group) || !(step instanceof NativeGroupStep nativeGroup)) {
			return;
		}
		softly.assertThat(group.getParentNode()).as("no evaluator invocation edge %s", label).isNull();
		softly.assertThat(GroupInvocationBindings.prepared(group)).isNull();
		softly.assertThat(GroupInvocationBindings.prepared(input)).as("no issued target entry %s", label).isNull();
		softly.assertThat(nativeGroup.invocationWitness).as("no direct-call semantic witness %s", label).isNull();
		Set<String> withheld = NativeEntryBindingVariant.problemBindings(input, nativeGroup.optionalOnlyNames,
				nativeGroup.context);
		Set<String> seeded = new TreeSet<>();
		for (String name : nativeGroup.layout.slotNames()) {
			if (input.hasBinding(name) && !withheld.contains(name)) {
				seeded.add(name);
			}
		}
		softly.assertThat(seeded).as("the complete raw seed needs a proof %s", label).isNotEmpty();
		softly.assertThat(nativeGroup.inputInjectionProof).isNotNull();
		if (nativeGroup.inputInjectionProof != null) {
			softly.assertThat(nativeGroup.inputInjectionProof.test(seeded))
					.as("the complete raw seed is unsafe to inject %s", label)
					.isFalse();
		}
		softly.assertThat(actual.fallback()).as("raw Group guard %s", label).isEqualTo("groupInput");
		softly.assertThat(actual.invocations()).as("normalized native counter delta %s", label).isZero();
		softly.assertThat(actual.execution())
				.as("explicit semantic fallback %s", label)
				.contains("genericFallback(groupInput)");
		softly.assertThat(actual.runtimePlan()).as("no plan opened for this invocation %s", label).isNull();
	}

	@ParameterizedTest(name = "aggregate={0}")
	@ValueSource(booleans = { false, true })
	void callerBoundRightOnlyGateRespectsOptionalEntryScope(boolean aggregate) {
		IRI subject = VF.createIRI("urn:optional-gate-input:subject");
		IRI predicate = VF.createIRI("urn:optional-gate-input:predicate");
		IRI outer = VF.createIRI("urn:optional-gate-input:outer");
		IRI inner = VF.createIRI("urn:optional-gate-input:inner");
		IRI outerHit = VF.createIRI("urn:optional-gate-input:outer-hit");
		IRI unrelated = VF.createIRI("urn:optional-gate-input:unrelated");
		Value localHit = literal("local-hit");
		Value value = literal("witness");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			for (IRI resource : List.of(subject, outer, inner, outerHit, unrelated)) {
				connection.add(resource, predicate, value);
			}
		}
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			for (String kind : List.of("caller", "caller-hit", "empty-marker", "disjoint")) {
				for (boolean gated : List.of(false, true)) {
					QueryBindingSet caller = new QueryBindingSet();
					if (kind.equals("disjoint")) {
						caller.addBinding("unrelated", unrelated);
					} else {
						caller.addBinding("x", outer);
						if (!kind.equals("caller")) {
							caller.addBinding("hit", outerHit);
						}
					}
					BindingSet input = kind.equals("empty-marker")
							? BindingFrameBindings.withSubstitutionDomain(caller, Set.of(), context)
							: caller;
					Extension right = new Extension(values("x", inner),
							new ExtensionElem(new ValueConstant(localHit), "hit"));
					TupleExpr optional = new LeftJoin(new SingletonSet(), right);
					if (gated) {
						optional = new Filter(optional, new Bound(Var.of("hit")));
					}
					StatementPattern pattern = new StatementPattern(Var.of("s", subject, false, true),
							Var.of("p", predicate, false, true), Var.of("v"));
					TupleExpr joined = new Join(optional, pattern);
					TupleExpr host;
					if (aggregate) {
						Group group = new Group(joined, List.of("x", "hit", "unrelated"));
						group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
						host = group;
					} else {
						host = new Projection(joined,
								new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("hit"),
										new ProjectionElem("unrelated"), new ProjectionElem("v")),
								false);
					}
					host.setRuntimeTelemetryEnabled(true);
					List<Map<String, Value>> expected;
					Value count = VF.createLiteral("1", XSD.INTEGER);
					if (kind.equals("empty-marker") || kind.equals("caller") && gated
							|| !aggregate && !kind.equals("disjoint")) {
						expected = List.of();
					} else if (kind.equals("caller")) {
						expected = List.of(row("x", outer, "count", count));
					} else if (kind.equals("caller-hit")) {
						expected = List.of(row("x", outer, "hit", outerHit, "count", count));
					} else {
						expected = List.of(aggregate
								? row("x", inner, "hit", localHit, "unrelated", unrelated, "count", count)
								: row("x", inner, "hit", localHit, "unrelated", unrelated, "v", value));
					}
					String label = "aggregate=" + aggregate + " gated=" + gated + " input=" + kind;
					Set<String> domain = BindingFrameBindings.substitutionDomain(input);
					if (SCOPE_DIAGNOSTICS) {
						System.out.printf("optional-gate entry %s domain=%s bindings=%s%n", label, domain, input);
					}
					if (kind.equals("empty-marker")) {
						softly.assertThat(domain).as("explicit empty entry domain " + label).isEmpty();
					} else {
						softly.assertThat(domain).as("unmarked logical caller " + label).isNull();
					}
					QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
					QueryEvaluationStep compiled = host instanceof Group group
							? compileGroupInputDiagnostic(group, context, strategy, source, List.of(input), label,
									softly)
							: LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
					softly.assertThat(compiled)
							.as("native host admission " + label)
							.isInstanceOf(aggregate ? NativeGroupStep.class : NativeRowsStep.class);
					GroupEntryFacts before = groupEntryFacts(input, host, compiled);
					try (var rows = generic.evaluate(input)) {
						List<Map<String, Value>> genericRows = mappings(rows);
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf("optional-gate generic %s expected=%s actual=%s%n", label, expected,
									genericRows);
						}
						softly.assertThat(genericRows)
								.as("independent generic bag " + label)
								.containsExactlyElementsOf(expected);
					}
					GroupEntryFacts afterGeneric = groupEntryFacts(input, host, compiled);
					softly.assertThat(afterGeneric).as("generic caller unchanged " + label).isEqualTo(before);
					if (compiled != null) {
						String pathBefore = host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
						NativeOptionalObservation actual = observeNativeOptional(label, compiled, host, input);
						GroupEntryFacts afterSelected = groupEntryFacts(input, host, compiled);
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf("optional-gate transition %s pathBefore=%s callerBefore=%s "
									+ "callerAfterGeneric=%s callerAfterSelected=%s%n", label, pathBefore, before,
									afterGeneric, afterSelected);
						}
						softly.assertThat(afterSelected).as("selected caller unchanged " + label).isEqualTo(before);
						softly.assertThat(actual.rows())
								.as("selected execution bag " + label)
								.containsExactlyElementsOf(expected);
						softly.assertThat(actual.invocations() > 0
								|| actual.execution() != null && actual.execution().contains("genericFallback"))
								.as("actual native invocation or recorded semantic fallback " + label)
								.isTrue();
						if (actual.invocations() > 0) {
							softly.assertThat(actual.fallback())
									.as("native entry has no fallback reason " + label)
									.isNull();
							softly.assertThat(actual.runtimePlan())
									.as("actual per-evaluation native plan " + label)
									.isNotBlank();
						}
						if (aggregate && kind.equals("caller") && gated) {
							assertDirectGroupInputFallback(softly, host, compiled, input, actual, label);
						} else if (kind.equals("disjoint") || kind.equals("caller") && gated) {
							softly.assertThat(actual.invocations()).as("safe native route " + label).isPositive();
							softly.assertThat(actual.execution())
									.as("no semantic fallback " + label)
									.doesNotContain("genericFallback");
						}
						if (!aggregate && kind.equals("caller") && gated) {
							softly.assertThat(actual.runtimePlan())
									.as("executed null-rejecting inner join " + label)
									.contains("Join(", "Filter(")
									.doesNotContain("LeftJoin(");
						}
					}
				}
			}
		}
		softly.assertAll();
	}

