	@ParameterizedTest(name = "empty enclosing domain={0}, equal write={1}")
	@MethodSource("graphWriteCases")
	void nativeLateralDoesNotRestoreGraphAuthorityAfterEqualLocalWrite(boolean marked, boolean equal) {
		IRI subject = VF.createIRI("urn:lateral-write:subject");
		IRI predicate = VF.createIRI("urn:lateral-write:p");
		IRI graph = VF.createIRI("urn:lateral-write:graph");
		IRI otherGraph = VF.createIRI("urn:lateral-write:other-graph");
		IRI other = VF.createIRI("urn:lateral-write:other");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, graph);
			connection.add(other, predicate, other);
		}
		TupleExpr left = new Extension(values("seed", literal("seed"), literal("seed")),
				new ExtensionElem(new ValueConstant(equal ? graph : other), "g"));
		TupleExpr optional = new LeftJoin(new SingletonSet(), values("g", other));
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("g"));
		Lateral lateral = new Lateral(left, new Join(optional, pattern), Set.of("g"));
		TupleExpr host = lateral;
		host.setRuntimeTelemetryEnabled(true);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		MutableBindingSet supplied = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
		supplied = GraphFrameBindings.supply(supplied, "h", otherGraph);
		BindingSet input = marked ? BindingFrameBindings.withSubstitutionDomain(supplied, Set.of(), context) : supplied;
		List<Map<String, Value>> expected = equal ? List.of(
				row("seed", literal("seed"), "g", graph, "h", otherGraph, "s", subject, "p", predicate),
				row("seed", literal("seed"), "g", graph, "h", otherGraph, "s", subject, "p", predicate)) : List.of();
		List<Map<String, Value>> downstreamExpected = marked ? List.of() : expected;
		Set<String> expectedDomain = marked ? Set.of() : null;
		SoftAssertions softly = new SoftAssertions();
		softly.assertThat(BindingFrameBindings.substitutionDomain(input))
				.as("host input invocation domain")
				.isEqualTo(expectedDomain);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
			QueryEvaluationStep downstream = strategy.genericOnlyView()
					.precompile(new LeftJoin(new SingletonSet(), values("g", other)), context);
			QueryEvaluationStep downstreamGate = strategy.genericOnlyView()
					.precompile(new Filter(graphWriteCompatibilityOptional("g", other),
							new Bound(Var.of("graphOptionalMatched"))), context);
			assertThat(compiled).as("the enclosing host must be native").isInstanceOf(NativeRowsStep.class);
			assertThat(((NativeRowsStep) compiled).nativePhysicalPlan()).contains("Lateral(", "Pattern(");
			for (QueryEvaluationStep step : List.of(generic, compiled)) {
				String route = step == generic ? "generic" : "native";
				List<Map<String, Value>> actual = new ArrayList<>();
				List<Map<String, Value>> downstreamRows = new ArrayList<>();
				List<Map<String, Value>> gatedRows = new ArrayList<>();
				List<Boolean> writtenOrigin = new ArrayList<>();
				List<Boolean> unrelatedOrigin = new ArrayList<>();
				long nativeBefore = Math.max(0L, host.getLongMetricActual("nativeInvocationsActual"));
				try (var rows = step.evaluate(input)) {
					while (rows.hasNext()) {
						BindingSet row = rows.next();
						Set<String> currentDomain = BindingFrameBindings.substitutionDomain(row);
						softly.assertThat(currentDomain)
								.as("%s local output invocation domain", route)
								.isEqualTo(expectedDomain);
						softly.assertThat(row.getValue("g"))
								.as("%s locally written graph value", route)
								.isEqualTo(graph);
						softly.assertThat(GraphFrameBindings.isSupplied(row, "g"))
								.as("%s local write cleared GRAPH authority before OPTIONAL", route)
								.isFalse();
						if (SCOPE_DIAGNOSTICS) {
							System.out.printf(
									"graph-local-optional route=%s marked=%s inputDomain=%s rowDomain=%s g=%s%n",
									route, marked, BindingFrameBindings.substitutionDomain(input), currentDomain,
									row.getValue("g"));
						}
						try (var evaluated = downstream.evaluate(row)) {
							downstreamRows.addAll(mappings(evaluated));
						}
						try (var evaluated = downstreamGate.evaluate(row)) {
							gatedRows.addAll(mappings(evaluated));
						}
						writtenOrigin.add(GraphFrameBindings.isSupplied(row, "g"));
						unrelatedOrigin.add(GraphFrameBindings.isSupplied(row, "h"));
						Map<String, Value> mapping = new TreeMap<>();
						for (String name : row.getBindingNames()) {
							mapping.put(name, row.getValue(name));
						}
						actual.add(mapping);
					}
				}
				assertThat(actual).as("%s exact result bag", route).containsExactlyElementsOf(expected);
				if (step == compiled) {
					if (SCOPE_DIAGNOSTICS) {
						System.out.printf("graph-local-optional native invocations=%d execution=%s actualPlan=%s%n",
								Math.max(0L, host.getLongMetricActual("nativeInvocationsActual")) - nativeBefore,
								host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH),
								host.getStringMetricActual("runtimePhysicalPlan"));
					}
					assertThat(host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
							.as("the graph assignment is evaluated before native provenance can be lost")
							.contains("genericFallback(graphAssignment)");
				}
				softly.assertThat(downstreamRows)
						.as("%s OPTIONAL after invocation-domain restoration", route)
						.containsExactlyElementsOf(downstreamExpected);
				softly.assertThat(gatedRows).as("%s BOUND removes unmatched OPTIONAL rows", route).isEmpty();
				assertThat(writtenOrigin).as("%s local assignment replaces graph origin", route)
						.containsExactlyElementsOf(equal ? List.of(false, false) : List.of());
				assertThat(unrelatedOrigin).as("%s unrelated graph origin remains available", route)
						.containsExactlyElementsOf(equal ? List.of(true, true) : List.of());
			}
		}
		softly.assertAll();
	}

	private static Stream<Arguments> graphWriteCases() {
		return Stream.of(false, true)
				.flatMap(marked -> Stream.of(false, true).map(equal -> Arguments.of(marked, equal)));
	}

	private static LeftJoin graphWriteCompatibilityOptional(String name, Value value) {
		Extension right = new Extension(values(name, value),
				new ExtensionElem(new ValueConstant(VF.createLiteral(true)), "graphOptionalMatched"));
		return new LeftJoin(new SingletonSet(), right);
	}

