	@ParameterizedTest(name = "{0}, equal write={1}")
	@MethodSource("nestedGraphWriteCases")
	void nestedGraphParameterLosesAuthorityAfterLocalWrite(String shape, boolean equal) throws IOException {
		IRI graph = VF.createIRI("urn:nested-graph-write:graph");
		IRI other = VF.createIRI("urn:nested-graph-write:other");
		IRI subject = VF.createIRI("urn:nested-graph-write:subject");
		IRI predicate = VF.createIRI("urn:nested-graph-write:p");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, literal("value"));
			connection.add(VF.createIRI("urn:nested-graph-write:named"), predicate, literal("named"), graph);
		}
		Value written = equal ? graph : other;
		TupleExpr input = new StatementPattern(Var.of("s", subject, false, true),
				Var.of("p", predicate, false, true), Var.of("v"));
		TupleExpr write = new Extension(input, new ExtensionElem(new ValueConstant(written), "privateGraph"));
		TupleExpr body;
		if (shape.equals("group")) {
			Group group = new Group(write, List.of("privateGraph"));
			group.addGroupElement(new GroupElem("count", new Count(Var.of("v"), false)));
			body = group;
		} else {
			body = write;
		}
		body.setRuntimeTelemetryEnabled(true);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(body, context, strategy, source);
			assertThat(compiled).as("the child has a native %s host", shape)
					.isInstanceOf(shape.equals("group") ? NativeGroupStep.class : NativeRowsStep.class);
			QueryEvaluationStep downstream = strategy.genericOnlyView()
					.precompile(new LeftJoin(new SingletonSet(), values("privateGraph", equal ? other : graph)),
							context);
			QueryEvaluationStep downstreamGate = strategy.genericOnlyView()
					.precompile(new Filter(graphWriteCompatibilityOptional("privateGraph", equal ? other : graph),
							new Bound(Var.of("graphOptionalMatched"))), context);
			AtomicInteger entries = new AtomicInteger();
			AtomicInteger results = new AtomicInteger();
			QueryEvaluationStep observed = bindings -> {
				assertThat(GraphFrameBindings.isSupplied(bindings, "privateGraph"))
						.as("the native subquery introduces the selected GRAPH parameter")
						.isTrue();
				assertThat(bindings.getValue("privateGraph")).isEqualTo(graph);
				entries.incrementAndGet();
				return new ConvertingIteration<BindingSet, BindingSet>(compiled.evaluate(bindings)) {
					@Override
					protected BindingSet convert(BindingSet result) {
						assertThat(result.getValue("privateGraph")).isEqualTo(written);
						assertThat(GraphFrameBindings.isSupplied(result, "privateGraph"))
								.as("a local write invalidates the inherited GRAPH authority")
								.isFalse();
						Map<String, Value> expectedRow = new TreeMap<>();
						result.forEach(binding -> expectedRow.put(binding.getName(), binding.getValue()));
						List<Map<String, Value>> bareRows;
						try (var optional = downstream.evaluate(result)) {
							bareRows = mappings(optional);
						}
						List<Map<String, Value>> gatedRows;
						try (var optional = downstreamGate.evaluate(result)) {
							gatedRows = mappings(optional);
						}
						assertAll(
								() -> assertThat(bareRows).as("incompatible OPTIONAL retains the local left row")
										.containsExactly(expectedRow),
								() -> assertThat(gatedRows).as("BOUND removes the unmatched local row").isEmpty());
						results.incrementAndGet();
						return result;
					}
				};
			};
			SyntheticValueSource evaluation = SyntheticValueSource.forEvaluation(source);
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("graph", 0, "result", 1), null);
			layout.freeze(List.of("graph", "result"));
			BindingSet empty = EmptyBindingSet.getInstance();
			evaluation.executionContext().initializeQueryBase(empty);
			RowState row = new RowState(evaluation, layout, empty);
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, empty, evaluation, layout)).isTrue();
				NativeGraphPlan selector = new NativeGraphPlan(new Graph(Var.of("graph"), new SingletonSet()),
						context, strategy, source, new int[] { 0 }, new String[] { "graph" }, new int[0],
						new String[0], Set.of(), Set.of());
				NativeSubqueryPlan subquery = new NativeSubqueryPlan(observed, new int[] { 1 },
						new String[] { "privateGraph" }, new int[] { 0 }, new String[] { "graph" },
						new String[] { "privateGraph" }, new String[] { "privateGraph" }, null, context);
				List<Map<String, Value>> actual = new ArrayList<>();
				try (RowCursor rows = new JoinPlan(selector, subquery).open(row)) {
					while (row.advance(rows)) {
						actual.add(row("graph", row.view.getValue("graph"), "result", row.view.getValue("result")));
					}
				}
				assertThat(actual).containsExactly(row("graph", graph, "result", written));
				assertThat(entries).hasValue(1);
				assertThat(results).hasValue(1);
				assertThat(body.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
						.as("the child guards its newly supplied GRAPH frame")
						.contains("genericFallback(graphAssignment)");
			} finally {
				row.closeDecodedInputs();
				evaluation.executionContext().close();
			}
		}
	}

	@ParameterizedTest(name = "{0}")
	@ValueSource(strings = { "owner", "wrong-owner", "isolated", "empty", "unbound" })
	void parentlessGraphWorkerRetainsOnlyItsPreparedOwnerGrant(String scenario) throws IOException {
		IRI first = VF.createIRI("urn:worker-owner:first");
		IRI second = VF.createIRI("urn:worker-owner:second");
		IRI predicate = VF.createIRI("urn:worker-owner:predicate");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:worker-owner:s1"), predicate, literal("one"), first);
			connection.add(VF.createIRI("urn:worker-owner:s2"), predicate, literal("two"), second);
		}
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		Graph graph = new Graph(Var.of("g"), new Filter(new SingletonSet(), new Not(new Bound(Var.of("g")))));
		Join owner = new Join(values("g", first), graph);
		BindingFrameBindings.Scope ownerScope = BindingFrameBindings.scopeFor(owner);
		assertThat(graph.getParentNode()).isSameAs(owner);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			NativeGraphPlan prepared = new NativeGraphPlan(graph, context, strategy, source, new int[] { 0 },
					new String[] { "g" }, new int[0], new String[0], Set.of(), Set.of());
			assertThat(prepared.describe()).contains("NativeGraph(selector=g");
			QueryBindingSet probe = new QueryBindingSet();
			probe.addBinding("g", first);
			BindingFrameBindings.Scope scope = scenario.equals("wrong-owner")
					? new BindingFrameBindings.Scope()
					: ownerScope;
			BindingSet input = BindingFrameBindings.push(scope, EmptyBindingSet.getInstance(), probe, context);
			if (scenario.equals("isolated")) {
				input = BindingFrameBindings.isolate(input, context);
			} else if (scenario.equals("empty")) {
				input = BindingFrameBindings.withSubstitutionDomain(input, Set.of(), context);
			} else if (scenario.equals("unbound")) {
				input = BindingFrameBindings.withLateralDomain(input, Set.of("g"), Set.of("g"), context);
			}
			List<Map<String, Value>> expected = scenario.equals("owner")
					? List.of(row("g", first))
					: List.of(row("g", first), row("g", second));
			for (boolean worker : List.of(false, true)) {
				SyntheticValueSource evaluation = SyntheticValueSource.forEvaluation(source);
				evaluation.executionContext().initializeQueryBase(input);
				NativeSlotLayout layout = new NativeSlotLayout(Map.of("g", 0), null);
				layout.freeze(List.of("g"));
				RowState row = new RowState(evaluation, layout, input);
				try {
					assertThat(LmdbNativeAggregateCompiler.initializeRow(row, input, evaluation, layout)).isTrue();
					long workerBindings = NativeGraphPlan.WORKER_BINDINGS.get();
					NativeGraphPlan selected = worker
							? prepared.forWorker(new NativeScalarPlan.WorkerContext(evaluation,
									evaluation.nativeValueCodec(), context))
							: prepared;
					assertThat(selected.describe()).contains("NativeGraph(selector=g");
					if (worker) {
						assertThat(NativeGraphPlan.WORKER_BINDINGS.get()).isGreaterThan(workerBindings);
					}
					AtomicInteger openings = new AtomicInteger();
					List<Map<String, Value>> actual = new ArrayList<>();
					try (RowCursor cursor = selected.open(row)) {
						openings.incrementAndGet();
						while (row.advance(cursor)) {
							actual.add(row("g", row.view.getValue("g")));
						}
					}
					assertThat(openings).as("native GRAPH invocation for %s, worker=%s", scenario, worker)
							.hasValue(1);
					assertThat(actual).as("%s, worker=%s", scenario, worker)
							.containsExactlyInAnyOrderElementsOf(expected);
				} finally {
					row.closeDecodedInputs();
					evaluation.executionContext().close();
				}
			}
		}
	}

	private static Stream<Arguments> nestedGraphWriteCases() {
		return Stream.of("row", "group")
				.flatMap(shape -> Stream.of(false, true).map(equal -> Arguments.of(shape, equal)));
	}

