	@Test
	void guardedLateralDoesNotExposeBorrowedSiblingToItsBind() {
		IRI subject = VF.createIRI("urn:lateral-probe:subject");
		IRI predicate = VF.createIRI("urn:lateral-probe:p");
		IRI outer = VF.createIRI("urn:lateral-probe:outer");
		IRI other = VF.createIRI("urn:lateral-probe:other");
		IRI graph = VF.createIRI("urn:lateral-probe:graph");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, outer);
			connection.add(other, predicate, other, graph);
		}
		TupleExpr left = new Extension(values("x", outer, outer),
				new ExtensionElem(new Bound(Var.of("sibling")), "leak"));
		TupleExpr optional = new LeftJoin(new SingletonSet(), values("x", other));
		TupleExpr graphLookup = new Graph(Var.of("sibling"), new SingletonSet());
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("x"));
		Lateral lateral = new Lateral(left, new Join(new Join(optional, graphLookup), pattern), Set.of("x"));
		TupleExpr host = new Join(values("sibling", graph), lateral.clone());
		host.setRuntimeTelemetryEnabled(true);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingSet entry = BindingFrameBindings.withSubstitutionDomain(new QueryBindingSet(), Set.of(), context);
		List<Map<String, Value>> expected = List.of(
				row("x", outer, "sibling", graph, "leak", VF.createLiteral(false), "s", subject, "p", predicate),
				row("x", outer, "sibling", graph, "leak", VF.createLiteral(false), "s", subject, "p", predicate));
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			try (var rows = generic.evaluate(entry)) {
				assertThat(mappings(rows)).as("generic scoped invocation").containsExactlyElementsOf(expected);
			}
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(lateral, context, strategy, source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep nativeStep = (NativeRowsStep) compiled;
			assertThat(nativeStep.arg).isInstanceOf(LateralPlan.class);
			assertThat(((LateralPlan) nativeStep.arg).semanticEntry).isNotNull();
			Integer siblingSlot = nativeStep.layout.slot("sibling");
			assertThat(siblingSlot).isNotNull();
			long graphId = nativeStep.source.idOf(graph, nativeStep.layout.positionMask(siblingSlot));
			assertThat(graphId).isNotEqualTo(UNKNOWN);
			SlotPlan physicalSibling = SlotPlan.values(new ValuesRow[] {
					new ValuesRow(new int[] { siblingSlot }, new long[] { graphId }) });
			SlotPlan ambiguous = new JoinPlan(physicalSibling, nativeStep.arg);
			NativeRowsStep hosted = new NativeRowsStep(nativeStep.source, ambiguous, nativeStep.layout,
					nativeStep.sourceSlots, nativeStep.targetNames, false, new int[0], new boolean[0], 0L, -1L,
					false, strategy, host, context, Set.of(), null, null);
			assertThat(hosted.nativePhysicalPlan()).contains("Join(", "Lateral(");
			try (var rows = hosted.evaluate(entry)) {
				assertThat(mappings(rows)).as("native host must keep the sibling probe hidden")
						.containsExactlyElementsOf(expected);
			}
			assertThat(host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
					.as("the ambiguous host falls back before its physical sibling opens")
					.contains("genericFallback(semanticLateralEntry)");
		}
	}

