	@ParameterizedTest(name = "overwriting invocation={0}")
	@ValueSource(booleans = { false, true })
	void typedAggregateFallbackKeepsOverwrittenInvocation(boolean overwriting) {
		IRI subject = VF.createIRI("urn:typed-entry:subject");
		IRI predicate = VF.createIRI("urn:typed-entry:p");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, literal("value"));
		}
		String query = "SELECT (STRLEN(GROUP_CONCAT(?x; SEPARATOR=\"\")) AS ?length) WHERE { "
				+ "?s <urn:typed-entry:p> ?v BIND(\"abc\" AS ?x) }";
		TupleExpr host = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		NativeValuePositionAnalysis positions = NativeValuePositionAnalysis.analyze(host);
		List<NativeAggregateResultDemand> demands = new ArrayList<>();
		AtomicReference<Group> observedGroup = new AtomicReference<>();
		host.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Group group) {
				group.setRuntimeTelemetryEnabled(true);
				observedGroup.set(group);
				super.meet(group);
			}

			@Override
			public void meet(GroupElem element) {
				demands.add(positions.aggregateDemand(element));
				super.meet(element);
			}
		});
		assertThat(demands).containsExactly(NativeAggregateResultDemand.LEXICAL_LENGTH);
		QueryBindingSet input = new QueryBindingSet();
		if (overwriting) {
			input.addBinding("x", literal("old"));
		}
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		List<Map<String, Value>> expected = List.of(row("length", VF.createLiteral("3", XSD.INTEGER)));
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			QueryEvaluationStep compiled = strategy.withValuePositions(positions,
					() -> LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source));
			assertThat(compiled).as("the length-only query retains a native physical consumer")
					.isInstanceOf(NativeBindingSetProjectionStep.class);
			assertThat(((NativeBindingSetProjectionStep) compiled).requiresPhysicalResults()).isTrue();
			try (var rows = generic.evaluate(input)) {
				assertThat(mappings(rows)).as("generic exact result").containsExactlyElementsOf(expected);
			}
			try (var rows = compiled.evaluate(input)) {
				assertThat(mappings(rows)).as("typed result for the same invocation")
						.containsExactlyElementsOf(expected);
			}
			if (overwriting) {
				assertThat(observedGroup.get().getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
						.contains("genericFallback(entryAssignment)");
			} else {
				assertThat(observedGroup.get().getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH))
						.as("the unbound input executes a native aggregate path")
						.isNotNull()
						.doesNotContain("genericFallback");
			}
		}
	}

