	@Test
	void projectedNativeExistsKeepsDisjointLateralOptionalWitness() {
		IRI subject = VF.createIRI("urn:disjoint-lateral:subject");
		IRI predicate = VF.createIRI("urn:disjoint-lateral:p");
		IRI input = VF.createIRI("urn:disjoint-lateral:input");
		IRI output = VF.createIRI("urn:disjoint-lateral:output");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, input);
			connection.add(subject, predicate, output);
		}
		LeftJoin optional = new LeftJoin(new SingletonSet(), values("y", output));
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true),
				Var.of("y"));
		Lateral lateral = new Lateral(values("x", input), new Join(optional, pattern), Set.of("x"));
		Filter filter = new Filter(new SingletonSet(), new Exists(lateral));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of("keep")));
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			SyntheticValueSource evaluation = SyntheticValueSource.forEvaluation(source);
			try {
				evaluation.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
				LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(context, strategy, evaluation);
				planner.slot("keep");
				NativeBooleanFilter predicateFilter = planner.compileProjectedFilter(filter);
				assertThat(predicateFilter).as("the disjoint witness retains its native route")
						.isInstanceOf(ExistsFilter.class);
				planner.layout.freeze(planner.slotNames);
				RowState row = new RowState(evaluation, planner.layout, EmptyBindingSet.getInstance());
				Arrays.fill(row.slots, UNKNOWN);
				row.recomputeBoundMask();
				try (var rows = strategy.genericOnlyView()
						.precompile(filter.clone(), context)
						.evaluate(EmptyBindingSet.getInstance())) {
					assertThat(rows.hasNext()).as("the generic witness has one row").isTrue();
					rows.next();
					assertThat(rows.hasNext()).isFalse();
				}
				assertThat(predicateFilter.accept(row)).isTrue();
			} finally {
				evaluation.executionContext().close();
			}
		}
	}

	@ParameterizedTest(name = "{0}")
	@ValueSource(strings = { "marker", "empty", "static", "static-empty", "ordinary" })
	void nativeMixedHostRespectsTheExistsInvocationDomain(String kind) {
		IRI subject = VF.createIRI("urn:domain-host:subject");
		IRI predicate = VF.createIRI("urn:domain-host:p");
		Value outer = literal("outer");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, outer);
		}
		QueryEvaluationContext base = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryEvaluationContext fixed = new QueryEvaluationContext.Minimal((Dataset) null) {
			@Override
			public Set<String> getSubstitutionBindingNames() {
				return Set.of("x");
			}
		};
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			TripleSource triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationContext context = kind.equals("marker") || kind.equals("empty")
					? captureDynamicContext(triples, base, outer)
					: kind.startsWith("static") ? fixed : base;
			LeftJoin optional = new LeftJoin(values("o", literal("o")), values("z", literal("z")),
					new Compare(Var.of("x"), new ValueConstant(outer), Compare.CompareOp.EQ));
			StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true),
					Var.of("v"));
			Projection host = new Projection(new Join(optional, pattern),
					new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("o"), new ProjectionElem("z"),
							new ProjectionElem("s"), new ProjectionElem("v")),
					false);
			host.setRuntimeTelemetryEnabled(true);
			QueryBindingSet inputRow = new QueryBindingSet();
			inputRow.addBinding("x", outer);
			BindingSet input = inputRow;
			if (kind.equals("marker") || kind.equals("empty") || kind.equals("static-empty")) {
				input = BindingFrameBindings.withSubstitutionDomain(input,
						kind.equals("marker") ? Set.of("x") : Set.of(), base);
			}
			List<Map<String, Value>> expected = kind.equals("marker") || kind.equals("static")
					? List.of(row("x", outer, "o", literal("o"), "z", literal("z"), "s", subject, "v", outer))
					: List.of(row("x", outer, "o", literal("o"), "s", subject, "v", outer));
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(host.clone(), context);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(host, context, strategy, source);
			assertThat(compiled).as("the mixed host must be native").isInstanceOf(NativeRowsStep.class);
			NativeRowsStep nativeStep = (NativeRowsStep) compiled;
			assertThat(nativeStep.nativePhysicalPlan()).contains("Pattern(");
			if (kind.equals("marker") || kind.equals("empty")) {
				assertThat(nativeStep.nativePhysicalPlan()).contains("GenericEvalPlan");
			}
			assertThat(nativeStep.optionalOnlyNames).contains("x");
			try (var rows = generic.evaluate(input)) {
				assertThat(mappings(rows)).as("generic %s", kind).containsExactlyElementsOf(expected);
			}
			long nativeBefore = host.getLongMetricActual("nativeInvocationsActual");
			List<Map<String, Value>> actual;
			try (var rows = nativeStep.evaluate(input)) {
				actual = mappings(rows);
			}
			long nativeAfter = host.getLongMetricActual("nativeInvocationsActual");
			long nativeDelta = Math.max(0L, nativeAfter) - Math.max(0L, nativeBefore);
			String executionPath = host.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("exists-host=mixed kind=%s actual=%s path=%s nativeBefore=%d nativeAfter=%d "
						+ "nativeDelta=%d%n", kind, actual, executionPath, nativeBefore, nativeAfter, nativeDelta);
			}
			assertThat(actual).as("diagnostic mixed host bag %s", kind).containsExactlyElementsOf(expected);
			if (kind.equals("ordinary")) {
				assertThat(nativeDelta).as("ordinary host has no native invocation").isZero();
				assertThat(executionPath).as("ordinary host uses the semantic fallback")
						.contains("genericFallback(optionalEntry)");
			} else {
				assertThat(host.getLongMetricActual("nativeInvocationsActual"))
						.as("the host actually executed natively for %s", kind)
						.isPositive();
			}
			assertThat(actual).as("native %s", kind).containsExactlyElementsOf(expected);
		}
	}

	@Test
	void actualExistsInvokesItsCountZGroupNatively() {
		IRI subject = VF.createIRI("urn:domain-group:subject");
		IRI predicate = VF.createIRI("urn:domain-group:p");
		Value outer = literal("outer");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, outer);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			Group group = countZInvocationGroup(predicate, outer);
			assertThat(QueryEvaluationUtility.isRepeatable(group.getArg())).as("the bag replay input is repeatable")
					.isTrue();
			assertThat(QueryEvaluationUtility.mayRaiseQueryFatalError(group.getArg())).isFalse();
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			Exists exists = new Exists(group);
			QueryValueEvaluationStep generic = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(new Exists(group.clone()), context);
			Group unobservedGroup = group.clone();
			Exists unobservedExists = new Exists(unobservedGroup);
			QueryValueEvaluationStep unobserved = groupEmissionStrategy(dataset)
					.precompile(unobservedExists, context);
			LmdbNativeEvaluationStrategy strategy = spy(groupEmissionStrategy(dataset));
			AttachedGroupProbe probe = new AttachedGroupProbe(strategy, group);
			QueryValueEvaluationStep selected = strategy.precompile(exists, context);
			assertThat(exists.getSubQuery()).as("the evaluated EXISTS owns the exact Count(z) Group").isSameAs(group);
			assertThat(group.getParentNode()).isSameAs(exists);
			assertThat(unobservedExists.getSubQuery()).isSameAs(unobservedGroup);
			assertThat(unobservedGroup.getParentNode()).isSameAs(unobservedExists);
			QueryBindingSet caller = new QueryBindingSet();
			caller.addBinding("x", outer);
			GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
			assertThat(generic.evaluate(caller)).as("independent generic EXISTS").isEqualTo(VF.createLiteral(true));
			assertThat(groupEntryFacts(caller, group, null)).isEqualTo(callerBefore);
			long unobservedBefore = resetAttachedGroupMetrics(unobservedGroup);
			Value unobservedResult = unobserved.evaluate(caller);
			long unobservedAfter = unobservedGroup.getLongMetricActual("nativeInvocationsActual");
			long unobservedDelta = Math.max(0L, unobservedAfter) - unobservedBefore;
			String unobservedPath = unobservedGroup.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
			String unobservedPlan = unobservedGroup.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			assertThat(groupEntryFacts(caller, group, null)).isEqualTo(callerBefore);
			long observedBefore = resetAttachedGroupMetrics(group);
			Value observedResult = selected.evaluate(caller);
			long observedAfter = group.getLongMetricActual("nativeInvocationsActual");
			long observedDelta = Math.max(0L, observedAfter) - observedBefore;
			String observedPath = group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
			String observedPlan = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			AttachedGroupEntry entry = probe.onlyEntrySince(0, "actual EXISTS Count(z)");
			assertThat(entry.step()).isInstanceOf(NativeGroupStep.class);
			NativeGroupStep nativeGroup = (NativeGroupStep) entry.step();
			GroupInvocationBindings.Prepared prepared = GroupInvocationBindings.prepared(entry.bindings());
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(unobservedResult).isEqualTo(VF.createLiteral(true));
			softly.assertThat(observedResult).isEqualTo(VF.createLiteral(true));
			softly.assertThat(nativeGroup.originalExpr).isSameAs(group);
			softly.assertThat(entry.dynamicContext()).isTrue();
			softly.assertThat(BindingFrameBindings.substitutionDomain(entry.bindings())).containsExactly("x");
			softly.assertThat(entry.bindings().getBindingNames()).containsExactly("x");
			softly.assertThat(entry.bindings().getValue("x")).isEqualTo(outer);
			softly.assertThat(prepared).as("the actual EXISTS issued the exact Group capability").isNotNull();
			if (prepared != null) {
				softly.assertThat(prepared.represents(group)).isTrue();
				softly.assertThat(prepared.admits(entry.bindings())).isTrue();
			}
			softly.assertThat(GroupInvocationBindings.prepared(group)).as("preparation metadata was removed").isNull();
			softly.assertThat(nativeGroup.invocationWitness)
					.as("the selected Count(z) input has its own witness")
					.isNotNull();
			softly.assertThat(entry.fallbackReason()).isNull();
			softly.assertThat(observedDelta)
					.as("first real observed EXISTS invocation, before bag replay")
					.isPositive();
			softly.assertThat(unobservedDelta)
					.as("first real unobserved EXISTS invocation, before bag replay")
					.isPositive();
			softly.assertThat(observedPath).isNotBlank().doesNotContain("genericFallback");
			softly.assertThat(unobservedPath).isNotBlank().doesNotContain("genericFallback");
			softly.assertThat(observedPlan).isNotBlank();
			softly.assertThat(unobservedPlan).isNotBlank();
			softly.assertThat(groupEntryFacts(entry.bindings(), group, nativeGroup)).isEqualTo(entry.before());
			softly.assertThat(groupEntryFacts(caller, group, null)).isEqualTo(callerBefore);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("actual-exists-count-z firstObservedBefore=%d firstObservedAfter=%d "
						+ "firstObservedDelta=%d "
						+ "firstUnobservedBefore=%d firstUnobservedAfter=%d firstUnobservedDelta=%d "
						+ "domain=%s capability=%s witness=%s guard=%s firstObservedPath=%s firstUnobservedPath=%s "
						+ "firstObservedPlan=%s firstUnobservedPlan=%s%n", observedBefore, observedAfter, observedDelta,
						unobservedBefore, unobservedAfter, unobservedDelta,
						BindingFrameBindings.substitutionDomain(entry.bindings()), prepared != null,
						nativeGroup.invocationWitness != null, entry.fallbackReason(), observedPath, unobservedPath,
						observedPlan != null, unobservedPlan != null);
			}

			// EXISTS has already closed its iteration. These pure bag evaluations reuse the exact issued entry;
			// their counters cannot provide evidence for either first EXISTS invocation recorded above.
			List<Map<String, Value>> expected = List.of(row("x", outer, "count", groupInteger(1)));
			QueryEvaluationStep genericBag = groupEmissionStrategy(dataset).genericOnlyView()
					.precompile(group.clone(), nativeGroup.context);
			List<Map<String, Value>> genericRows;
			try (var rows = genericBag.evaluate(entry.bindings())) {
				genericRows = mappings(rows);
			}
			List<Map<String, Value>> selectedRows;
			try (var rows = entry.step().evaluate(entry.bindings())) {
				selectedRows = mappings(rows);
			}
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("actual-exists-count-z bagReplay expected=%s generic=%s selected=%s "
						+ "firstObservedDelta=%d firstUnobservedDelta=%d%n", expected, genericRows, selectedRows,
						observedDelta, unobservedDelta);
			}
			softly.assertThat(genericRows)
					.as("independent generic Count(z) bag under the actual domain")
					.containsExactlyElementsOf(expected);
			softly.assertThat(selectedRows)
					.as("Count(z) bag replay with the same prepared step and original entry")
					.containsExactlyElementsOf(expected);
			softly.assertThat(probe.entries).as("bag replay did not issue another EXISTS entry").hasSize(1);
			softly.assertThat(groupEntryFacts(entry.bindings(), group, nativeGroup)).isEqualTo(entry.before());
			softly.assertThat(groupEntryFacts(caller, group, null)).isEqualTo(callerBefore);
			softly.assertAll();
		}
	}

	@ParameterizedTest(name = "{0}")
	@ValueSource(strings = { "marker", "static" })
	void detachedCountZGroupDoesNotBorrowInvocationAuthority(String kind) {
		IRI subject = VF.createIRI("urn:domain-group:subject");
		IRI predicate = VF.createIRI("urn:domain-group:p");
		Value outer = literal("outer");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, outer);
		}
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			QueryEvaluationContext base = new QueryEvaluationContext.Minimal((Dataset) null);
			TripleSource triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			QueryEvaluationContext context = kind.equals("marker") ? captureDynamicContext(triples, base, outer)
					: new QueryEvaluationContext.Minimal((Dataset) null) {
						@Override
						public Set<String> getSubstitutionBindingNames() {
							return Set.of("x");
						}
					};
			Group group = countZInvocationGroup(predicate, outer);
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			QueryBindingSet caller = new QueryBindingSet();
			caller.addBinding("x", outer);
			BindingSet input = kind.equals("marker")
					? BindingFrameBindings.withSubstitutionDomain(caller, Set.of("x"), base)
					: caller;
			GroupEntryFacts callerBefore = groupEntryFacts(caller, group, null);
			GroupEntryFacts inputBefore = groupEntryFacts(input, group, null);
			assertThat(group.getParentNode()).as("the target has no evaluator invocation edge").isNull();
			assertThat(GroupInvocationBindings.prepared(group)).isNull();
			assertThat(GroupInvocationBindings.prepared(input)).isNull();
			LmdbNativeEvaluationStrategy strategy = groupEmissionStrategy(dataset);
			QueryEvaluationStep generic = strategy.genericOnlyView().precompile(group.clone(), context);
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(group, context, strategy,
					(NativeLmdbQuerySource) dataset);
			assertThat(compiled).isInstanceOf(NativeGroupStep.class);
			NativeGroupStep nativeGroup = (NativeGroupStep) compiled;
			assertThat(nativeGroup.originalExpr).isSameAs(group);
			assertThat(group.getParentNode()).isNull();
			assertThat(GroupInvocationBindings.prepared(group)).as("direct compilation did not mint metadata").isNull();
			assertThat(GroupInvocationBindings.prepared(input)).as("context and names did not mint an entry").isNull();
			assertThat(nativeGroup.invocationWitness).isNull();
			assertThat(nativeGroup.semanticEntryFallbackReason(input)).isEqualTo("groupInput");
			List<Map<String, Value>> expected = List.of(row("x", outer, "count", groupInteger(1)));
			List<Map<String, Value>> genericRows;
			try (var rows = generic.evaluate(input)) {
				genericRows = mappings(rows);
			}
			assertThat(groupEntryFacts(input, group, nativeGroup)).isEqualTo(inputBefore);
			long rawBefore = group.getLongMetricActual("nativeInvocationsActual");
			long nativeBefore = resetAttachedGroupMetrics(group);
			List<Map<String, Value>> selectedRows;
			try (var rows = compiled.evaluate(input)) {
				selectedRows = mappings(rows);
			}
			long rawAfter = group.getLongMetricActual("nativeInvocationsActual");
			long nativeDelta = Math.max(0L, rawAfter) - nativeBefore;
			String execution = group.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
			String actualPlan = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
			if (SCOPE_DIAGNOSTICS) {
				System.out.printf("detached-count-z kind=%s expected=%s generic=%s selected=%s parent=%s "
						+ "hostCapability=%s entryCapability=%s witness=%s guard=%s nativeBeforeRaw=%d "
						+ "nativeAfterRaw=%d nativeDelta=%d execution=%s actualPlan=%s%n", kind, expected, genericRows,
						selectedRows, group.getParentNode(), GroupInvocationBindings.prepared(group) != null,
						GroupInvocationBindings.prepared(input) != null, nativeGroup.invocationWitness != null,
						nativeGroup.semanticEntryFallbackReason(input), rawBefore, rawAfter, nativeDelta, execution,
						actualPlan);
			}
			assertThat(genericRows).as("independent generic detached Count(z) bag %s", kind)
					.containsExactlyElementsOf(expected);
			assertThat(selectedRows).as("unsupported origin preserves the exact Count(z) bag %s", kind)
					.containsExactlyElementsOf(expected);
			// A raw -1 means unavailable telemetry; normalize it before asserting no native invocation occurred.
			assertThat(nativeDelta).isZero();
			assertThat(execution).contains("genericFallback(groupInput)");
			assertThat(actualPlan).isNull();
			assertThat(groupEntryFacts(input, group, nativeGroup)).isEqualTo(inputBefore);
			assertThat(groupEntryFacts(caller, group, null)).isEqualTo(callerBefore);
		}
	}

	private static Group countZInvocationGroup(IRI predicate, Value outer) {
		LeftJoin optional = new LeftJoin(values("o", literal("o")), values("z", literal("z")),
				new Compare(Var.of("x"), new ValueConstant(outer), Compare.CompareOp.EQ));
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p", predicate, false, true), Var.of("v"));
		Group group = new Group(new Join(optional, pattern), List.of("x"));
		group.addGroupElement(new GroupElem("count", new Count(Var.of("z"), false)));
		return group;
	}

