	private static DeepValuesWork exerciseNestedValues(int size, LmdbNativeEvaluationStrategy strategy,
			QueryEvaluationContext context) {
		DeepValuesProbe probe = new DeepValuesProbe();
		Group group = nestedValuesGroup(size, probe);
		Group genericGroup = nestedValuesGroup(size, new DeepValuesProbe());
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		QueryEvaluationStep generic = strategy.genericOnlyView().precompile(genericGroup, context);
		int beforeHeaders = probe.headerNames.get();
		QueryEvaluationStep compiled = NativeValuesElisions.withPreparationDiagnostics(
				() -> strategy.precompile(group, context));
		int preparedHeaders = probe.headerNames.get() - beforeHeaders;
		NativeGroupStep nativeGroup = BindingFrameBindings.unframedCapability(compiled, NativeGroupStep.class);
		assertThat(nativeGroup).as("the actual prepared aggregate is native for %s VALUES", size).isNotNull();
		assertThat(nativeGroup.valuesRequirement.witnesses()).hasSize(size);
		NativeValuesElisions.PreparationWork proof = nativeGroup.valuesRequirement.preparationWork();
		assertThat(proof).isNotNull();
		assertThat(proof.distinctNames()).isEqualTo(size);
		assertThat(proof.headerDemand()).isEqualTo(size);
		assertThat(proof.capturedRows()).isEqualTo(size);
		assertThat(proof.inputEdges()).isPositive();
		assertThat(proof.inputTransfers()).isPositive();
		assertThat(nativeGroup.nativePhysicalPlan()).contains("Pattern(").doesNotContain("Values(rows=");

		QueryBindingSet matching = new QueryBindingSet();
		for (int i = 0; i < size; i++) {
			matching.addBinding("unused" + i, GROUP_A);
		}
		QueryBindingSet early = new QueryBindingSet();
		early.addBinding("unused0", GROUP_C);
		QueryBindingSet middle = new QueryBindingSet();
		middle.addBinding("unused" + size / 2, GROUP_C);
		QueryBindingSet late = new QueryBindingSet();
		late.addBinding("unused" + (size - 1), GROUP_C);
		List<BindingSet> entries = List.of(EmptyBindingSet.getInstance(), matching, early, middle, late);
		for (int index = 0; index < entries.size(); index++) {
			BindingSet input = entries.get(index);
			Map<String, Value> expected = new TreeMap<>();
			for (String name : input.getBindingNames()) {
				expected.put(name, input.getValue(name));
			}
			expected.put("count", groupInteger(index < 2 ? 2 : 0));
			List<BindingSet> genericRows;
			try (var rows = generic.evaluate(input)) {
				genericRows = drainGroupRdf(rows);
			}
			group.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
			group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
			long before = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"));
			List<BindingSet> nativeRows;
			try (var rows = compiled.evaluate(input)) {
				nativeRows = drainGroupRdf(rows);
			}
			assertThat(groupMaps(genericRows)).as("generic size %s entry %s", size, index).containsExactly(expected);
			assertThat(groupMaps(nativeRows)).as("native size %s entry %s", size, index).containsExactly(expected);
			if (index < 2) {
				assertThat(group.getLongMetricActual("nativeInvocationsActual") - before).isPositive();
				assertThat(group.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH))
						.isNotBlank()
						.doesNotContain("genericFallback");
				String runtime = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
				assertThat(runtime).contains("status: COMPLETED", "opens: 1");
				int actualStart = runtime.indexOf("    actualOrder:");
				int actualEnd = runtime.indexOf("\n    janino:", actualStart);
				assertThat(actualStart).isGreaterThanOrEqualTo(0);
				assertThat(actualEnd).isGreaterThan(actualStart);
				assertThat(runtime.substring(actualStart, actualEnd)).contains("Pattern(")
						.doesNotContain("<not opened", "Values(rows=", "GenericEvalPlan(");
			}
		}
		return new DeepValuesWork(size, preparedHeaders, probe.headerNames.get() - beforeHeaders,
				probe.sourceOpenings.get(), probe.sourceRows.get(), proof);
	}

	private record DeepValuesWork(int size, int preparationHeaderNames, int totalHeaderNames,
			int sourceOpenings, int sourceRows, NativeValuesElisions.PreparationWork proof) {
	}

	private static final class DeepValuesProbe {
		final AtomicInteger headerNames = new AtomicInteger();
		final AtomicInteger sourceOpenings = new AtomicInteger();
		final AtomicInteger sourceRows = new AtomicInteger();
	}

	@SuppressWarnings("deprecation") // The legacy header aliases this instrumented Set by contract.
	private static Group nestedValuesGroup(int size, DeepValuesProbe probe) {
		TupleExpr root = groupEmissionRelation(false);
		for (int i = 0; i < size; i++) {
			String name = "unused" + i;
			BindingSetAssignment values = new BindingSetAssignment();
			values.setBindingNames(new AbstractSet<>() {
				@Override
				public Iterator<String> iterator() {
					Iterator<String> nameIterator = Set.of(name).iterator();
					return new Iterator<>() {
						@Override
						public boolean hasNext() {
							return nameIterator.hasNext();
						}

						@Override
						public String next() {
							probe.headerNames.incrementAndGet();
							return nameIterator.next();
						}
					};
				}

				@Override
				public int size() {
					return 1;
				}
			});
			AtomicInteger opened = new AtomicInteger();
			values.setBindingSets(() -> {
				if (opened.incrementAndGet() != 1) {
					throw new IllegalStateException("VALUES source opened more than once: " + name);
				}
				probe.sourceOpenings.incrementAndGet();
				QueryBindingSet row = new QueryBindingSet();
				row.addBinding(name, GROUP_A);
				return new Iterator<>() {
					private boolean available = true;

					@Override
					public boolean hasNext() {
						return available;
					}

					@Override
					public BindingSet next() {
						if (!available) {
							throw new NoSuchElementException();
						}
						available = false;
						probe.sourceRows.incrementAndGet();
						return row;
					}
				};
			});
			root = new Join(root, values);
		}
		Group group = new Group(root);
		group.addGroupElement(new GroupElem("count", new Count(Var.of("e"), true)));
		return group;
	}

