	@Test
	void spilledFrameRetainsIndependentParentReplayDomain() throws IOException {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope outerOwner = new BindingFrameBindings.Scope();
		BindingFrameBindings.Scope innerOwner = new BindingFrameBindings.Scope();
		IRI graph = VF.createIRI("urn:frame:graph");
		MutableBindingSet base = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
		QueryBindingSet outerProbe = new QueryBindingSet();
		outerProbe.addBinding("outer", literal("outer"));
		QueryBindingSet innerProbe = new QueryBindingSet();
		innerProbe.addBinding("inner", literal("inner"));
		try (BindingFrameReplay.Invocation outer = new BindingFrameReplay.Invocation(() -> null, null);
				BindingFrameReplay.Invocation inner = new BindingFrameReplay.Invocation(() -> null, null);
				NativeExecutionContext execution = new NativeExecutionContext();
				NativeResultFrameCodec codec = new NativeResultFrameCodec(execution.memoryLedger(),
						execution.cancellation());
				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
				DataOutputStream output = new DataOutputStream(bytes)) {
			BindingSet parent = BindingFrameBindings.push(outerOwner, base, outerProbe, context, outer.root);
			BindingSet child = BindingFrameBindings.push(innerOwner, parent, innerProbe, context, inner.root);
			assertThat(BindingFrameReplay.domain(child)).isSameAs(inner.root);
			assertThat(BindingFrameReplay.domain(BindingFrameBindings.pop(innerOwner, child, context)))
					.isSameAs(outer.root);
			NativeResultRow.Schema schema = new NativeResultRow.Schema("g");
			codec.write(output, NativeResultRow.fromBindingSet(schema, child));
			output.flush();
			try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				BindingSet restored = codec.read(input, schema, new NativeResultCell[] { NativeResultCell.term(graph) },
						execution.cancellation()).toBindingSet();
				assertThat(GraphFrameBindings.isSupplied(restored, "g")).isTrue();
				assertThat(BindingFrameBindings.probeValue(restored, "inner")).isEqualTo(literal("inner"));
				assertThat(BindingFrameReplay.domain(restored)).isSameAs(inner.root);
				BindingSet restoredParent = BindingFrameBindings.pop(innerOwner, restored, context);
				assertThat(BindingFrameBindings.probeValue(restoredParent, "outer")).isEqualTo(literal("outer"));
				assertThat(BindingFrameReplay.domain(restoredParent)).isSameAs(outer.root);
				assertThat(BindingFrameBindings.hasFrame(BindingFrameBindings.pop(outerOwner, restoredParent, context)))
						.isFalse();
			}
			try (NativeResultReplay replay = new NativeResultReplay(schema, execution, execution.cancellation(),
					execution.memoryLedger(), 12L << 10)) {
				for (int index = 0; index < 40; index++) {
					replay.append(NativeResultRow.fromBindingSet(schema, child));
				}
				replay.finish();
				assertThat(replay.spilled()).isTrue();
				try (NativeResultCursor first = replay.cursor(); NativeResultCursor second = replay.cursor()) {
					replay.close();
					BindingSet firstRow = first.next().toBindingSet();
					assertThat(BindingFrameReplay.domain(firstRow)).isSameAs(inner.root);
					assertThat(BindingFrameReplay.domain(BindingFrameBindings.pop(innerOwner, firstRow, context)))
							.isSameAs(outer.root);
					first.close();
					BindingSet secondRow = second.next().toBindingSet();
					assertThat(GraphFrameBindings.isSupplied(secondRow, "g")).isTrue();
					assertThat(BindingFrameReplay.domain(secondRow)).isSameAs(inner.root);
					assertThat(BindingFrameReplay.domain(BindingFrameBindings.pop(innerOwner, secondRow, context)))
							.isSameAs(outer.root);
				}
			}
		}
	}

	@Test
	void deepSpilledFramePreservesOwnersRegistriesAndProvenanceForIndependentReaders() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		IRI graph = VF.createIRI("urn:frame:deep-graph");
		RepositoryBNode repositoryNode = RepositoryBNode.fromNegotiatedResult("wire", "raw", true);
		RemoteBNode remoteNode = (RemoteBNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF,
				new Object(), true).map(VF.createBNode("remote"));
		List<BindingFrameBindings.Scope> owners = new ArrayList<>();
		NativeResultRow.Schema schema = new NativeResultRow.Schema("g");
		try (BindingFrameReplay.Invocation outer = new BindingFrameReplay.Invocation(() -> null, null);
				BindingFrameReplay.Invocation inner = new BindingFrameReplay.Invocation(() -> null, null);
				NativeExecutionContext execution = new NativeExecutionContext()) {
			BindingSet framed = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
			for (int index = 0; index < 10_000; index++) {
				BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
				owners.add(owner);
				QueryBindingSet probe = new QueryBindingSet();
				Value value = index == 0 ? repositoryNode : index == 9_999 ? remoteNode : VF.createLiteral(index);
				probe.addBinding("probe", value);
				framed = BindingFrameBindings.push(owner, framed, probe, context,
						index < 5_000 ? outer.root : inner.root);
			}
			try (NativeResultReplay replay = new NativeResultReplay(schema, execution, execution.cancellation(),
					execution.memoryLedger(), 12L << 10)) {
				replay.append(NativeResultRow.fromBindingSet(schema, framed));
				replay.finish();
				assertThat(replay.spilled()).isTrue();
				try (NativeResultCursor first = replay.cursor(); NativeResultCursor second = replay.cursor()) {
					replay.close();
					assertDeepSpilledFrame(first.next().toBindingSet(), owners, outer.root, inner.root,
							repositoryNode, remoteNode, graph, context);
					assertThat(first.next()).isNull();
					first.close();
					assertDeepSpilledFrame(second.next().toBindingSet(), owners, outer.root, inner.root,
							repositoryNode, remoteNode, graph, context);
					assertThat(second.next()).isNull();
				}
			}
		}
	}

	private static void assertDeepSpilledFrame(BindingSet row, List<BindingFrameBindings.Scope> owners,
			BindingFrameReplay.Domain outer, BindingFrameReplay.Domain inner, RepositoryBNode repositoryNode,
			RemoteBNode remoteNode, IRI graph, QueryEvaluationContext context) {
		assertThat(row.getValue("g")).isEqualTo(graph);
		assertThat(GraphFrameBindings.isSupplied(row, "g")).isTrue();
		for (int index = owners.size() - 1; index >= 0; index--) {
			Value probe = BindingFrameBindings.probeValue(row, "probe");
			if (index == 9_999) {
				assertThat(probe).isInstanceOf(RemoteBNode.class);
				assertThat(RemoteBNode.sameTrustedIdentity(remoteNode, (RemoteBNode) probe)).isTrue();
			} else if (index == 0) {
				assertThat(probe).isSameAs(repositoryNode);
				assertThat(((RepositoryBNode) probe).isReference()).isTrue();
			} else {
				assertThat(probe).as("probe %s", index).isEqualTo(VF.createLiteral(index));
			}
			assertThat(BindingFrameReplay.domain(row)).as("registry %s", index)
					.isSameAs(index < 5_000 ? outer : inner);
			row = BindingFrameBindings.pop(owners.get(index), row, context);
		}
		assertThat(BindingFrameBindings.hasFrame(row)).isFalse();
	}

