			TupleExpr fragment = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
					"SELECT ?s ?v WHERE { ?s <urn:frame:predicate> ?v }", null).getTupleExpr();
			QueryEvaluationStep compiled = strategy.genericOnlyView().precompile(fragment.clone(), context);
