	@ParameterizedTest(name = "spill={0}")
	@ValueSource(booleans = { false, true })
	void physicalResultReplayRetainsEachRowsFrames(boolean spill) {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		NativeResultRow.Schema schema = new NativeResultRow.Schema("g", "value");
		int count = spill ? 40 : 2;
		try (NativeExecutionContext execution = new NativeExecutionContext();
				NativeResultReplay replay = new NativeResultReplay(schema, execution, execution.cancellation(),
						execution.memoryLedger(), 12L << 10)) {
			for (int index = 0; index < count; index++) {
				replay.append(NativeResultRow.fromBindingSet(schema, framedReplayRow(owner, context, index)));
			}
			replay.finish();
			assertThat(replay.spilled()).isEqualTo(spill);
			try (NativeResultCursor first = replay.cursor(); NativeResultCursor second = replay.cursor()) {
				for (int index = 0; index < count; index++) {
					assertReplayFrames(first.next().toBindingSet(), owner, context, index);
					assertReplayFrames(second.next().toBindingSet(), owner, context, index);
				}
				assertThat(first.next()).isNull();
				assertThat(second.next()).isNull();
			}
		}
	}

	@ParameterizedTest(name = "spill={0}")
	@ValueSource(booleans = { false, true })
	void lazyPhysicalReplayRetainsEachRowsFrames(boolean spill) {
		String property = NativeCountGroupStore.MAX_BYTES_PROPERTY;
		String old = System.getProperty(property);
		System.setProperty(property, spill ? "16384" : "65536");
		long spills = NativeLazyResultReplay.SPILLS.get();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		int count = spill ? 40 : 2;
		try (NativeExecutionContext execution = new NativeExecutionContext()) {
			NativeResultRow.Schema schema = new NativeResultRow.Schema("g", "value");
			List<NativeResultRow> input = new ArrayList<>();
			for (int index = 0; index < count; index++) {
				input.add(NativeResultRow.fromBindingSet(schema, framedReplayRow(owner, context, index)));
			}
			NativeResultCursor producer = new NativeResultCursor() {
				private int position;

				@Override
				public NativeResultRow next() {
					return position < input.size() ? input.get(position++) : null;
				}

				@Override
				public NativeCancellationToken cancellation() {
					return execution.cancellation();
				}

				@Override
				public NativeExecutionContext executionContext() {
					return execution;
				}

				@Override
				public void close() {
				}
			};
			try (NativeLazyResultReplay replay = new NativeLazyResultReplay(new String[] { "g", "value" }, execution,
					execution.cancellation(), producer);
					NativeResultCursor first = replay.cursor(execution.cancellation());
					NativeResultCursor second = replay.cursor(execution.cancellation())) {
				List<BindingSet> firstRows = new ArrayList<>();
				List<BindingSet> secondRows = new ArrayList<>();
				for (int index = 0; index < count; index++) {
					firstRows.add(first.next().toBindingSet());
				}
				for (int index = 0; index < count; index++) {
					secondRows.add(second.next().toBindingSet());
				}
				assertThat(first.next()).isNull();
				assertThat(second.next()).isNull();
				assertThat(NativeLazyResultReplay.SPILLS.get() > spills).isEqualTo(spill);
				for (int index = 0; index < count; index++) {
					assertReplayFrames(firstRows.get(index), owner, context, index);
					assertReplayFrames(secondRows.get(index), owner, context, index);
				}
			}
		} finally {
			if (old == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, old);
			}
		}
	}

	@ParameterizedTest(name = "lazy={0}")
	@ValueSource(booleans = { false, true })
	void spilledPhysicalReplayRestoresDistinctLiveDomains(boolean lazy) {
		String property = NativeCountGroupStore.MAX_BYTES_PROPERTY;
		String old = System.getProperty(property);
		System.setProperty(property, "16384");
		long spills = NativeLazyResultReplay.SPILLS.get();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation first = new BindingFrameReplay.Invocation(() -> null, null);
				BindingFrameReplay.Invocation nested = new BindingFrameReplay.Invocation(() -> null, first.root);
				BindingFrameReplay.Invocation second = new BindingFrameReplay.Invocation(() -> null, null);
				NativeExecutionContext execution = new NativeExecutionContext()) {
			BindingFrameReplay.Domain[] domains = { first.root, nested.root, second.root };
			NativeResultRow.Schema schema = new NativeResultRow.Schema("g", "value");
			List<NativeResultRow> input = new ArrayList<>();
			for (int index = 0; index < 42; index++) {
				BindingSet row = BindingFrameBindings.withReplay(framedReplayRow(owner, context, index),
						domains[index % domains.length], context);
				input.add(NativeResultRow.fromBindingSet(schema, row));
			}
			if (lazy) {
				NativeResultCursor producer = new NativeResultCursor() {
					private int position;

					@Override
					public NativeResultRow next() {
						return position < input.size() ? input.get(position++) : null;
					}

					@Override
					public NativeCancellationToken cancellation() {
						return execution.cancellation();
					}

					@Override
					public NativeExecutionContext executionContext() {
						return execution;
					}

					@Override
					public void close() {
					}
				};
				try (NativeLazyResultReplay replay = new NativeLazyResultReplay(new String[] { "g", "value" },
						execution, execution.cancellation(), producer);
						NativeResultCursor primary = replay.cursor(execution.cancellation());
						NativeResultCursor repeated = replay.cursor(execution.cancellation())) {
					assertReplayDomains(primary, owner, context, domains, input.size());
					assertThat(NativeLazyResultReplay.SPILLS.get()).isGreaterThan(spills);
					assertReplayDomains(repeated, owner, context, domains, input.size());
				}
			} else {
				try (NativeResultReplay replay = new NativeResultReplay(schema, execution, execution.cancellation(),
						execution.memoryLedger(), 12L << 10)) {
					input.forEach(replay::append);
					replay.finish();
					assertThat(replay.spilled()).isTrue();
					try (NativeResultCursor primary = replay.cursor(); NativeResultCursor repeated = replay.cursor()) {
						assertReplayDomains(primary, owner, context, domains, input.size());
						assertReplayDomains(repeated, owner, context, domains, input.size());
					}
				}
			}
		} finally {
			if (old == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, old);
			}
		}
	}

	private static void assertReplayDomains(NativeResultCursor cursor, BindingFrameBindings.Scope owner,
			QueryEvaluationContext context, BindingFrameReplay.Domain[] domains, int count) {
		for (int index = 0; index < count; index++) {
			BindingSet row = cursor.next().toBindingSet();
			assertReplayFrames(row, owner, context, index);
			assertThat(BindingFrameReplay.domain(row)).as("live replay domain for row %s", index)
					.isSameAs(domains[index % domains.length]);
		}
		assertThat(cursor.next()).isNull();
	}

	@ParameterizedTest(name = "lazy={0}, metadata={1}")
	@MethodSource("hiddenMetadataCases")
	void physicalReplayAccountsForHiddenFramePayload(boolean lazy, String metadata) {
		String property = NativeCountGroupStore.MAX_BYTES_PROPERTY;
		String old = System.getProperty(property);
		System.setProperty(property, "16384");
		long spills = NativeLazyResultReplay.SPILLS.get();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		Value largeSeed = literal(metadata.equals("probe") ? "seed".repeat(8192) : "seed");
		IRI largeGraph = VF.createIRI("urn:frame:" + "graph".repeat(8192));
		QueryBindingSet base = new QueryBindingSet();
		base.addBinding("value", literal("small"));
		if (metadata.equals("graph")) {
			GraphFrameBindings.supply(base, "g", largeGraph);
		}
		QueryBindingSet probe = new QueryBindingSet();
		probe.addBinding("hidden", largeSeed);
		BindingSet framed = BindingFrameBindings.push(owner, base, probe, context);
		NativeResultRow.Schema schema = new NativeResultRow.Schema("value");
		NativeResultRow input = NativeResultRow.fromBindingSet(schema, framed);
		try (NativeExecutionContext execution = new NativeExecutionContext()) {
			if (lazy) {
				NativeResultCursor producer = new NativeResultCursor() {
					private boolean consumed;

					@Override
					public NativeResultRow next() {
						if (consumed) {
							return null;
						}
						consumed = true;
						return input;
					}

					@Override
					public NativeCancellationToken cancellation() {
						return execution.cancellation();
					}

					@Override
					public NativeExecutionContext executionContext() {
						return execution;
					}

					@Override
					public void close() {
					}
				};
				try (NativeLazyResultReplay replay = new NativeLazyResultReplay(new String[] { "value" }, execution,
						execution.cancellation(), producer);
						NativeResultCursor rows = replay.cursor(execution.cancellation())) {
					assertThat(NativeLazyResultReplay.SPILLS.get()).isGreaterThan(spills);
					assertLargeReplayMetadata(rows.next().toBindingSet(), largeSeed, largeGraph, metadata);
					assertThat(rows.next()).isNull();
				}
			} else {
				try (NativeResultReplay replay = new NativeResultReplay(schema, execution, execution.cancellation(),
						execution.memoryLedger(), 12L << 10)) {
					replay.append(input);
					replay.finish();
					assertThat(replay.spilled()).isTrue();
					try (NativeResultCursor rows = replay.cursor()) {
						assertLargeReplayMetadata(rows.next().toBindingSet(), largeSeed, largeGraph, metadata);
						assertThat(rows.next()).isNull();
					}
				}
			}
		} finally {
			if (old == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, old);
			}
		}
	}

	private static Stream<Arguments> hiddenMetadataCases() {
		return Stream.of(Arguments.of(false, "probe"), Arguments.of(false, "graph"), Arguments.of(true, "probe"),
				Arguments.of(true, "graph"));
	}

	private static void assertLargeReplayMetadata(BindingSet row, Value largeSeed, IRI largeGraph, String metadata) {
		assertThat(BindingFrameBindings.probeValue(row, "hidden")).isEqualTo(largeSeed);
		if (metadata.equals("graph")) {
			QueryBindingSet carrier = new QueryBindingSet();
			carrier.addBinding("g", largeGraph);
			carrier.setGraphFrameBindings(GraphFrameBindings.from(row));
			assertThat(GraphFrameBindings.isSupplied(carrier, "g")).isTrue();
		}
	}

	private static BindingSet framedReplayRow(BindingFrameBindings.Scope owner, QueryEvaluationContext context,
			int index) {
		IRI graph = VF.createIRI("urn:frame:graph:" + index % 2);
		MutableBindingSet base = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
		base.setBinding("value", literal(index + "x".repeat(256)));
		QueryBindingSet probe = new QueryBindingSet();
		probe.addBinding("hidden", literal("seed:" + index));
		return BindingFrameBindings.push(owner, base, probe, context);
	}

	private static void assertReplayFrames(BindingSet row, BindingFrameBindings.Scope owner,
			QueryEvaluationContext context, int index) {
		assertThat(row.getValue("g")).isEqualTo(VF.createIRI("urn:frame:graph:" + index % 2));
		assertThat(row.getValue("value")).isEqualTo(literal(index + "x".repeat(256)));
		assertThat(GraphFrameBindings.isSupplied(row, "g")).isTrue();
		assertThat(BindingFrameBindings.probeValue(row, "hidden")).isEqualTo(literal("seed:" + index));
		assertThat(BindingFrameBindings.hasFrame(BindingFrameBindings.pop(owner, row, context))).isFalse();
	}

